package io.undertow.client.http;

import io.undertow.UndertowOptions;
import io.undertow.client.ClientCallback;
import io.undertow.client.ClientExchange;
import io.undertow.client.ClientRequest;
import io.undertow.client.UndertowClientMessages;
import io.undertow.connector.ByteBufferPool;
import io.undertow.util.Headers;
import io.undertow.util.Methods;
import io.undertow.util.Protocols;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.xnio.OptionMap;
import org.xnio.Options;
import java.nio.channels.ClosedChannelException;

import java.io.IOException;
import java.net.InetSocketAddress;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

class HttpClientConnectionTest {

    private ByteBufferPool bufferPool;
    private HttpClientTestSupport.FakeStreamConnection fakeConnection;
    private HttpClientConnection connection;

    @BeforeEach
    void setUp() {
        bufferPool = HttpClientTestSupport.newBufferPool();
        fakeConnection = new HttpClientTestSupport.FakeStreamConnection();
        connection = new HttpClientConnection(fakeConnection, OptionMap.EMPTY, bufferPool);
    }

    @AfterEach
    void tearDown() {
        bufferPool.close();
    }

    @Test
    void exposesConnectionMetadataAndCapabilities() {
        assertSame(bufferPool, connection.getBufferPool());
        assertSame(fakeConnection, connection.getConnection());
        assertTrue(connection.isOpen());
        assertFalse(connection.isUpgraded());
        assertFalse(connection.isPushSupported());
        assertFalse(connection.isMultiplexingSupported());
        assertTrue(connection.isUpgradeSupported());
        assertNull(connection.getStatistics());
        assertEquals(new InetSocketAddress("localhost", 8080), connection.getPeerAddress());
        assertEquals(new InetSocketAddress("localhost", 12345), connection.getLocalAddress());
        assertEquals(new InetSocketAddress("localhost", 8080), connection.getPeerAddress(InetSocketAddress.class));
        assertEquals(new InetSocketAddress("localhost", 12345), connection.getLocalAddress(InetSocketAddress.class));
    }

    @Test
    void delegatesOptionsToUnderlyingConnection() throws Exception {
        assertFalse(connection.supportsOption(Options.READ_TIMEOUT));

        connection.setOption(Options.READ_TIMEOUT, 2500);

        assertTrue(connection.supportsOption(Options.READ_TIMEOUT));
        assertEquals(2500, connection.getOption(Options.READ_TIMEOUT));
    }

    @Test
    void reportsStatisticsWhenEnabled() {
        HttpClientTestSupport.FakeStreamConnection statisticsConnection = new HttpClientTestSupport.FakeStreamConnection();
        OptionMap options = OptionMap.builder().set(UndertowOptions.ENABLE_STATISTICS, true).getMap();
        HttpClientConnection statisticsEnabled = new HttpClientConnection(statisticsConnection, options, bufferPool);

        assertNotNull(statisticsEnabled.getStatistics());
    }

    @Test
    void rejectsRequestWhenConnectionIsClosed() throws Exception {
        connection.close();
        RecordingCallback callback = new RecordingCallback();

        connection.sendRequest(HttpClientTestSupport.get("/"), callback);

        assertEquals(1, callback.failures);
        assertInstanceOf(ClosedChannelException.class, callback.failure);
        assertNull(callback.result);
    }

    @Test
    void rejectsRequestAfterUpgradeWasRequested() throws Exception {
        ClientRequest upgradeRequest = HttpClientTestSupport.get("/upgrade");
        upgradeRequest.getRequestHeaders().put(Headers.UPGRADE, "h2c");
        RecordingCallback first = new RecordingCallback();
        connection.sendRequest(upgradeRequest, first);
        assertEquals(1, first.completions);

        RecordingCallback second = new RecordingCallback();
        connection.sendRequest(HttpClientTestSupport.get("/next"), second);

        assertEquals(1, second.failures);
        assertEquals(UndertowClientMessages.MESSAGES.invalidConnectionState().getMessage(), second.failure.getMessage());
    }

    @Test
    void rejectsMalformedContentLength() throws Exception {
        ClientRequest request = new ClientRequest().setMethod(Methods.POST).setPath("/").setProtocol(Protocols.HTTP_1_1);
        request.getRequestHeaders().put(Headers.CONTENT_LENGTH, "not-a-number");
        RecordingCallback callback = new RecordingCallback();

        connection.sendRequest(request, callback);

        assertEquals(1, callback.failures);
        assertInstanceOf(NumberFormatException.class, callback.failure.getCause());
        assertFalse(connection.isOpen());
    }

    @Test
    void rejectsUnknownTransferEncoding() throws Exception {
        ClientRequest request = new ClientRequest().setMethod(Methods.POST).setPath("/").setProtocol(Protocols.HTTP_1_1);
        request.getRequestHeaders().put(Headers.TRANSFER_ENCODING, "gzip");
        RecordingCallback callback = new RecordingCallback();

        connection.sendRequest(request, callback);

        assertEquals(1, callback.failures);
        assertNotNull(callback.failure);
        assertTrue(callback.failure.getMessage().contains("gzip"), callback.failure.getMessage());
        assertFalse(connection.isOpen());
    }

    @Test
    void finishesBodilessRequestImmediately() throws Exception {
        RecordingCallback callback = new RecordingCallback();

        connection.sendRequest(HttpClientTestSupport.get("/"), callback);

        assertEquals(1, callback.completions);
        assertTrue(((HttpClientExchange) callback.result).isRequestDataSent());
    }

    @Test
    void doesNotFinishRequestWithBodyUntilBodyIsSent() throws Exception {
        ClientRequest request = new ClientRequest().setMethod(Methods.POST).setPath("/").setProtocol(Protocols.HTTP_1_1);
        request.getRequestHeaders().put(Headers.CONTENT_LENGTH, "5");
        RecordingCallback callback = new RecordingCallback();

        connection.sendRequest(request, callback);

        assertEquals(1, callback.completions);
        assertFalse(((HttpClientExchange) callback.result).isRequestDataSent());
    }

    @Test
    void finishesZeroLengthRequestBodyImmediately() throws Exception {
        ClientRequest request = new ClientRequest().setMethod(Methods.POST).setPath("/").setProtocol(Protocols.HTTP_1_1);
        request.getRequestHeaders().put(Headers.CONTENT_LENGTH, "0");
        RecordingCallback callback = new RecordingCallback();

        connection.sendRequest(request, callback);

        assertEquals(1, callback.completions);
        assertTrue(((HttpClientExchange) callback.result).isRequestDataSent());
    }

    @Test
    void advertisesCleartextHttp2UpgradeOnFirstRequestWhenEnabled() throws Exception {
        HttpClientTestSupport.FakeStreamConnection h2Connection = new HttpClientTestSupport.FakeStreamConnection();
        OptionMap options = OptionMap.builder().set(UndertowOptions.ENABLE_HTTP2, true).getMap();
        HttpClientConnection h2Enabled = new HttpClientConnection(h2Connection, options, bufferPool);
        ClientRequest request = HttpClientTestSupport.get("/h2");
        RecordingCallback callback = new RecordingCallback();

        h2Enabled.sendRequest(request, callback);

        assertEquals(1, callback.completions);
        assertEquals("h2c", request.getRequestHeaders().getFirst(Headers.UPGRADE));
        assertNotNull(request.getRequestHeaders().getFirst("HTTP2-Settings"));
        assertNotNull(request.getRequestHeaders().getFirst(Headers.CONNECTION));
        assertTrue(h2Enabled.isUpgraded());
    }

    @Test
    void queuesSecondRequestUntilFirstExchangeCompletes() throws Exception {
        ClientRequest firstRequest = new ClientRequest().setMethod(Methods.POST).setPath("/first").setProtocol(Protocols.HTTP_1_1);
        firstRequest.getRequestHeaders().put(Headers.CONTENT_LENGTH, "5");
        RecordingCallback first = new RecordingCallback();
        connection.sendRequest(firstRequest, first);
        assertEquals(1, first.completions);
        HttpClientExchange firstExchange = (HttpClientExchange) first.result;

        RecordingCallback second = new RecordingCallback();
        connection.sendRequest(HttpClientTestSupport.get("/second"), second);
        assertEquals(0, second.completions);

        firstExchange.terminateRequest();
        firstExchange.terminateResponse();

        assertEquals(1, second.completions);
        assertEquals("/second", ((HttpClientExchange) second.result).getRequest().getPath());
    }

    @Test
    void closesUnderlyingConnectionAfterHttp10ExchangeCompletes() throws Exception {
        ClientRequest request = new ClientRequest().setMethod(Methods.GET).setPath("/").setProtocol(Protocols.HTTP_1_0);
        RecordingCallback callback = new RecordingCallback();
        connection.sendRequest(request, callback);
        assertEquals(1, callback.completions);

        ((HttpClientExchange) callback.result).terminateResponse();

        assertFalse(connection.isOpen());
        assertFalse(fakeConnection.isOpen());
    }

    @Test
    void notifiesCloseListenersAndFailsPendingRequestsWhenUnderlyingConnectionCloses() throws Exception {
        ClientRequest firstRequest = new ClientRequest().setMethod(Methods.POST).setPath("/first").setProtocol(Protocols.HTTP_1_1);
        firstRequest.getRequestHeaders().put(Headers.CONTENT_LENGTH, "5");
        RecordingCallback first = new RecordingCallback();
        connection.sendRequest(firstRequest, first);
        HttpClientExchange firstExchange = (HttpClientExchange) first.result;
        RecordingCallback responseCallback = new RecordingCallback();
        firstExchange.setResponseListener(responseCallback);

        RecordingCallback second = new RecordingCallback();
        connection.sendRequest(HttpClientTestSupport.get("/second"), second);
        final int[] closeNotifications = new int[1];
        connection.addCloseListener(value -> closeNotifications[0]++);

        fakeConnection.fireClose();

        assertEquals(1, closeNotifications[0]);
        assertEquals(1, second.failures);
        assertInstanceOf(ClosedChannelException.class, second.failure);
        assertEquals(1, responseCallback.failures);
        assertInstanceOf(ClosedChannelException.class, responseCallback.failure);
        assertFalse(connection.isOpen());
    }

    @Test
    void performUpgradeReturnsUnderlyingConnectionAndBlocksNewRequests() throws Exception {
        assertSame(fakeConnection, connection.performUpgrade());
        assertTrue(connection.isUpgraded());

        RecordingCallback callback = new RecordingCallback();
        connection.sendRequest(HttpClientTestSupport.get("/after-upgrade"), callback);

        assertEquals(1, callback.failures);
        assertNotNull(callback.failure);
    }

    private static final class RecordingCallback implements ClientCallback<ClientExchange> {

        private ClientExchange result;
        private IOException failure;
        private int completions;
        private int failures;

        @Override
        public void completed(final ClientExchange value) {
            completions++;
            result = value;
        }

        @Override
        public void failed(final IOException exception) {
            failures++;
            failure = exception;
        }
    }
}
