package io.undertow.client.http;

import io.undertow.UndertowMessages;
import io.undertow.client.ALPNClientSelector;
import io.undertow.client.ClientCallback;
import io.undertow.client.ClientConnection;
import io.undertow.connector.ByteBufferPool;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.xnio.OptionMap;
import org.xnio.XnioIoThread;
import org.xnio.XnioWorker;

import java.io.IOException;
import java.net.URI;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;

class HttpClientProviderTest {

    private ByteBufferPool bufferPool;
    private HttpClientProvider provider;

    @BeforeEach
    void setUp() {
        bufferPool = HttpClientTestSupport.newBufferPool();
        provider = new HttpClientProvider();
    }

    @AfterEach
    void tearDown() {
        bufferPool.close();
    }

    @Test
    void handlesHttpAndHttpsSchemes() {
        assertEquals(Set.of("http", "https"), provider.handlesSchemes());
    }

    @Test
    void failsHttpsConnectionOnWorkerOverloadWithoutSsl() {
        RecordingCallback callback = new RecordingCallback();

        provider.connect(callback, URI.create("https://example.com/"), (XnioWorker) null, null, bufferPool, OptionMap.EMPTY);

        assertEquals(1, callback.failures);
        assertNull(callback.result);
        assertEquals(UndertowMessages.MESSAGES.sslWasNull().getMessage(), callback.failure.getMessage());
    }

    @Test
    void failsHttpsConnectionOnIoThreadOverloadWithoutSsl() {
        RecordingCallback callback = new RecordingCallback();

        provider.connect(callback, URI.create("https://example.com:8443/"), (XnioIoThread) null, null, bufferPool, OptionMap.EMPTY);

        assertEquals(1, callback.failures);
        assertNull(callback.result);
        assertEquals(UndertowMessages.MESSAGES.sslWasNull().getMessage(), callback.failure.getMessage());
    }

    @Test
    void advertisesHttp11OverAlpn() {
        RecordingCallback callback = new RecordingCallback();

        ALPNClientSelector.ALPNProtocol protocol = HttpClientProvider.alpnProtocol(
                callback, URI.create("https://example.com/"), bufferPool, OptionMap.EMPTY);

        assertNotNull(protocol);
        assertEquals("http/1.1", protocol.getProtocol());
        assertNotNull(protocol.getSelected());
    }

    private static final class RecordingCallback implements ClientCallback<ClientConnection> {

        private ClientConnection result;
        private IOException failure;
        private int completions;
        private int failures;

        @Override
        public void completed(final ClientConnection value) {
            completions++;
            result = value;
        }

        @Override
        public void failed(final IOException exception) {
            failures++;
            failure = exception;
        }
    }
}
