/**
 * Lightweight substitutes for the XNIO conduits and connection used by the HTTP client.
 */
final class HttpClientTestSupport {

    private HttpClientTestSupport() {
    }

    static ByteBufferPool newBufferPool() {
        return new DefaultByteBufferPool(false, 1024);
    }

    static ClientRequest get(String path) {
        return new ClientRequest().setMethod(Methods.GET).setPath(path).setProtocol(Protocols.HTTP_1_1);
    }

    static HttpClientExchange newExchange(final HttpClientConnection connection, final ClientRequest request) {
        return new HttpClientExchange(null, request, connection);
    }

    static final class RecordingSinkConduit implements StreamSinkConduit {

        private final ByteArrayOutputStream output = new ByteArrayOutputStream();
        private int writesReturningZero;
        private int terminateWritesCalls;
        private int truncateWritesCalls;
        private boolean flushed;
        private XnioWorker worker;

        void failWritesWithZero(final int count) {
            writesReturningZero = count;
        }

        String writtenAscii() {
            return output.toString(StandardCharsets.US_ASCII);
        }

        byte[] writtenBytes() {
            return output.toByteArray();
        }

        int terminateWritesCalls() {
            return terminateWritesCalls;
        }

        int truncateWritesCalls() {
            return truncateWritesCalls;
        }

        boolean flushed() {
            return flushed;
        }

        void setWorker(final XnioWorker worker) {
            this.worker = worker;
        }

        @Override
        public int write(final ByteBuffer src) {
            if (writesReturningZero > 0) {
                writesReturningZero--;
                return 0;
            }
            int length = src.remaining();
            byte[] bytes = new byte[length];
            src.get(bytes);
            output.write(bytes, 0, length);
            return length;
        }

        @Override
        public long write(final ByteBuffer[] srcs, final int offset, final int length) {
            if (writesReturningZero > 0) {
                writesReturningZero--;
                return 0;
            }
            long total = 0;
            for (int i = offset; i < offset + length; i++) {
                total += write(srcs[i]);
            }
            return total;
        }

        @Override
        public int writeFinal(final ByteBuffer src) {
            return write(src);
        }

        @Override
        public long writeFinal(final ByteBuffer[] srcs, final int offset, final int length) {
            return write(srcs, offset, length);
        }

        @Override
        public long transferFrom(final FileChannel src, final long position, final long count) {
            return 0;
        }

        @Override
        public long transferFrom(final StreamSourceChannel source, final long count, final ByteBuffer throughBuffer) {
            return 0;
        }

        @Override
        public void terminateWrites() {
            terminateWritesCalls++;
        }

        @Override
        public boolean isWriteShutdown() {
            return false;
        }

        @Override
        public void resumeWrites() {
        }

        @Override
        public void suspendWrites() {
        }

        @Override
        public void wakeupWrites() {
        }

        @Override
        public boolean isWriteResumed() {
            return false;
        }

        @Override
        public void awaitWritable() {
        }

        @Override
        public void awaitWritable(final long time, final TimeUnit timeUnit) {
        }

        @Override
        public XnioIoThread getWriteThread() {
            return null;
        }

        @Override
        public void setWriteReadyHandler(final WriteReadyHandler handler) {
        }

        @Override
        public void truncateWrites() {
            truncateWritesCalls++;
        }

        @Override
        public boolean flush() {
            flushed = true;
            return true;
        }

        @Override
        public XnioWorker getWorker() {
            return worker;
        }
    }

    static final class NoOpSourceConduit implements StreamSourceConduit {

        @Override
        public long transferTo(final long position, final long count, final FileChannel target) {
            return 0;
        }

        @Override
        public long transferTo(final long count, final ByteBuffer throughBuffer, final StreamSinkChannel target) {
            return 0;
        }

        @Override
        public int read(final ByteBuffer dst) {
            return -1;
        }

        @Override
        public long read(final ByteBuffer[] dsts, final int offset, final int length) {
            return -1;
        }

        @Override
        public void terminateReads() {
        }

        @Override
        public boolean isReadShutdown() {
            return false;
        }

        @Override
        public void resumeReads() {
        }

        @Override
        public void suspendReads() {
        }

        @Override
        public void wakeupReads() {
        }

        @Override
        public boolean isReadResumed() {
            return false;
        }

        @Override
        public void awaitReadable() {
        }

        @Override
        public void awaitReadable(final long time, final TimeUnit timeUnit) {
        }

        @Override
        public XnioIoThread getReadThread() {
            return null;
        }

        @Override
        public void setReadReadyHandler(final ReadReadyHandler handler) {
        }

        @Override
        public XnioWorker getWorker() {
            return null;
        }
    }

    static final class FakeStreamConnection extends StreamConnection {

        private final Map<Option<?>, Object> options = new HashMap<>();
        private final ChannelListener.SimpleSetter<StreamConnection> closeSetter = new ChannelListener.SimpleSetter<>();
        private final RecordingSinkConduit sinkConduit = new RecordingSinkConduit();
        private final ConduitStreamSinkChannel sinkChannel;
        private final ConduitStreamSourceChannel sourceChannel;
        private boolean open = true;

        FakeStreamConnection() {
            super(null);
            sinkChannel = new ConduitStreamSinkChannel(this, sinkConduit);
            sourceChannel = new ConduitStreamSourceChannel(this, new NoOpSourceConduit());
        }

        RecordingSinkConduit getRecordingSink() {
            return sinkConduit;
        }

        void fireClose() {
            open = false;
            ChannelListener<? super StreamConnection> listener = closeSetter.get();
            if (listener != null) {
                listener.handleEvent(this);
            }
        }

        @Override
        public ConduitStreamSinkChannel getSinkChannel() {
            return sinkChannel;
        }

        @Override
        public ConduitStreamSourceChannel getSourceChannel() {
            return sourceChannel;
        }

        @Override
        public ChannelListener.Setter<? extends StreamConnection> getCloseSetter() {
            return closeSetter;
        }

        @Override
        public SocketAddress getPeerAddress() {
            return new InetSocketAddress("localhost", 8080);
        }

        @Override
        public SocketAddress getLocalAddress() {
            return new InetSocketAddress("localhost", 12345);
        }

        @Override
        public boolean isOpen() {
            return open;
        }

        @Override
        public boolean supportsOption(final Option<?> option) {
            return options.containsKey(option);
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T getOption(final Option<T> option) throws IOException {
            return (T) options.get(option);
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T setOption(final Option<T> option, final T value) throws IllegalArgumentException, IOException {
            return (T) options.put(option, value);
        }

        @Override
        protected void notifyReadClosed() {
        }

        @Override
        protected void notifyWriteClosed() {
        }

        @Override
        protected void closeAction() {
            open = false;
        }

        void invokeCloseListener() {
            fireClose();
        }
    }

    static final class RecordingHttpClientConnection extends HttpClientConnection {

        private int requestDataSentCalls;
        private int exchangeDoneCalls;

        RecordingHttpClientConnection(final StreamConnection connection, final OptionMap options, final ByteBufferPool bufferPool) {
            super(connection, options, bufferPool);
        }

        @Override
        public void requestDataSent() {
            requestDataSentCalls++;
            super.requestDataSent();
        }

        @Override
        public void exchangeDone() {
            exchangeDoneCalls++;
            super.exchangeDone();
        }

        int requestDataSentCalls() {
            return requestDataSentCalls;
        }

        int exchangeDoneCalls() {
            return exchangeDoneCalls;
        }
    }
}
