package io.undertow.client.http;

import io.undertow.client.ClientResponse;
import io.undertow.util.Headers;
import io.undertow.util.Protocols;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;

class HttpResponseBuilderTest {

    @Test
    void startsWithoutStatusCodeProtocolOrReasonPhrase() {
        HttpResponseBuilder builder = new HttpResponseBuilder();

        assertEquals(0, builder.getStatusCode());
        assertNull(builder.getProtocol());
        assertNull(builder.getReasonPhrase());
        assertEquals(0, builder.getResponseHeaders().size());
    }

    @Test
    void buildsResponseFromConfiguredState() {
        HttpResponseBuilder builder = new HttpResponseBuilder();
        builder.setStatusCode(201);
        builder.setReasonPhrase("Created");
        builder.setProtocol(Protocols.HTTP_1_1);
        builder.getResponseHeaders().put(Headers.CONTENT_TYPE, "application/json");

        ClientResponse response = builder.build();

        assertEquals(201, response.getResponseCode());
        assertEquals("Created", response.getStatus());
        assertEquals(Protocols.HTTP_1_1, response.getProtocol());
        assertEquals("application/json", response.getResponseHeaders().getFirst(Headers.CONTENT_TYPE));
        assertSame(builder.getResponseHeaders(), response.getResponseHeaders());
    }

    @Test
    void exposesTheSameParseStateAcrossCalls() {
        HttpResponseBuilder builder = new HttpResponseBuilder();

        assertSame(builder.getParseState(), builder.getParseState());
        assertEquals(ResponseState.VERSION, builder.getParseState().state);
    }
}
