class ResponseParserTest {

    @Test
    void parsesStatusLineAndHeadersAndLeavesMessageBodyUntouched() {
        HttpResponseBuilder builder = new HttpResponseBuilder();
        ByteBuffer buffer = ascii("HTTP/1.1 200 OK\r\n"
                + "Content-Type: text/plain\r\n"
                + "Content-Length: 4\r\n"
                + "\r\n"
                + "BODY");

        ResponseParser.INSTANCE.handle(buffer, builder.getParseState(), builder);

        assertTrue(builder.getParseState().isComplete());
        assertEquals(Protocols.HTTP_1_1, builder.getProtocol());
        assertEquals(200, builder.getStatusCode());
        assertEquals("OK", builder.getReasonPhrase());
        assertEquals("text/plain", builder.getResponseHeaders().getFirst(Headers.CONTENT_TYPE));
        assertEquals("4", builder.getResponseHeaders().getFirst(Headers.CONTENT_LENGTH));
        assertEquals(4, buffer.remaining());
        byte[] remaining = new byte[buffer.remaining()];
        buffer.get(remaining);
        assertArrayEquals("BODY".getBytes(StandardCharsets.US_ASCII), remaining);
    }

    @Test
    void parsesHttp10ResponseWithoutHeaders() {
        HttpResponseBuilder builder = parse("HTTP/1.0 404 Not Found\r\n\r\n");

        assertEquals(Protocols.HTTP_1_0, builder.getProtocol());
        assertEquals(404, builder.getStatusCode());
        assertEquals("Not Found", builder.getReasonPhrase());
        assertEquals(0, builder.getResponseHeaders().size());
    }

    @Test
    void parsesHttp20Response() {
        HttpResponseBuilder builder = parse("HTTP/2.0 204 No Content\r\n\r\n");

        assertEquals(Protocols.HTTP_2_0, builder.getProtocol());
        assertEquals(204, builder.getStatusCode());
        assertEquals("No Content", builder.getReasonPhrase());
    }

    @Test
    void fallsBackToHttp11ForUnsupportedVersion() {
        HttpResponseBuilder builder = parse("HTTP/3.0 200 Boom\r\n\r\n");

        assertEquals(Protocols.HTTP_1_1, builder.getProtocol());
        assertEquals(200, builder.getStatusCode());
        assertEquals("Boom", builder.getReasonPhrase());
    }

    @Test
    void emptyReasonPhraseIsNotReported() {
        HttpResponseBuilder builder = parse("HTTP/1.1 204 \r\n\r\n");

        assertTrue(builder.getParseState().isComplete());
        assertEquals(204, builder.getStatusCode());
        assertNull(builder.getReasonPhrase());
    }

    @Test
    void unfoldsObsoleteLineFolding() {
        HttpResponseBuilder builder = parse("HTTP/1.1 200 OK\r\nX-Folded: first\r\n second\r\n\r\n");

        assertEquals("first second", builder.getResponseHeaders().getFirst("X-Folded"));
    }

    @Test
    void trimsOptionalWhitespaceAroundHeaderValues() {
        HttpResponseBuilder builder = parse("HTTP/1.1 200 OK\r\nX-Trimmed: \t value \t\r\n\r\n");

        assertEquals("value", builder.getResponseHeaders().getFirst("X-Trimmed"));
    }

    @Test
    void keepsSingleInternalWhitespaceInHeaderValues() {
        HttpResponseBuilder builder = parse("HTTP/1.1 200 OK\r\nX-Internal: alpha beta\r\n\r\n");

        assertEquals("alpha beta", builder.getResponseHeaders().getFirst("X-Internal"));
    }

    @Test
    void keepsDuplicateHeaderValuesInArrivalOrder() {
        HttpResponseBuilder builder = parse("HTTP/1.1 200 OK\r\nX-Multi: one\r\nOther: x\r\nX-Multi: two\r\n\r\n");

        assertArrayEquals(new String[]{"one", "two"}, builder.getResponseHeaders().get("X-Multi").toArray());
    }

    @Test
    void parsesResponseDeliveredInEveryPossibleChunkSize() {
        String response = "HTTP/1.1 200 OK\r\nFirst: one\r\nSecond: two\r\n\r\n";
        byte[] bytes = response.getBytes(StandardCharsets.US_ASCII);

        for (int chunkSize = 1; chunkSize <= bytes.length; chunkSize++) {
            HttpResponseBuilder builder = new HttpResponseBuilder();
            int offset = 0;
            while (offset < bytes.length && !builder.getParseState().isComplete()) {
                int length = Math.min(chunkSize, bytes.length - offset);
                ByteBuffer chunk = ByteBuffer.wrap(bytes, offset, length).slice();
                ResponseParser.INSTANCE.handle(chunk, builder.getParseState(), builder);
                int consumed = length - chunk.remaining();
                assertTrue(consumed > 0, "parser made no progress with chunk size " + chunkSize);
                offset += consumed;
            }

            assertTrue(builder.getParseState().isComplete(), "chunk size " + chunkSize);
            assertEquals(200, builder.getStatusCode(), "chunk size " + chunkSize);
            assertEquals("OK", builder.getReasonPhrase(), "chunk size " + chunkSize);
            assertEquals("one", builder.getResponseHeaders().getFirst("First"), "chunk size " + chunkSize);
            assertEquals("two", builder.getResponseHeaders().getFirst("Second"), "chunk size " + chunkSize);
            assertEquals(bytes.length, offset, "chunk size " + chunkSize);
        }
    }

    @Test
    void ignoresEmptyBuffer() {
        HttpResponseBuilder builder = new HttpResponseBuilder();

        ResponseParser.INSTANCE.handle(ByteBuffer.allocate(0), builder.getParseState(), builder);

        assertFalse(builder.getParseState().isComplete());
        assertEquals(ResponseState.VERSION, builder.getParseState().state);
    }

    @Test
    void rejectsMalformedProtocolVersion() {
        HttpResponseParseException exception = assertThrows(HttpResponseParseException.class,
                () -> parse("XTTP/1.1 200 OK\r\n\r\n"));

        assertEquals("Wrong protocol version", exception.getMessage());
    }

    @Test
    void rejectsMalformedStatusCode() {
        assertEquals("Wrong status code", assertThrows(HttpResponseParseException.class,
                () -> parse("HTTP/1.1 abc OK\r\n\r\n")).getMessage());
        assertEquals("Wrong status code", assertThrows(HttpResponseParseException.class,
                () -> parse("HTTP/1.1 20 OK\r\n\r\n")).getMessage());
        assertEquals("Wrong status code", assertThrows(HttpResponseParseException.class,
                () -> parse("HTTP/1.1 2000 OK\r\n\r\n")).getMessage());
    }

    @Test
    void rejectsMalformedReasonPhrase() {
        HttpResponseParseException exception = assertThrows(HttpResponseParseException.class,
                () -> parse("HTTP/1.1 200 Bad\u0001Reason\r\n\r\n"));

        assertEquals("Wrong reason phrase", exception.getMessage());
    }

    @Test
    void rejectsMalformedHeaderName() {
        HttpResponseParseException exception = assertThrows(HttpResponseParseException.class,
                () -> parse("HTTP/1.1 200 OK\r\nBad Name: value\r\n\r\n"));

        assertEquals("Wrong header name", exception.getMessage());
    }

    @Test
    void rejectsMalformedHeaderValue() {
        HttpResponseParseException exception = assertThrows(HttpResponseParseException.class,
                () -> parse("HTTP/1.1 200 OK\r\nX-Bad: value\u0001here\r\n\r\n"));

        assertEquals("Wrong header value", exception.getMessage());
    }

    @Test
    void ignoresBytesArrivingAfterTheResponseHeaderIsComplete() {
        HttpResponseBuilder builder = parse("HTTP/1.1 200 OK\r\n\r\n");
        assertTrue(builder.getParseState().isComplete());
        ByteBuffer body = ascii("later body");

        ResponseParser.INSTANCE.handle(body, builder.getParseState(), builder);

        assertEquals(10, body.remaining());
        assertEquals(200, builder.getStatusCode());
    }

    private static HttpResponseBuilder parse(final String response) {
        HttpResponseBuilder builder = new HttpResponseBuilder();
        ResponseParser.INSTANCE.handle(ascii(response), builder.getParseState(), builder);
        return builder;
    }

    private static ByteBuffer ascii(final String value) {
        return ByteBuffer.wrap(value.getBytes(StandardCharsets.US_ASCII));
    }
}
