package io.undertow.client.http;

import io.undertow.util.Headers;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ResponseStateTest {

    @Test
    void newStateStartsAtVersionWithEmptyBuffers() {
        ResponseState state = new ResponseState();

        assertEquals(ResponseState.VERSION, state.state);
        assertEquals(0, state.parsedData.length());
        assertEquals(0, state.previousByte);
        assertNull(state.headerName);
        assertFalse(state.isComplete());
    }

    @Test
    void isCompleteOnlyInMessageBodyState() {
        ResponseState state = new ResponseState();
        byte[] nonTerminalStates = {
                ResponseState.VERSION,
                ResponseState.STATUS_CODE,
                ResponseState.REASON_PHRASE,
                ResponseState.FIELD_NAME,
                ResponseState.FIELD_VALUE
        };

        for (byte candidate : nonTerminalStates) {
            state.state = candidate;
            assertFalse(state.isComplete());
        }

        state.state = ResponseState.MESSAGE_BODY;
        assertTrue(state.isComplete());
    }

    @Test
    void keepsParserScratchData() {
        ResponseState state = new ResponseState();
        state.parsedData.append("scratch");
        state.headerName = Headers.HOST;
        state.previousByte = (byte) '\r';

        assertEquals("scratch", state.parsedData.toString());
        assertEquals(Headers.HOST, state.headerName);
        assertEquals((byte) '\r', state.previousByte);
    }
}

