class ClientFixedLengthStreamSinkConduitTest {

    @Test
    void tracksNumberOfRemainingBytes() throws Exception {
        ByteBufferPool pool = HttpClientTestSupport.newBufferPool();
        HttpClientTestSupport.FakeStreamConnection fake = new HttpClientTestSupport.FakeStreamConnection();
        HttpClientConnection connection = new HttpClientConnection(fake, OptionMap.EMPTY, pool);
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, requestWithLength(5));
        HttpClientTestSupport.RecordingSinkConduit next = new HttpClientTestSupport.RecordingSinkConduit();
        ClientFixedLengthStreamSinkConduit conduit = new ClientFixedLengthStreamSinkConduit(next, 5, false, false, exchange);

        assertEquals(5, conduit.getRemaining());
        assertEquals(3, conduit.write(ByteBuffer.wrap("abc".getBytes(StandardCharsets.US_ASCII))));
        assertEquals(2, conduit.getRemaining());
        assertFalse(exchange.isRequestDataSent());
    }

    @Test
    void terminatesRequestOnlyAfterContentLengthBytesAreFlushed() throws Exception {
        ByteBufferPool pool = HttpClientTestSupport.newBufferPool();
        HttpClientTestSupport.FakeStreamConnection fake = new HttpClientTestSupport.FakeStreamConnection();
        HttpClientConnection connection = new HttpClientConnection(fake, OptionMap.EMPTY, pool);
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, requestWithLength(5));
        HttpClientTestSupport.RecordingSinkConduit next = new HttpClientTestSupport.RecordingSinkConduit();
        ClientFixedLengthStreamSinkConduit conduit = new ClientFixedLengthStreamSinkConduit(next, 5, false, false, exchange);

        assertEquals(3, conduit.write(ByteBuffer.wrap("abc".getBytes(StandardCharsets.US_ASCII))));
        assertTrue(conduit.flush());
        assertFalse(exchange.isRequestDataSent());

        assertEquals(2, conduit.write(ByteBuffer.wrap("de".getBytes(StandardCharsets.US_ASCII))));
        assertEquals(0, conduit.getRemaining());
        assertTrue(conduit.flush());

        assertTrue(exchange.isRequestDataSent());
        assertEquals("abcde", next.writtenAscii());
    }

    @Test
    void notifiesExchangeOnlyOnceWhenFlushedRepeatedly() throws Exception {
        ByteBufferPool pool = HttpClientTestSupport.newBufferPool();
        HttpClientTestSupport.FakeStreamConnection fake = new HttpClientTestSupport.FakeStreamConnection();
        HttpClientTestSupport.RecordingHttpClientConnection connection =
                new HttpClientTestSupport.RecordingHttpClientConnection(fake, OptionMap.EMPTY, pool);
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, requestWithLength(2));
        ClientFixedLengthStreamSinkConduit conduit = new ClientFixedLengthStreamSinkConduit(
                new HttpClientTestSupport.RecordingSinkConduit(), 2, false, false, exchange);

        conduit.write(ByteBuffer.wrap("ab".getBytes(StandardCharsets.US_ASCII)));
        assertTrue(conduit.flush());
        assertTrue(conduit.flush());

        assertEquals(1, connection.requestDataSentCalls());
    }

    @Test
    void limitsWriteToContentLengthAndRejectsOverflow() throws Exception {
        ByteBufferPool pool = HttpClientTestSupport.newBufferPool();
        HttpClientTestSupport.FakeStreamConnection fake = new HttpClientTestSupport.FakeStreamConnection();
        HttpClientConnection connection = new HttpClientConnection(fake, OptionMap.EMPTY, pool);
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, requestWithLength(2));
        HttpClientTestSupport.RecordingSinkConduit next = new HttpClientTestSupport.RecordingSinkConduit();
        ClientFixedLengthStreamSinkConduit conduit = new ClientFixedLengthStreamSinkConduit(next, 2, false, false, exchange);
        ByteBuffer source = ByteBuffer.wrap("abcd".getBytes(StandardCharsets.US_ASCII));

        assertEquals(2, conduit.write(source));
        assertEquals(2, source.remaining());
        assertEquals("ab", next.writtenAscii());
        assertThrows(FixedLengthOverflowException.class, () -> conduit.write(source));
    }

    @Test
    void truncatingBeforeCompletionTruncatesNextConduitAndTerminatesRequest() throws Exception {
        ByteBufferPool pool = HttpClientTestSupport.newBufferPool();
        HttpClientTestSupport.FakeStreamConnection fake = new HttpClientTestSupport.FakeStreamConnection();
        HttpClientConnection connection = new HttpClientConnection(fake, OptionMap.EMPTY, pool);
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, requestWithLength(10));
        HttpClientTestSupport.RecordingSinkConduit next = new HttpClientTestSupport.RecordingSinkConduit();
        ClientFixedLengthStreamSinkConduit conduit = new ClientFixedLengthStreamSinkConduit(next, 10, false, false, exchange);

        conduit.write(ByteBuffer.wrap("ab".getBytes(StandardCharsets.US_ASCII)));
        conduit.terminateWrites();

        assertEquals(1, next.truncateWritesCalls());
        assertTrue(exchange.isRequestDataSent());
    }

    @Test
    void truncatingWithoutWritingAnyBytesTerminatesRequest() throws Exception {
        ByteBufferPool pool = HttpClientTestSupport.newBufferPool();
        HttpClientTestSupport.FakeStreamConnection fake = new HttpClientTestSupport.FakeStreamConnection();
        HttpClientConnection connection = new HttpClientConnection(fake, OptionMap.EMPTY, pool);
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, requestWithLength(10));
        HttpClientTestSupport.RecordingSinkConduit next = new HttpClientTestSupport.RecordingSinkConduit();
        ClientFixedLengthStreamSinkConduit conduit = new ClientFixedLengthStreamSinkConduit(next, 10, false, false, exchange);

        conduit.terminateWrites();

        assertEquals(1, next.truncateWritesCalls());
        assertTrue(exchange.isRequestDataSent());
    }

    @Test
    void rejectsNegativeContentLength() {
        ByteBufferPool pool = HttpClientTestSupport.newBufferPool();
        HttpClientTestSupport.FakeStreamConnection fake = new HttpClientTestSupport.FakeStreamConnection();
        HttpClientConnection connection = new HttpClientConnection(fake, OptionMap.EMPTY, pool);
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, requestWithLength(1));
        HttpClientTestSupport.RecordingSinkConduit next = new HttpClientTestSupport.RecordingSinkConduit();

        assertThrows(IllegalArgumentException.class,
                () -> new ClientFixedLengthStreamSinkConduit(next, -1, false, false, exchange));
    }

    private static ClientRequest requestWithLength(final long length) {
        ClientRequest request = new ClientRequest().setPath("/fixed").setMethod(io.undertow.util.Methods.POST)
                .setProtocol(io.undertow.util.Protocols.HTTP_1_1);
        request.getRequestHeaders().put(Headers.CONTENT_LENGTH, Long.toString(length));
        return request;
    }
}

