package io.undertow.client.http;

import io.undertow.client.ClientCallback;
import io.undertow.client.ClientExchange;
import io.undertow.client.ClientRequest;
import io.undertow.client.ClientResponse;
import io.undertow.connector.ByteBufferPool;
import io.undertow.util.Headers;
import io.undertow.util.Protocols;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.xnio.OptionMap;

import java.io.IOException;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

class HttpClientExchangeTest {

    private ByteBufferPool bufferPool;
    private HttpClientTestSupport.FakeStreamConnection fakeConnection;
    private HttpClientConnection connection;

    @BeforeEach
    void setUp() {
        bufferPool = HttpClientTestSupport.newBufferPool();
        fakeConnection = new HttpClientTestSupport.FakeStreamConnection();
        connection = new HttpClientConnection(fakeConnection, OptionMap.EMPTY, bufferPool);
    }

    @AfterEach
    void tearDown() {
        bufferPool.close();
    }

    @Test
    void doesNotRequireContinueWithoutExpectHeader() {
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, HttpClientTestSupport.get("/"));

        assertFalse(exchange.isRequiresContinue());
    }

    @Test
    void requiresContinueForExact100ContinueExpectHeader() {
        ClientRequest request = HttpClientTestSupport.get("/");
        request.getRequestHeaders().add(Headers.EXPECT, "100-continue");

        assertTrue(HttpClientTestSupport.newExchange(connection, request).isRequiresContinue());
    }

    @Test
    void requiresContinueWhenAnyExpectValueMatches() {
        ClientRequest request = HttpClientTestSupport.get("/");
        request.getRequestHeaders().add(Headers.EXPECT, "something-else");
        request.getRequestHeaders().add(Headers.EXPECT, "100-continue");

        assertTrue(HttpClientTestSupport.newExchange(connection, request).isRequiresContinue());
    }

    @Test
    void notifiesContinueHandlerWhenContinueResponseArrives() {
        ClientRequest request = HttpClientTestSupport.get("/");
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, request);
        final ClientExchange[] notified = new ClientExchange[1];
        exchange.setContinueHandler(value -> notified[0] = value);
        ClientResponse continueResponse = new ClientResponse(100, "Continue", Protocols.HTTP_1_1);

        exchange.setContinueResponse(continueResponse);

        assertSame(exchange, notified[0]);
        assertSame(continueResponse, exchange.getContinueResponse());
    }

    @Test
    void deliversResponseToListenerRegisteredBeforeResponse() {
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, HttpClientTestSupport.get("/"));
        RecordingCallback<ClientExchange> callback = new RecordingCallback<>();
        ClientResponse response = new ClientResponse(200, "OK", Protocols.HTTP_1_1);
        exchange.setResponseListener(callback);

        exchange.setResponse(response);

        assertEquals(1, callback.completions);
        assertEquals(0, callback.failures);
        assertSame(exchange, callback.result);
        assertSame(response, exchange.getResponse());
    }

    @Test
    void deliversExistingResponseToLateListener() {
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, HttpClientTestSupport.get("/"));
        ClientResponse response = new ClientResponse(201, "Created", Protocols.HTTP_1_1);
        exchange.setResponse(response);
        RecordingCallback<ClientExchange> callback = new RecordingCallback<>();

        exchange.setResponseListener(callback);

        assertEquals(1, callback.completions);
        assertSame(exchange, callback.result);
    }

    @Test
    void deliversFailureToLateListener() {
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, HttpClientTestSupport.get("/"));
        IOException failure = new IOException("boom");
        exchange.setFailed(failure);
        RecordingCallback<ClientExchange> callback = new RecordingCallback<>();

        exchange.setResponseListener(callback);

        assertEquals(1, callback.failures);
        assertSame(failure, callback.failure);
        assertNull(exchange.getResponse());
    }

    @Test
    void failsBothReadyAndResponseCallbacks() {
        ClientRequest request = HttpClientTestSupport.get("/");
        RecordingCallback<ClientExchange> readyCallback = new RecordingCallback<>();
        HttpClientExchange exchange = new HttpClientExchange(readyCallback, request, connection);
        RecordingCallback<ClientExchange> responseCallback = new RecordingCallback<>();
        exchange.setResponseListener(responseCallback);
        IOException failure = new IOException("closed");

        exchange.setFailed(failure);

        assertEquals(1, readyCallback.failures);
        assertSame(failure, readyCallback.failure);
        assertEquals(1, responseCallback.failures);
        assertSame(failure, responseCallback.failure);
    }

    @Test
    void requestAndResponseChannelsFinishIndependently() {
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, HttpClientTestSupport.get("/"));

        assertTrue(exchange.getRequestChannel().isOpen());
        assertTrue(exchange.getResponseChannel().isOpen());

        exchange.terminateRequest();
        assertFalse(exchange.getRequestChannel().isOpen());
        assertTrue(exchange.getResponseChannel().isOpen());

        exchange.terminateResponse();
        assertFalse(exchange.getRequestChannel().isOpen());
        assertFalse(exchange.getResponseChannel().isOpen());
    }

    @Test
    void terminateRequestNotifiesConnectionOnlyOnce() {
        HttpClientTestSupport.RecordingHttpClientConnection recordingConnection =
                new HttpClientTestSupport.RecordingHttpClientConnection(
                        new HttpClientTestSupport.FakeStreamConnection(), OptionMap.EMPTY, bufferPool);
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(recordingConnection, HttpClientTestSupport.get("/"));

        exchange.terminateRequest();
        exchange.terminateRequest();
        exchange.terminateResponse();

        assertEquals(1, recordingConnection.requestDataSentCalls());
        assertEquals(1, recordingConnection.exchangeDoneCalls());
    }

    @Test
    void terminateResponseWaitsForRequestBeforeCompletingExchange() {
        HttpClientTestSupport.RecordingHttpClientConnection recordingConnection =
                new HttpClientTestSupport.RecordingHttpClientConnection(
                        new HttpClientTestSupport.FakeStreamConnection(), OptionMap.EMPTY, bufferPool);
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(recordingConnection, HttpClientTestSupport.get("/"));

        exchange.terminateResponse();
        assertEquals(0, recordingConnection.exchangeDoneCalls());

        exchange.terminateRequest();
        assertEquals(1, recordingConnection.exchangeDoneCalls());
    }

    @Test
    void exposesRequestAndOwningConnection() {
        ClientRequest request = HttpClientTestSupport.get("/owner");
        HttpClientExchange exchange = HttpClientTestSupport.newExchange(connection, request);

        assertSame(request, exchange.getRequest());
        assertSame(connection, exchange.getConnection());
    }

    private static final class RecordingCallback<T> implements ClientCallback<T> {

        private T result;
        private IOException failure;
        private int completions;
        private int failures;

        @Override
        public void completed(final T value) {
            completions++;
            result = value;
        }

        @Override
        public void failed(final IOException exception) {
            failures++;
            failure = exception;
        }
    }
}

