package io.undertow.client.http;

import io.undertow.client.ClientRequest;
import io.undertow.connector.ByteBufferPool;
import io.undertow.server.DefaultByteBufferPool;
import io.undertow.server.TruncatedResponseException;
import io.undertow.util.Headers;
import io.undertow.util.Methods;
import io.undertow.util.Protocols;
import org.junit.jupiter.api.Test;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class HttpRequestConduitTest {

    @Test
    void writesRequestLineHeadersAndBodyInSingleWrite() throws Exception {
        ClientRequest request = HttpClientTestSupport.get("/foo?x=1");
        request.getRequestHeaders().put(Headers.HOST, "example.com");
        request.getRequestHeaders().add(Headers.ACCEPT, "text/plain");
        request.getRequestHeaders().add(Headers.ACCEPT, "text/html");
        HttpClientTestSupport.RecordingSinkConduit sink = new HttpClientTestSupport.RecordingSinkConduit();
        HttpRequestConduit conduit = new HttpRequestConduit(sink, HttpClientTestSupport.newBufferPool(), request);

        int written = conduit.write(ByteBuffer.wrap("BODY".getBytes(StandardCharsets.US_ASCII)));

        assertEquals(4, written);
        String output = sink.writtenAscii();
        assertTrue(output.startsWith("GET /foo?x=1 HTTP/1.1\r\n"), output);
        assertTrue(output.contains("Host: example.com\r\n"), output);
        assertTrue(output.contains("Accept: text/plain\r\n"), output);
        assertTrue(output.contains("Accept: text/html\r\n"), output);
        assertTrue(output.endsWith("\r\n\r\nBODY"), output);
    }

    @Test
    void writesRequestWithoutHeaders() throws Exception {
        ClientRequest request = new ClientRequest().setMethod(Methods.DELETE).setPath("/resource").setProtocol(Protocols.HTTP_1_1);
        HttpClientTestSupport.RecordingSinkConduit sink = new HttpClientTestSupport.RecordingSinkConduit();
        HttpRequestConduit conduit = new HttpRequestConduit(sink, HttpClientTestSupport.newBufferPool(), request);

        assertEquals(3, conduit.write(ByteBuffer.wrap("abc".getBytes(StandardCharsets.US_ASCII))));

        assertEquals("DELETE /resource HTTP/1.1\r\n\r\nabc", sink.writtenAscii());
    }

    @Test
    void flushEmitsHeadersEvenWhenNoBodyWasWritten() throws Exception {
        ClientRequest request = HttpClientTestSupport.get("/flush");
        request.getRequestHeaders().put(Headers.HOST, "example.com");
        HttpClientTestSupport.RecordingSinkConduit sink = new HttpClientTestSupport.RecordingSinkConduit();
        HttpRequestConduit conduit = new HttpRequestConduit(sink, HttpClientTestSupport.newBufferPool(), request);

        assertTrue(conduit.flush());

        assertTrue(sink.flushed());
        assertEquals("GET /flush HTTP/1.1\r\nHost: example.com\r\n\r\n", sink.writtenAscii());
    }

    @Test
    void writeOfEmptyBufferStillEmitsHeaders() throws Exception {
        ClientRequest request = new ClientRequest().setMethod(Methods.POST).setPath("/").setProtocol(Protocols.HTTP_1_1);
        HttpClientTestSupport.RecordingSinkConduit sink = new HttpClientTestSupport.RecordingSinkConduit();
        HttpRequestConduit conduit = new HttpRequestConduit(sink, HttpClientTestSupport.newBufferPool(), request);

        assertEquals(0, conduit.write(ByteBuffer.allocate(0)));

        assertEquals("POST / HTTP/1.1\r\n\r\n", sink.writtenAscii());
    }

    @Test
    void appendsSubsequentBodyWritesAfterHeaders() throws Exception {
        ClientRequest request = HttpClientTestSupport.get("/body");
        HttpClientTestSupport.RecordingSinkConduit sink = new HttpClientTestSupport.RecordingSinkConduit();
        HttpRequestConduit conduit = new HttpRequestConduit(sink, HttpClientTestSupport.newBufferPool(), request);

        assertEquals(3, conduit.write(ByteBuffer.wrap("one".getBytes(StandardCharsets.US_ASCII))));
        assertEquals(3, conduit.write(ByteBuffer.wrap("two".getBytes(StandardCharsets.US_ASCII))));

        assertTrue(sink.writtenAscii().endsWith("\r\n\r\nonetwo"), sink.writtenAscii());
    }

    @Test
    void retriesWhenSinkAppliesBackpressure() throws Exception {
        ClientRequest request = new ClientRequest().setMethod(Methods.POST).setPath("/p").setProtocol(Protocols.HTTP_1_1);
        request.getRequestHeaders().put(Headers.CONTENT_LENGTH, "3");
        HttpClientTestSupport.RecordingSinkConduit sink = new HttpClientTestSupport.RecordingSinkConduit();
        sink.failWritesWithZero(1);
        HttpRequestConduit conduit = new HttpRequestConduit(sink, HttpClientTestSupport.newBufferPool(), request);
        ByteBuffer body = ByteBuffer.wrap("abc".getBytes(StandardCharsets.US_ASCII));

        assertEquals(0, conduit.write(body));
        assertEquals(3, body.remaining());
        assertEquals(0, sink.writtenBytes().length);

        assertEquals(3, conduit.write(body));
        assertEquals(0, body.remaining());
        assertEquals("POST /p HTTP/1.1\r\nContent-Length: 3\r\n\r\nabc", sink.writtenAscii());
    }

    @Test
