        assertTrue(exception.getMessage().endsWith("AJP request already in progress"));

        channel.sinkDone();
        // still waiting for a response
        assertThrows(IllegalStateException.class,
                () -> AjpTestSupport.request(channel, Methods.GET, "/", new HeaderMap(), AjpTestSupport.attachable()));

        channel.sourceDone();
        AjpClientRequestClientStreamSinkChannel next = AjpTestSupport.request(channel, Methods.GET, "/",
                new HeaderMap(), AjpTestSupport.attachable());
        assertNotNull(next);
    }

    @Test
    void parseFrameBuildsSendHeadersResponse() throws Exception {
        AjpClientChannel channel = newClientChannel();
        FrameHeaderData data = channel.parseFrame(responseFrame(AjpConstants.FRAME_TYPE_SEND_HEADERS, 1, buffer -> {
            putInt(buffer, 200);
            putString(buffer, "OK");
            putInt(buffer, 1);
            putInt(buffer, 0xA001);
            putString(buffer, "text/plain");
        }));

        AjpClientChannel.SendHeadersResponse response = assertInstanceOf(AjpClientChannel.SendHeadersResponse.class, data);
        assertEquals(0, response.getFrameLength());
        assertNull(response.getExistingChannel());

        AjpClientResponseStreamSourceChannel source = assertInstanceOf(AjpClientResponseStreamSourceChannel.class,
                channel.createChannel(response, null));
        assertEquals(200, source.getStatusCode());
        assertEquals("OK", source.getReasonPhrase());
        assertEquals("text/plain", source.getHeaders().getFirst(Headers.CONTENT_TYPE));
        assertEquals(1, channel.getReceivers().size());
    }

    @Test
    void parseFrameRecognisesRequestBodyChunkAndSendBodyChunk() throws Exception {
        AjpClientChannel channel = newClientChannel();

        FrameHeaderData requested = channel.parseFrame(responseFrame(AjpConstants.FRAME_TYPE_REQUEST_BODY_CHUNK, 2,
                buffer -> putInt(buffer, 321)));
        AjpClientChannel.RequestBodyChunk bodyChunk = assertInstanceOf(AjpClientChannel.RequestBodyChunk.class, requested);
        assertEquals(321, bodyChunk.getLength());
        assertEquals(0, bodyChunk.getFrameLength());

        FrameHeaderData body = channel.parseFrame(responseFrame(AjpConstants.FRAME_TYPE_SEND_BODY_CHUNK, 2,
                buffer -> putInt(buffer, 10)));
        AjpClientChannel.SendBodyChunk sendBodyChunk = assertInstanceOf(AjpClientChannel.SendBodyChunk.class, body);
        // AJP body chunks have a trailing null byte that is part of the frame
        assertEquals(11, sendBodyChunk.getFrameLength());
    }

    @Test
    void nonPersistentEndResponseClosesChannel() throws Exception {
