        assertTrue(channel.isOpen());

        FrameHeaderData data = channel.parseFrame(responseFrame(AjpConstants.FRAME_TYPE_END_RESPONSE, 1,
                buffer -> buffer.put((byte) 0)));
        assertInstanceOf(AjpClientChannel.EndResponse.class, data);
        assertFalse(channel.isOpen());
        assertTrue(channel.isLastFrameReceived());
        assertTrue(channel.isLastFrameSent());
    }

    @Test
    void persistentEndResponseLeavesChannelOpen() throws Exception {
        AjpClientChannel channel = newClientChannel();

        FrameHeaderData data = channel.parseFrame(responseFrame(AjpConstants.FRAME_TYPE_END_RESPONSE, 1,
                buffer -> buffer.put((byte) 1)));

        assertInstanceOf(AjpClientChannel.EndResponse.class, data);
        assertTrue(channel.isOpen());
        assertFalse(channel.isLastFrameReceived());
        assertFalse(channel.isLastFrameSent());
    }

    @Test
    void parseFrameRecognisesCpong() throws Exception {
        AjpClientChannel channel = newClientChannel();
        FrameHeaderData data = channel.parseFrame(AjpTestSupport.bytes(0x41, 0x42, 0x00, 0x01, AjpConstants.FRAME_TYPE_CPONG));
        AjpClientChannel.CpongResponse cpong = assertInstanceOf(AjpClientChannel.CpongResponse.class, data);
        assertEquals(0, cpong.getFrameLength());
        assertNull(cpong.getExistingChannel());
    }

    @Test
    void createChannelHandlesRequestBodyChunkAndClosesData() throws Exception {
        AjpClientChannel channel = newClientChannel();
        AjpClientRequestClientStreamSinkChannel request = AjpTestSupport.request(channel, Methods.POST, "/",
                new HeaderMap(), AjpTestSupport.attachable());
        assertNotNull(request);

        FrameHeaderData requested = channel.parseFrame(responseFrame(AjpConstants.FRAME_TYPE_REQUEST_BODY_CHUNK, 2,
                buffer -> putInt(buffer, 17)));
        TrackingPooledByteBuffer data = new TrackingPooledByteBuffer();
        assertNull(channel.createChannel(requested, data));
        assertTrue(data.isClosed());
    }

    @Test
    void createChannelRejectsUnknownFrameAndClosesData() {
        AjpClientChannel channel = newClientChannel();
        FrameHeaderData unknown = new FrameHeaderData() {
            @Override
            public long getFrameLength() {
                return 0;
            }

            @Override
            public AbstractFramedStreamSourceChannel<?, ?, ?> getExistingChannel() {
                return null;
            }
        };
        TrackingPooledByteBuffer data = new TrackingPooledByteBuffer();

        RuntimeException exception = assertThrows(RuntimeException.class, () -> channel.createChannel(unknown, data));
        assertEquals("TODO: unknown frame", exception.getMessage());
        assertTrue(data.isClosed());
    }

    @Test
    void sourceDoneWithoutSinkDonePutsRequestIntoDiscardMode() throws Exception {
        AjpClientChannel channel = newClientChannel();
        AjpClientRequestClientStreamSinkChannel request = AjpTestSupport.request(channel, Methods.POST, "/",
                new HeaderMap(), AjpTestSupport.attachable());

        channel.sourceDone();

        SendFrameHeader header = request.generateSendFrameHeader();
        assertNotNull(header.getByteBuffer());
        assertEquals(0, header.getByteBuffer().getBuffer().remaining());
        assertEquals(0, header.getRemainingInBuffer());

        channel.sinkDone();
        assertEquals(0, channel.getReceivers().size());
        assertNotNull(AjpTestSupport.request(channel, Methods.GET, "/", new HeaderMap(), AjpTestSupport.attachable()));
    }

    @Test
    void channelExposesSettingsAndBufferPool() {
        AjpClientChannel channel = newClientChannel();
        assertNotNull(channel.getBufferPool());
        assertNotNull(channel.getSettings());
        assertEquals(0, channel.getSettings().size());
        assertEquals(4096, channel.getBufferPool().getBufferSize());
    }

    @Test
    void closeSubChannelsDoesNotFailWhenNoSubChannelsExist() {
        AjpClientChannel channel = newClientChannel();
        channel.closeSubChannels();
        Collection<AbstractFramedStreamSourceChannel<AjpClientChannel, AbstractAjpClientStreamSourceChannel, AbstractAjpClientStreamSinkChannel>> receivers = channel.getReceivers();
        assertEquals(0, receivers.size());
    }

    @Test
    void settingsAreReadFromOptionMap() {
        AjpClientChannel channel = newClientChannel();
        assertFalse(channel.getSettings().contains(Options.READ_TIMEOUT));
        assertEquals(0, channel.getSettings().size());
    }

    @Test
    void parseFrameWithIncompleteDataReturnsNull() throws Exception {
        AjpClientChannel channel = newClientChannel();
        assertNull(channel.parseFrame(ByteBuffer.allocate(0)));
        assertNull(channel.parseFrame(AjpTestSupport.bytes(0x41, 0x42, 0x00, 0x01, AjpConstants.FRAME_TYPE_END_RESPONSE)));
        assertInstanceOf(AjpClientChannel.EndResponse.class, channel.parseFrame(AjpTestSupport.bytes(0x00)));
    }

    @Test
    void isLastFrameFlagsInitiallyFalse() {
        AjpClientChannel channel = newClientChannel();
        assertFalse(channel.isLastFrameReceived());
        assertFalse(channel.isLastFrameSent());
    }

    private static final class TrackingPooledByteBuffer implements PooledByteBuffer {
        private boolean closed;

        @Override
        public ByteBuffer getBuffer() {
            return ByteBuffer.allocate(0);
        }

        @Override
        public void close() {
            closed = true;
        }

        @Override
        public boolean isOpen() {
            return !closed;
        }

        boolean isClosed() {
            return closed;
        }
    }
}
