@Tag("io.undertow.testutils.category.UnitTest")
class AjpClientFramePriorityTest {

    private final AjpClientFramePriority priority = AjpClientFramePriority.INSTANCE;

    @Test
    void instanceIsAvailableAsSingleton() {
        assertNotNull(AjpClientFramePriority.INSTANCE);
        assertSame(AjpClientFramePriority.INSTANCE, priority);
    }

    @Test
    void ordinaryFramesAreAlwaysPending() {
        AbstractAjpClientStreamSinkChannel frame = new AbstractAjpClientStreamSinkChannel(null) {
        };
        List<AbstractAjpClientStreamSinkChannel> pending = new ArrayList<>();

        assertTrue(priority.insertFrame(frame, pending));
        assertEquals(1, pending.size());
        assertSame(frame, pending.get(0));
    }

    @Test
    void requestWaitingForAFlowControlWindowIsHeld() {
        AjpClientChannel channel = newClientChannel();
        AjpClientRequestClientStreamSinkChannel request = request(channel, Methods.POST, "/",
                new HeaderMap(), AjpTestSupport.attachable());
        request.generateSendFrameHeader();
        List<AbstractAjpClientStreamSinkChannel> pending = new ArrayList<>();

        assertFalse(priority.insertFrame(request, pending));
        assertTrue(pending.isEmpty());
    }

    @Test
    void requestWithNoBodyIsImmediatelyPending() {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "0");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.GET, "/",
                headers, AjpTestSupport.attachable());
        List<AbstractAjpClientStreamSinkChannel> pending = new ArrayList<>();

        assertTrue(priority.insertFrame(request, pending));
        assertEquals(1, pending.size());
    }

    @Test
    void frameAddedReleasesRequestOnceAChunkIsAvailable() throws Exception {
        AjpClientChannel channel = newClientChannel();
        AjpClientRequestClientStreamSinkChannel request = request(channel, Methods.POST, "/",
                new HeaderMap(), AjpTestSupport.attachable());
        request.generateSendFrameHeader();
        List<AbstractAjpClientStreamSinkChannel> pending = new ArrayList<>();
        Deque<AbstractAjpClientStreamSinkChannel> held = new ArrayDeque<>();
        held.add(request);

        AbstractAjpClientStreamSinkChannel added = new AbstractAjpClientStreamSinkChannel(null) {
        };
        priority.frameAdded(added, pending, held);
        assertEquals(1, held.size());
        assertTrue(pending.isEmpty());

        request.chunkRequested(1);
        priority.frameAdded(added, pending, held);

        assertTrue(held.isEmpty());
        assertEquals(1, pending.size());
        assertSame(request, pending.get(0));
    }

    @Test
    void frameAddedLeavesNonRequestFramesInTheHoldQueue() {
        AbstractAjpClientStreamSinkChannel heldFrame = new AbstractAjpClientStreamSinkChannel(null) {
        };
        Deque<AbstractAjpClientStreamSinkChannel> held = new ArrayDeque<>();
        held.add(heldFrame);
        List<AbstractAjpClientStreamSinkChannel> pending = new ArrayList<>();

        priority.frameAdded(heldFrame, pending, held);

        assertEquals(1, held.size());
        assertSame(heldFrame, held.peek());
        assertTrue(pending.isEmpty());
    }
}
