    @Test
    void forciblyClosedRequestNotifiesFinishListenerAndCompletesSink() throws Exception {
        AjpClientChannel channel = newClientChannel();
        java.util.concurrent.atomic.AtomicInteger callbacks = new java.util.concurrent.atomic.AtomicInteger();
        AjpClientRequestClientStreamSinkChannel request = channel.sendRequest(Methods.GET, "/",
                new HttpString("HTTP/1.1"), new HeaderMap(), AjpTestSupport.attachable(),
                ignored -> callbacks.incrementAndGet());

        request.channelForciblyClosed();

        assertEquals(1, callbacks.get());
        IllegalStateException exception = assertThrows(IllegalStateException.class,
                () -> request(channel, Methods.GET, "/", new HeaderMap(), AjpTestSupport.attachable()));
        assertTrue(exception.getMessage().endsWith("AJP request already in progress"));

        channel.sourceDone();
        assertNotNull(request(channel, Methods.GET, "/", new HeaderMap(), AjpTestSupport.attachable()));
    }

    @Test
    void generatesExactMinimalGetRequestFrame() {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "0");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.GET, "/", headers,
                AjpTestSupport.attachable());

        SendFrameHeader header = request.generateSendFrameHeader();
        ByteBuffer frame = header.getByteBuffer().getBuffer();
        byte[] actual = new byte[frame.remaining()];
        frame.duplicate().get(actual);

        byte[] expected = new byte[] {
                0x12, 0x34, 0x00, 0x26, 0x02,
                0x02,
                0x00, 0x08, 'H', 'T', 'T', 'P', '/', '1', '.', '1', 0x00,
                0x00, 0x01, '/', 0x00,
                0x00, 0x00, 0x00,
                0x00, 0x00, 0x00,
                0x00, 0x00, 0x00,
                0x00, 0x00,
                0x00,
                0x00, 0x01,
                (byte) 0xA0, 0x08,
                0x00, 0x01, '0', 0x00,
                (byte) 0xFF
        };
        assertArrayEquals(expected, actual);
        assertEquals(0, header.getRemainingInBuffer());
        assertFalse(header.isAnotherFrameRequired());
        header.getByteBuffer().close();
    }

    @Test
    void encodesKnownMethodAsSingleByte() {
