        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.POST, "/submit",
                headers, AjpTestSupport.attachable());

        SendFrameHeader header = request.generateSendFrameHeader();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(header.getByteBuffer().getBuffer());

        assertEquals(2, decoded.prefix);
        assertEquals(4, decoded.method);
        assertEquals("HTTP/1.1", decoded.protocol);
        assertEquals("/submit", decoded.path);
        assertEquals("", decoded.remoteAddress);
        assertEquals("", decoded.remoteHost);
        assertEquals("", decoded.serverName);
        assertEquals(0, decoded.serverPort);
        assertEquals(0, decoded.ssl);
        assertTrue(decoded.attributes.isEmpty());
        header.getByteBuffer().close();
    }

    @Test
    void encodesUnknownMethodAsStoredMethodAttribute() {
        HeaderMap headers = new HeaderMap();
