        HttpString customMethod = HttpString.tryFromString("CUSTOM");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), customMethod, "/",
                headers, AjpTestSupport.attachable());

        SendFrameHeader header = request.generateSendFrameHeader();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(header.getByteBuffer().getBuffer());

        assertEquals(0xFF, decoded.method);
