    @Test
    void encodesWellKnownHeadersWithNumericCodesAndCustomHeadersByName() {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "0");
        headers.put(Headers.ACCEPT, "text/html");
        headers.add(Headers.ACCEPT, "application/json");
        headers.put(Headers.COOKIE, "a=b");
        headers.put(new HttpString("X-Custom"), "custom-value");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.GET, "/",
                headers, AjpTestSupport.attachable());

        SendFrameHeader header = request.generateSendFrameHeader();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(header.getByteBuffer().getBuffer());

        assertEquals(2, countCode(decoded, 0xA001));
        assertEquals(2, valuesForCode(decoded, 0xA001).size());
        assertEquals("a=b", valuesForCode(decoded, 0xA009).get(0));
        assertEquals("custom-value", headerValue(decoded, "X-Custom"));
