        sendBody(request, "hi".getBytes(StandardCharsets.US_ASCII));
        request.shutdownWrites();

        SendFrameHeader header = request.generateSendFrameHeader();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(header.getByteBuffer().getBuffer());

        assertNull(headers.getFirst(Headers.CONTENT_LENGTH));
        assertEquals("chunked", headerValue(decoded, "Transfer-Encoding"));
        assertEquals(2, header.getRemainingInBuffer());
        assertTrue(header.isAnotherFrameRequired());
        header.getByteBuffer().close();
    }

    @Test
    void packetSizeSettingLimitsEachBodyChunk() throws Exception {
        OptionMap settings = OptionMap.create(UndertowOptions.MAX_AJP_PACKET_SIZE, 16);
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "20");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(settings), Methods.POST, "/",
                headers, AjpTestSupport.attachable());
        sendBody(request, new byte[20]);

        SendFrameHeader header = request.generateSendFrameHeader();
        ByteBuffer frame = header.getByteBuffer().getBuffer();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(frame);
        int chunkOffset = 4 + decoded.frameLength;

        assertEquals(10, frame.getShort(chunkOffset + 4) & 0xFFFF);
        assertEquals(10, header.getRemainingInBuffer());
        assertEquals(10, request.getBuffer().remaining());
        header.getByteBuffer().close();
    }

    @Test
    void zeroLengthBodyProducesHeadersOnly() {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "0");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.GET, "/",
                headers, AjpTestSupport.attachable());

        SendFrameHeader header = request.generateSendFrameHeader();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(header.getByteBuffer().getBuffer());

        assertEquals(4 + decoded.frameLength, header.getByteBuffer().getBuffer().remaining());
        assertEquals(0, header.getRemainingInBuffer());
        header.getByteBuffer().close();
    }

    @Test
    void requestBufferIsUsableForWritingBody() throws Exception {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "4");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.POST, "/",
                headers, AjpTestSupport.attachable());

        request.write(ByteBuffer.wrap(new byte[4096]));
        ByteBuffer buffer = request.getBuffer();
        assertNotNull(buffer);
        assertEquals(4096, buffer.remaining());

        request.shutdownWrites();
        assertTrue(request.isWritesShutdown());
    }

    private static void sendBody(AjpClientRequestClientStreamSinkChannel request, byte[] body) throws java.io.IOException {
        request.send(new ImmediatePooledByteBuffer(ByteBuffer.wrap(body)));
    }

    private static int countCode(AjpTestSupport.DecodedRequest decoded, int code) {
        int count = 0;
        for (AjpTestSupport.DecodedHeader header : decoded.headers) {
            if (header.code == code) {
                count++;
            }
        }
        return count;
    }

    private static java.util.List<String> valuesForCode(AjpTestSupport.DecodedRequest decoded, int code) {
        java.util.List<String> values = new java.util.ArrayList<>();
        for (AjpTestSupport.DecodedHeader header : decoded.headers) {
            if (header.code == code) {
                values.add(header.value);
            }
        }
        return values;
    }

    private static String headerValue(AjpTestSupport.DecodedRequest decoded, String name) {
        for (AjpTestSupport.DecodedHeader header : decoded.headers) {
            if (name.equals(header.name) || (header.code == 0xA003 && "Transfer-Encoding".equals(name))
                    || (header.code == 0xA008 && "Content-Length".equals(name))) {
                return header.value;
            }
        }
        return null;
    }
}
package io.undertow.protocols.ajp;

import static io.undertow.protocols.ajp.AjpTestSupport.newClientChannel;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
