    @Test
    void encodesProxyAttachments() {
        Attachable attachable = AjpTestSupport.attachable();
        attachable.putAttachment(ProxiedRequestAttachments.REMOTE_ADDRESS, "10.1.2.3");
        attachable.putAttachment(ProxiedRequestAttachments.REMOTE_HOST, "client.example");
        attachable.putAttachment(ProxiedRequestAttachments.SERVER_NAME, "backend.example");
        attachable.putAttachment(ProxiedRequestAttachments.SERVER_PORT, 8443);
        attachable.putAttachment(ProxiedRequestAttachments.IS_SSL, Boolean.TRUE);
        attachable.putAttachment(ProxiedRequestAttachments.REMOTE_USER, "alice");
        attachable.putAttachment(ProxiedRequestAttachments.AUTH_TYPE, "BASIC");
        attachable.putAttachment(ProxiedRequestAttachments.ROUTE, "node-1");
        attachable.putAttachment(ProxiedRequestAttachments.SSL_CERT, "CERT-DATA");
        attachable.putAttachment(ProxiedRequestAttachments.SSL_CYPHER, "TLS_AES_256_GCM_SHA384");
        attachable.putAttachment(ProxiedRequestAttachments.SSL_SESSION_ID, new byte[] {0x0A, 0x0B, 0x0C});
        attachable.putAttachment(ProxiedRequestAttachments.SSL_KEY_SIZE, 256);
        attachable.putAttachment(ProxiedRequestAttachments.SECRET, "s3cr3t");

        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "0");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.GET, "/secure",
                headers, attachable);

        SendFrameHeader header = request.generateSendFrameHeader();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(header.getByteBuffer().getBuffer());

        assertEquals("10.1.2.3", decoded.remoteAddress);
        assertEquals("client.example", decoded.remoteHost);
        assertEquals("backend.example", decoded.serverName);
        assertEquals(8443, decoded.serverPort);
        assertEquals(1, decoded.ssl);
        assertEquals("alice", decoded.attributes.get(AjpConstants.ATTR_REMOTE_USER));
        assertEquals("BASIC", decoded.attributes.get(AjpConstants.ATTR_AUTH_TYPE));
        assertEquals("node-1", decoded.attributes.get(AjpConstants.ATTR_ROUTE));
        assertEquals("CERT-DATA", decoded.attributes.get(AjpConstants.ATTR_SSL_CERT));
        assertEquals("TLS_AES_256_GCM_SHA384", decoded.attributes.get(AjpConstants.ATTR_SSL_CIPHER));
        assertEquals("0a0b0c", decoded.attributes.get(AjpConstants.ATTR_SSL_SESSION));
        assertEquals("256", decoded.attributes.get(AjpConstants.ATTR_SSL_KEY_SIZE));
        assertEquals("s3cr3t", decoded.attributes.get(AjpConstants.ATTR_SECRET));
