    @Test
    void fixedLengthBodyIsSentAsChunkDirectlyAfterHeaders() throws Exception {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "5");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.POST, "/",
                headers, AjpTestSupport.attachable());
        sendBody(request, "hello".getBytes(StandardCharsets.US_ASCII));

        SendFrameHeader header = request.generateSendFrameHeader();
        ByteBuffer frame = header.getByteBuffer().getBuffer();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(frame);

        assertEquals(0, header.getRemainingInBuffer());
        assertFalse(header.isAnotherFrameRequired());
        int chunkOffset = 4 + decoded.frameLength;
        assertEquals(0x12, frame.get(chunkOffset) & 0xFF);
        assertEquals(0x34, frame.get(chunkOffset + 1) & 0xFF);
        assertEquals(7, frame.getShort(chunkOffset + 2) & 0xFFFF);
        assertEquals(5, frame.getShort(chunkOffset + 4) & 0xFFFF);
        header.getByteBuffer().close();
    }

    @Test
    void bodyLargerThanContentLengthIsRejected() throws Exception {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "2");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.POST, "/",
                headers, AjpTestSupport.attachable());
        sendBody(request, new byte[] {1, 2, 3});

        IllegalStateException exception = assertThrows(IllegalStateException.class,
                request::generateSendFrameHeader);
        assertTrue(exception.getMessage().endsWith("More data was written to the channel than specified in the content-length"));
    }

    @Test
    void chunkedRequestWaitsForBodyChunkRequest() throws Exception {
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.POST, "/",
                new HeaderMap(), AjpTestSupport.attachable());
        sendBody(request, "abcdefg".getBytes(StandardCharsets.US_ASCII));

        SendFrameHeader header = request.generateSendFrameHeader();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(header.getByteBuffer().getBuffer());

        assertEquals("chunked", headerValue(decoded, "Transfer-Encoding"));
        assertEquals(7, header.getRemainingInBuffer());
        assertTrue(header.isAnotherFrameRequired());

        // The backend asks for five bytes, which must produce a five byte chunk frame
        request.getBuffer().position(0).limit(7);
        request.chunkRequested(5);
        SendFrameHeader chunkHeader = request.generateSendFrameHeader();
        ByteBuffer chunk = chunkHeader.getByteBuffer().getBuffer();
        assertEquals(0x12, chunk.get(0) & 0xFF);
        assertEquals(0x34, chunk.get(1) & 0xFF);
        assertEquals(7, chunk.getShort(2) & 0xFFFF);
        assertEquals(5, chunk.getShort(4) & 0xFFFF);
        assertEquals(2, chunkHeader.getRemainingInBuffer());
        assertTrue(chunkHeader.isAnotherFrameRequired());
        chunkHeader.getByteBuffer().close();
        header.getByteBuffer().close();
    }

    @Test
    void shutdownWithoutContentLengthDerivesFixedLength() throws Exception {
        HeaderMap headers = new HeaderMap();
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.POST, "/",
                headers, AjpTestSupport.attachable());
        sendBody(request, "hello".getBytes(StandardCharsets.US_ASCII));
        request.shutdownWrites();

        SendFrameHeader header = request.generateSendFrameHeader();
        ByteBuffer frame = header.getByteBuffer().getBuffer();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(frame);

        assertEquals("5", headers.getFirst(Headers.CONTENT_LENGTH));
        assertNull(headers.getFirst(Headers.TRANSFER_ENCODING));
        assertEquals("5", headerValue(decoded, "Content-Length"));
        int chunkOffset = 4 + decoded.frameLength;
        assertEquals(7, frame.getShort(chunkOffset + 2) & 0xFFFF);
        assertEquals(5, frame.getShort(chunkOffset + 4) & 0xFFFF);
        header.getByteBuffer().close();
    }

    @Test
    void shutdownWithTransferEncodingKeepsChunkedEncoding() throws Exception {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.TRANSFER_ENCODING, "chunked");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.POST, "/",
                headers, AjpTestSupport.attachable());
        sendBody(request, "hi".getBytes(StandardCharsets.US_ASCII));
        request.shutdownWrites();

        SendFrameHeader header = request.generateSendFrameHeader();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(header.getByteBuffer().getBuffer());

        assertNull(headers.getFirst(Headers.CONTENT_LENGTH));
        assertEquals("chunked", headerValue(decoded, "Transfer-Encoding"));
        assertEquals(2, header.getRemainingInBuffer());
        assertTrue(header.isAnotherFrameRequired());
        header.getByteBuffer().close();
    }

    @Test
    void packetSizeSettingLimitsEachBodyChunk() throws Exception {
        OptionMap settings = OptionMap.create(UndertowOptions.MAX_AJP_PACKET_SIZE, 16);
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "20");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(settings), Methods.POST, "/",
                headers, AjpTestSupport.attachable());
        sendBody(request, new byte[20]);

        SendFrameHeader header = request.generateSendFrameHeader();
        ByteBuffer frame = header.getByteBuffer().getBuffer();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(frame);
        int chunkOffset = 4 + decoded.frameLength;

        assertEquals(10, frame.getShort(chunkOffset + 4) & 0xFFFF);
        assertEquals(10, header.getRemainingInBuffer());
        assertEquals(10, request.getBuffer().remaining());
        header.getByteBuffer().close();
    }

    @Test
    void zeroLengthBodyProducesHeadersOnly() {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "0");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.GET, "/",
                headers, AjpTestSupport.attachable());

        SendFrameHeader header = request.generateSendFrameHeader();
        AjpTestSupport.DecodedRequest decoded = decodeRequest(header.getByteBuffer().getBuffer());

        assertEquals(4 + decoded.frameLength, header.getByteBuffer().getBuffer().remaining());
        assertEquals(0, header.getRemainingInBuffer());
        header.getByteBuffer().close();
    }

    @Test
    void requestBufferIsUsableForWritingBody() throws Exception {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_LENGTH, "4");
        AjpClientRequestClientStreamSinkChannel request = request(newClientChannel(), Methods.POST, "/",
                headers, AjpTestSupport.attachable());

        request.write(ByteBuffer.wrap(new byte[4096]));
        ByteBuffer buffer = request.getBuffer();
        assertNotNull(buffer);
        assertEquals(4096, buffer.remaining());

        request.shutdownWrites();
        assertTrue(request.isWritesShutdown());
    }

    private static void sendBody(AjpClientRequestClientStreamSinkChannel request, byte[] body) throws java.io.IOException {
        request.send(new ImmediatePooledByteBuffer(ByteBuffer.wrap(body)));
    }

    private static int countCode(AjpTestSupport.DecodedRequest decoded, int code) {
        int count = 0;
        for (AjpTestSupport.DecodedHeader header : decoded.headers) {
            if (header.code == code) {
                count++;
            }
        }
        return count;
    }

    private static java.util.List<String> valuesForCode(AjpTestSupport.DecodedRequest decoded, int code) {
        java.util.List<String> values = new java.util.ArrayList<>();
        for (AjpTestSupport.DecodedHeader header : decoded.headers) {
            if (header.code == code) {
                values.add(header.value);
            }
        }
        return values;
    }

    private static String headerValue(AjpTestSupport.DecodedRequest decoded, String name) {
        for (AjpTestSupport.DecodedHeader header : decoded.headers) {
            if (name.equals(header.name) || (header.code == 0xA003 && "Transfer-Encoding".equals(name))
                    || (header.code == 0xA008 && "Content-Length".equals(name))) {
                return header.value;
            }
        }
        return null;
    }
}

package io.undertow.protocols.ajp;

import static io.undertow.protocols.ajp.AjpTestSupport.newClientChannel;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import io.undertow.connector.PooledByteBuffer;
import io.undertow.util.HeaderMap;
import io.undertow.util.Headers;
import io.undertow.util.ImmediatePooledByteBuffer;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

@Tag("io.undertow.testutils.category.UnitTest")
class AjpClientResponseStreamSourceChannelTest {

    @Test
    void exposesStatusHeadersAndReasonPhrase() {
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_TYPE, "text/plain");
        AjpClientResponseStreamSourceChannel source = new AjpClientResponseStreamSourceChannel(newClientChannel(),
                headers, 201, "Created", data("abc\0"), 4);

        assertSame(headers, source.getHeaders());
        assertEquals(201, source.getStatusCode());
        assertEquals("Created", source.getReasonPhrase());
        assertEquals("text/plain", source.getHeaders().getFirst(Headers.CONTENT_TYPE));
    }

    @Test
    void stripsTrailingNullTerminatorFromBodyFrame() throws Exception {
        PooledByteBuffer data = data("hello\0");
        AjpClientResponseStreamSourceChannel source = new AjpClientResponseStreamSourceChannel(newClientChannel(),
                new HeaderMap(), 200, "OK", data, 6);

        ByteBuffer destination = ByteBuffer.allocate(16);
        int read = source.read(destination);

        assertEquals(5, read);
        byte[] actual = new byte[5];
        destination.flip();
        destination.get(actual);
        assertEquals("hello", new String(actual, StandardCharsets.US_ASCII));
        assertEquals(5, data.getBuffer().limit());
    }

    @Test
    void updateFrameDataRemainingOnlyTrimsWhenSizesMatch() {
        AjpClientResponseStreamSourceChannel source = new AjpClientResponseStreamSourceChannel(newClientChannel(),
                new HeaderMap(), 200, "OK", null, 0);

        PooledByteBuffer data = data("abcd");
        assertEquals(3, source.updateFrameDataRemaining(data, 4));
        assertEquals(3, data.getBuffer().limit());

        PooledByteBuffer different = data("abcd");
        assertEquals(9, source.updateFrameDataRemaining(different, 9));
        assertEquals(4, different.getBuffer().limit());
    }

    @Test
    void endResponseHeaderMarksLastFrameAndNotifiesFinishListener() throws Exception {
        AjpClientChannel channel = newClientChannel();
        AtomicBoolean finished = new AtomicBoolean();
        AjpClientResponseStreamSourceChannel source = new AjpClientResponseStreamSourceChannel(channel,
                new HeaderMap(), 200, "OK", data("abc\0"), 4);
        source.setFinishListener(ignored -> finished.set(true));

        source.handleHeaderData(channel.new EndResponse());

        ByteBuffer destination = ByteBuffer.allocate(8);
        assertEquals(3, source.read(destination));
        destination.clear();
        assertEquals(-1, source.read(destination));
        assertTrue(finished.get());
    }

    @Test
    void withoutEndResponseTheStreamWaitsForAnotherFrame() throws Exception {
        AjpClientResponseStreamSourceChannel source = new AjpClientResponseStreamSourceChannel(newClientChannel(),
                new HeaderMap(), 200, "OK", data("abc\0"), 4);

        ByteBuffer destination = ByteBuffer.allocate(8);
        assertEquals(3, source.read(destination));
        destination.clear();
        assertEquals(0, source.read(destination));
    }

    @Test
    void resumeSuspendAndWakeupAreForwardedToTheUnderlyingChannel() {
        AjpClientResponseStreamSourceChannel source = new AjpClientResponseStreamSourceChannel(newClientChannel(),
                new HeaderMap(), 200, "OK", null, 0);

        assertFalse(source.isReadResumed());
        source.resumeReads();
        assertTrue(source.isReadResumed());
        source.suspendReads();
        assertFalse(source.isReadResumed());
        source.wakeupReads();
        assertTrue(source.isReadResumed());
    }

    @Test
    void nullFinishListenerIsTolerated() throws Exception {
        AjpClientChannel channel = newClientChannel();
        AjpClientResponseStreamSourceChannel source = new AjpClientResponseStreamSourceChannel(channel,
                new HeaderMap(), 200, "OK", data("a\0"), 2);
        source.handleHeaderData(channel.new EndResponse());

        ByteBuffer destination = ByteBuffer.allocate(4);
        assertEquals(1, source.read(destination));
        destination.clear();
        assertEquals(-1, source.read(destination));
    }

    @Test
    void completeInvokesFinishListenerOnlyWhenSetAndMarksChannelSourceDone() throws Exception {
        AjpClientChannel channel = newClientChannel();
        AtomicInteger completed = new AtomicInteger();
        AjpClientResponseStreamSourceChannel source = new AjpClientResponseStreamSourceChannel(channel,
                new HeaderMap(), 200, "OK", null, 0);
        source.setFinishListener(ignored -> completed.incrementAndGet());

        source.complete();

        assertEquals(1, completed.get());
    }

    private static PooledByteBuffer data(String value) {
        return new ImmediatePooledByteBuffer(ByteBuffer.wrap(value.getBytes(StandardCharsets.US_ASCII)));
    }
}

