@Tag("io.undertow.testutils.category.UnitTest")
class AjpResponseParserTest {

    @Test
    void parsesSendHeadersResponse() throws Exception {
        ByteBuffer frame = responseFrame(AjpConstants.FRAME_TYPE_SEND_HEADERS, 42, buffer -> {
            putInt(buffer, 201);
            putString(buffer, "Created");
            putInt(buffer, 3);
            putInt(buffer, 0xA001);
            putString(buffer, "text/plain");
            putString(buffer, "X-Custom");
            putString(buffer, "custom-value");
            putInt(buffer, 0xA003);
            putString(buffer, "42");
        });

        AjpResponseParser parser = new AjpResponseParser();
        parser.parse(frame);

        assertTrue(parser.isComplete());
        assertEquals(AjpConstants.FRAME_TYPE_SEND_HEADERS, parser.prefix);
        assertEquals(201, parser.getStatusCode());
        assertEquals("Created", parser.getReasonPhrase());

        HeaderMap headers = parser.getHeaders();
        assertEquals(3, headers.size());
        assertEquals("text/plain", headers.getFirst(Headers.CONTENT_TYPE));
        assertEquals("custom-value", headers.getFirst(HttpString.tryFromString("X-Custom")));
        assertEquals("42", headers.getFirst(Headers.CONTENT_LENGTH));
    }

    @Test
    void parsesResponseWithRepeatedHeaders() throws Exception {
        ByteBuffer frame = responseFrame(AjpConstants.FRAME_TYPE_SEND_HEADERS, 1, buffer -> {
            putInt(buffer, 200);
            putString(buffer, "OK");
            putInt(buffer, 2);
            putInt(buffer, 0xA003);
            putString(buffer, "a");
            putInt(buffer, 0xA003);
            putString(buffer, "b");
        });

        AjpResponseParser parser = new AjpResponseParser();
        parser.parse(frame);

        assertEquals("[a, b]", parser.getHeaders().get(Headers.CONTENT_LENGTH).toString());
    }

    @Test
    void parsesEveryByteWhenFrameIsFragmented() throws Exception {
        ByteBuffer frame = responseFrame(AjpConstants.FRAME_TYPE_SEND_HEADERS, 5, buffer -> {
            putInt(buffer, 200);
            putString(buffer, "OK");
            putInt(buffer, 1);
            putInt(buffer, 0xA001);
            putString(buffer, "text/html");
        });
        byte[] raw = new byte[frame.remaining()];
        frame.get(raw);

        AjpResponseParser parser = new AjpResponseParser();
        for (int i = 0; i < raw.length - 1; ++i) {
            parser.parse(ByteBuffer.wrap(new byte[] {raw[i]}));
            assertFalse(parser.isComplete(), "frame should not be complete at byte " + i);
        }
        parser.parse(ByteBuffer.wrap(new byte[] {raw[raw.length - 1]}));

        assertTrue(parser.isComplete());
        assertEquals(200, parser.getStatusCode());
        assertEquals("OK", parser.getReasonPhrase());
        assertEquals("text/html", parser.getHeaders().getFirst(Headers.CONTENT_TYPE));
    }

    @Test
    void waitsForMoreDataWhenStringCrossesBufferBoundary() throws Exception {
        ByteBuffer frame = responseFrame(AjpConstants.FRAME_TYPE_SEND_HEADERS, 1, buffer -> {
            putInt(buffer, 200);
            putString(buffer, "A reason phrase");
            putInt(buffer, 0);
        });

        AjpResponseParser parser = new AjpResponseParser();
        // stop in the middle of the reason phrase
        int split = 2 + 2 + 1 + 2 + 2 + 3;
        ByteBuffer first = frame.duplicate();
        first.limit(split);
        parser.parse(first);
        assertFalse(parser.isComplete());

        ByteBuffer second = frame.duplicate();
        second.position(split);
        parser.parse(second);
        assertTrue(parser.isComplete());
        assertEquals("A reason phrase", parser.getReasonPhrase());
    }

    @Test
    void parsesRequestBodyChunk() throws Exception {
        AjpResponseParser parser = new AjpResponseParser();
        parser.parse(responseFrame(AjpConstants.FRAME_TYPE_REQUEST_BODY_CHUNK, 2, buffer -> putInt(buffer, 513)));

        assertTrue(parser.isComplete());
        assertEquals(AjpConstants.FRAME_TYPE_REQUEST_BODY_CHUNK, parser.prefix);
        assertEquals(513, parser.getReadBodyChunkSize());
    }

    @Test
    void parsesSendBodyChunkLength() throws Exception {
        AjpResponseParser parser = new AjpResponseParser();
        parser.parse(responseFrame(AjpConstants.FRAME_TYPE_SEND_BODY_CHUNK, 2, buffer -> putInt(buffer, 7)));

        assertTrue(parser.isComplete());
        assertEquals(AjpConstants.FRAME_TYPE_SEND_BODY_CHUNK, parser.prefix);
        assertEquals(7, parser.currentIntegerPart);
    }

    @Test
    void parsesEndResponsePersistenceFlag() throws Exception {
        AjpResponseParser parser = new AjpResponseParser();

        parser.parse(responseFrame(AjpConstants.FRAME_TYPE_END_RESPONSE, 1, buffer -> buffer.put((byte) 1)));
        assertTrue(parser.isComplete());
        assertEquals(1, parser.currentIntegerPart);

        parser.reset();
        parser.parse(responseFrame(AjpConstants.FRAME_TYPE_END_RESPONSE, 1, buffer -> buffer.put((byte) 0)));
        assertTrue(parser.isComplete());
        assertEquals(0, parser.currentIntegerPart);
    }

    @Test
    void parsesCpongFrame() throws Exception {
        AjpResponseParser parser = new AjpResponseParser();
        parser.parse(AjpTestSupport.bytes(0x41, 0x42, 0x00, 0x01, AjpConstants.FRAME_TYPE_CPONG));

        assertTrue(parser.isComplete());
        assertEquals(AjpConstants.FRAME_TYPE_CPONG, parser.prefix);
    }

    @Test
    void unknownFrameTypeCompletesWithoutError() throws Exception {
        AjpResponseParser parser = new AjpResponseParser();
        parser.parse(AjpTestSupport.bytes(0x41, 0x42, 0x00, 0x01, 0x7E));

        assertTrue(parser.isComplete());
        assertEquals(0x7E, parser.prefix);
    }

    @Test
    void wrongMagicNumberIsRejected() {
        AjpResponseParser parser = new AjpResponseParser();
        IOException exception = assertThrows(IOException.class,
                () -> parser.parse(AjpTestSupport.bytes(0x41, 0x43)));
        assertEquals("Wrong magic number", exception.getMessage());
        assertFalse(parser.isComplete());
    }

    @Test
    void emptyBufferIsIgnored() throws Exception {
        AjpResponseParser parser = new AjpResponseParser();
        parser.parse(ByteBuffer.allocate(0));
        parser.parse(AjpTestSupport.bytes(0x12));

        assertFalse(parser.isComplete());
    }

    @Test
    void resetReturnsParserToInitialState() throws Exception {
        AjpResponseParser parser = new AjpResponseParser();
        parser.parse(responseFrame(AjpConstants.FRAME_TYPE_SEND_HEADERS, 1, buffer -> {
            putInt(buffer, 200);
            putString(buffer, "OK");
            putInt(buffer, 0);
        }));
        HeaderMap parsedHeaders = parser.getHeaders();

        parser.reset();

        assertFalse(parser.isComplete());
        assertEquals(0, parser.prefix);
        assertEquals(0, parser.getStatusCode());
        assertNull(parser.getReasonPhrase());
        assertEquals(0, parser.getHeaders().size());
        assertNotSame(parsedHeaders, parser.getHeaders());
        assertSame(parser.getHeaders(), parser.getHeaders());
    }
}

package io.undertow.protocols.ajp;

import static org.easymock.EasyMock.createNiceMock;
import static org.easymock.EasyMock.expect;
import static org.easymock.EasyMock.replay;

import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import io.undertow.server.DefaultByteBufferPool;
import io.undertow.util.AbstractAttachable;
import io.undertow.util.Attachable;
import io.undertow.util.HeaderMap;
import io.undertow.util.HttpString;
import org.xnio.OptionMap;
import org.xnio.StreamConnection;
import org.xnio.XnioIoThread;
import org.xnio.channels.Configurable;
import org.xnio.conduits.ConduitStreamSinkChannel;
import org.xnio.conduits.ConduitStreamSourceChannel;
import org.xnio.conduits.StreamSinkConduit;
import org.xnio.conduits.StreamSourceConduit;

/**
 * Small amount of plumbing shared by the AJP client tests.  The tests do not need a real
 * socket: all frame encoding/decoding exercised here is independent of the transport.
 */
final class AjpTestSupport {

    private AjpTestSupport() {
    }

    static ByteBuffer bytes(int... values) {
        byte[] data = new byte[values.length];
        for (int i = 0; i < values.length; ++i) {
            data[i] = (byte) values[i];
        }
        return ByteBuffer.wrap(data);
    }

    static void putInt(ByteBuffer buffer, int value) {
        buffer.put((byte) ((value >> 8) & 0xFF));
        buffer.put((byte) (value & 0xFF));
    }

    static void putString(ByteBuffer buffer, String value) {
        putInt(buffer, value.length());
        for (int i = 0; i < value.length(); ++i) {
            buffer.put((byte) value.charAt(i));
        }
        buffer.put((byte) 0);
    }

    static ByteBuffer responseFrame(int prefix, int dataLength, java.util.function.Consumer<ByteBuffer> payload) {
        ByteBuffer frame = ByteBuffer.allocate(1024);
        frame.put((byte) 0x41);
        frame.put((byte) 0x42);
        putInt(frame, dataLength);
        frame.put((byte) prefix);
        if (payload != null) {
            payload.accept(frame);
        }
        frame.flip();
        return frame;
    }

    static Attachable attachable() {
        return new AbstractAttachable() {
        };
    }

    static AjpClientChannel newClientChannel() {
        XnioIoThread ioThread = createNiceMock(XnioIoThread.class);
        replay(ioThread);
        return newClientChannel(ioThread, OptionMap.EMPTY);
    }

    static AjpClientChannel newClientChannel(int bufferSize) {
        XnioIoThread ioThread = createNiceMock(XnioIoThread.class);
        replay(ioThread);
        return new AjpClientChannel(newStreamConnection(ioThread), new DefaultByteBufferPool(false, bufferSize), OptionMap.EMPTY);
    }

    static AjpClientChannel newClientChannel(OptionMap settings, int bufferSize) {
        XnioIoThread ioThread = createNiceMock(XnioIoThread.class);
        replay(ioThread);
        return new AjpClientChannel(newStreamConnection(ioThread), new DefaultByteBufferPool(false, bufferSize), settings);
    }

    static AjpClientChannel newClientChannel(OptionMap settings) {
        XnioIoThread ioThread = createNiceMock(XnioIoThread.class);
        replay(ioThread);
        return newClientChannel(ioThread, settings);
    }

    static AjpClientChannel newClientChannel(XnioIoThread ioThread, OptionMap settings) {
        return new AjpClientChannel(newStreamConnection(ioThread), new DefaultByteBufferPool(false, 4096), settings);
    }

    static StreamConnection newStreamConnection(XnioIoThread ioThread) {
        StreamSourceConduit sourceConduit = createNiceMock(StreamSourceConduit.class);
        StreamSinkConduit sinkConduit = createNiceMock(StreamSinkConduit.class);
        replay(sourceConduit, sinkConduit);

        ConduitStreamSourceChannel sourceChannel = new ConduitStreamSourceChannel(Configurable.EMPTY, sourceConduit);
        ConduitStreamSinkChannel sinkChannel = new ConduitStreamSinkChannel(Configurable.EMPTY, sinkConduit);

        StreamConnection connection = createNiceMock(StreamConnection.class);
        expect(connection.getSourceChannel()).andStubReturn(sourceChannel);
        expect(connection.getSinkChannel()).andStubReturn(sinkChannel);
        expect(connection.getIoThread()).andStubReturn(ioThread);
        expect(connection.isOpen()).andStubReturn(true);
        replay(connection);
        return connection;
    }

    static AjpClientRequestClientStreamSinkChannel request(AjpClientChannel channel, HttpString method,
            String path, HeaderMap headers, Attachable attachable) {
        return channel.sendRequest(method, path, new HttpString("HTTP/1.1"), headers, attachable, null);
    }

    static DecodedRequest decodeRequest(ByteBuffer frame) {
        ByteBuffer buffer = frame.duplicate();
        if ((buffer.get() & 0xFF) != 0x12 || (buffer.get() & 0xFF) != 0x34) {
            throw new IllegalArgumentException("not an AJP request frame");
        }
        int frameLength = buffer.getShort() & 0xFFFF;
        int prefix = buffer.get() & 0xFF;
        int method = buffer.get() & 0xFF;
        String protocol = readString(buffer);
        String path = readString(buffer);
        String remoteAddress = readString(buffer);
        String remoteHost = readString(buffer);
        String serverName = readString(buffer);
        int serverPort = buffer.getShort() & 0xFFFF;
        int ssl = buffer.get() & 0xFF;
        int numHeaders = buffer.getShort() & 0xFFFF;
        List<DecodedHeader> headers = new ArrayList<>();
        for (int i = 0; i < numHeaders; ++i) {
            int start = buffer.position();
            int first = buffer.getShort() & 0xFFFF;
            if ((first & 0xFF00) != 0) {
                headers.add(new DecodedHeader(first, null, readString(buffer)));
            } else {
                buffer.position(start);
                headers.add(new DecodedHeader(-1, readString(buffer), readString(buffer)));
            }
        }
        Map<Integer, String> attributes = new LinkedHashMap<>();
        while (buffer.hasRemaining() && (buffer.get(buffer.position()) & 0xFF) != 0xFF) {
            int tag = buffer.get() & 0xFF;
            attributes.put(tag, readString(buffer));
        }
        if (buffer.hasRemaining()) {
            buffer.get();
        }
        return new DecodedRequest(frameLength, prefix, method, protocol, path, remoteAddress, remoteHost,
                serverName, serverPort, ssl, headers, attributes);
    }

    static String readString(ByteBuffer buffer) {
        int length = buffer.getShort() & 0xFFFF;
        if (length == 0xFFFF) {
            return null;
        }
        StringBuilder builder = new StringBuilder(length);
        for (int i = 0; i < length; ++i) {
            builder.append((char) (buffer.get() & 0xFF));
        }
        if (buffer.hasRemaining()) {
            buffer.get();
        }
        return builder.toString();
    }

    static final class DecodedHeader {
        final int code;
        final String name;
        final String value;

        DecodedHeader(int code, String name, String value) {
            this.code = code;
            this.name = name;
            this.value = value;
        }
    }

    static final class DecodedRequest {
        final int frameLength;
        final int prefix;
        final int method;
        final String protocol;
        final String path;
        final String remoteAddress;
        final String remoteHost;
        final String serverName;
        final int serverPort;
        final int ssl;
        final List<DecodedHeader> headers;
        final Map<Integer, String> attributes;

        DecodedRequest(int frameLength, int prefix, int method, String protocol, String path, String remoteAddress,
                String remoteHost, String serverName, int serverPort, int ssl, List<DecodedHeader> headers,
                Map<Integer, String> attributes) {
            this.frameLength = frameLength;
            this.prefix = prefix;
            this.method = method;
            this.protocol = protocol;
            this.path = path;
            this.remoteAddress = remoteAddress;
            this.remoteHost = remoteHost;
            this.serverName = serverName;
            this.serverPort = serverPort;
            this.ssl = ssl;
            this.headers = headers;
            this.attributes = attributes;
        }
    }
}

