import io.undertow.util.HttpString;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

@Tag("io.undertow.testutils.category.UnitTest")
class AjpUtilsTest {

    @Test
    void notNullTreatsOnlyNullAsAbsent() {
        assertFalse(AjpUtils.notNull((Boolean) null));
        assertFalse(AjpUtils.notNull(Boolean.FALSE));
        assertTrue(AjpUtils.notNull(Boolean.TRUE));

        assertEquals(0, AjpUtils.notNull((Integer) null));
        assertEquals(0, AjpUtils.notNull(Integer.valueOf(0)));
        assertEquals(-7, AjpUtils.notNull(Integer.valueOf(-7)));

        assertEquals("", AjpUtils.notNull((String) null));
        assertEquals("value", AjpUtils.notNull("value"));
    }

    @Test
    void putIntWritesBigEndianTwoBytes() {
        ByteBuffer buffer = ByteBuffer.allocate(6);
        AjpUtils.putInt(buffer, 0x1234);
        AjpUtils.putInt(buffer, 0x00FF);
        AjpUtils.putInt(buffer, 0xABCD);

        assertArrayEquals(new byte[] {0x12, 0x34, 0x00, (byte) 0xFF, (byte) 0xAB, (byte) 0xCD},
                buffer.array());
    }

    @Test
    void putIntUsesLowSixteenBits() {
        ByteBuffer buffer = ByteBuffer.allocate(4);
        AjpUtils.putInt(buffer, 0x12345678);
        AjpUtils.putInt(buffer, -1);

        assertArrayEquals(new byte[] {0x56, 0x78, (byte) 0xFF, (byte) 0xFF}, buffer.array());
    }

    @Test
    void putStringWritesLengthPayloadAndTerminator() {
        ByteBuffer buffer = ByteBuffer.allocate(32);
        AjpUtils.putString(buffer, "hello");

        buffer.flip();
        assertEquals(5, buffer.getShort() & 0xFFFF);
        byte[] payload = new byte[5];
        buffer.get(payload);
        assertArrayEquals("hello".getBytes(), payload);
        assertEquals(0, buffer.get());
        assertFalse(buffer.hasRemaining());
    }

    @Test
    void putStringSupportsEmptyString() {
        ByteBuffer buffer = ByteBuffer.allocate(8);
        AjpUtils.putString(buffer, "");

        assertArrayEquals(new byte[] {0, 0, 0}, new byte[] {buffer.get(0), buffer.get(1), buffer.get(2)});
    }

    @Test
    void putHttpStringWritesLengthPayloadAndTerminator() {
        ByteBuffer buffer = ByteBuffer.allocate(32);
        AjpUtils.putHttpString(buffer, HttpString.tryFromString("X-Test"));

        buffer.flip();
        assertEquals(6, buffer.getShort() & 0xFFFF);
        byte[] payload = new byte[6];
        buffer.get(payload);
        assertArrayEquals("X-Test".getBytes(), payload);
        assertEquals(0, buffer.get());
        assertFalse(buffer.hasRemaining());
    }

    @Test
    void writingToReadOnlyBufferFails() {
        ByteBuffer readOnly = ByteBuffer.allocate(4).asReadOnlyBuffer();
        assertThrows(ReadOnlyBufferException.class, () -> AjpUtils.putInt(readOnly, 1));
    }
}

