        assertEquals(Collections.singletonMap("value", ExchangeAttribute.class), builder.parameters());
        assertEquals(Collections.singleton("value"), builder.requiredParameters());
        assertEquals("value", builder.defaultParameter());
        assertEquals(0, builder.priority());
    }

    @Test
    void rewriteBuilderPrependsSlashToConstantValue() throws Exception {
        RewriteHandlerBuilder builder = new RewriteHandlerBuilder();
        HandlerWrapper wrapper = builder.build(
                Collections.<String, Object>singletonMap("value", new ConstantExchangeAttribute("newPath")));

        HandlerTestSupport.RecordingHandler next = new HandlerTestSupport.RecordingHandler();
        HttpHandler handler = wrapper.wrap(next);
        assertInstanceOf(SetAttributeHandler.class, handler);

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        exchange.setResolvedPath("/app");
        handler.handleRequest(exchange);

        assertEquals("/newPath", exchange.getRelativePath());
        assertEquals("/app/newPath", exchange.getRequestURI());
        assertEquals("/app/newPath", exchange.getRequestPath());
        assertEquals(1, next.invocations);
    }

    @Test
    void rewriteBuilderKeepsLeadingSlashOfConstantValue() throws Exception {
        RewriteHandlerBuilder builder = new RewriteHandlerBuilder();

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        builder.build(Collections.<String, Object>singletonMap("value", new ConstantExchangeAttribute("/already/absolute")))
                .wrap(noop())
                .handleRequest(exchange);

        assertEquals("/already/absolute", exchange.getRelativePath());
        assertEquals("/already/absolute", exchange.getRequestURI());
    }

    @Test
    void rewriteBuilderEvaluatesNonConstantAttributeForEveryRequest() throws Exception {
        ExchangeAttribute dynamicAttribute = new ExchangeAttribute() {
            @Override
            public String readAttribute(HttpServerExchange exchange) {
                return "query" + exchange.getQueryString();
            }

            @Override
            public void writeAttribute(HttpServerExchange exchange, String newValue) throws ReadOnlyAttributeException {
                throw new ReadOnlyAttributeException("dynamic", newValue);
            }
        };
        RewriteHandlerBuilder builder = new RewriteHandlerBuilder();
        HttpHandler handler = builder.build(
                Collections.<String, Object>singletonMap("value", dynamicAttribute)).wrap(noop());

        HttpServerExchange first = HandlerTestSupport.exchange().setQueryString("one");
        handler.handleRequest(first);
        assertEquals("/queryone", first.getRelativePath());

        HttpServerExchange second = HandlerTestSupport.exchange().setQueryString("two");
        handler.handleRequest(second);
        assertEquals("/querytwo", second.getRelativePath());
    }

    @Test
    void rewriteBuilderWrappedNonConstantAttributeIsReadOnly() {
        ExchangeAttribute dynamicAttribute = new ExchangeAttribute() {
            @Override
            public String readAttribute(HttpServerExchange exchange) {
                return "value";
            }

            @Override
            public void writeAttribute(HttpServerExchange exchange, String newValue) throws ReadOnlyAttributeException {
                throw new ReadOnlyAttributeException("dynamic", newValue);
            }
        };
        RewriteHandlerBuilder builder = new RewriteHandlerBuilder();
        SetAttributeHandler handler = assertInstanceOf(SetAttributeHandler.class,
                builder.build(Collections.<String, Object>singletonMap("value", dynamicAttribute)).wrap(noop()));

        ExchangeAttribute storedValue = handler.getValue();
        assertNotNull(storedValue);
        assertThrows(ReadOnlyAttributeException.class,
                () -> storedValue.writeAttribute(HandlerTestSupport.exchange(), "other"));
    }

    @Test
    void rewriteBuilderHandlerDescriptionContainsTheTargetPath() {
        RewriteHandlerBuilder builder = new RewriteHandlerBuilder();
        HttpHandler handler = builder.build(
                Collections.<String, Object>singletonMap("value", new ConstantExchangeAttribute("/target"))).wrap(noop());

        assertEquals("rewrite( '/target' )", handler.toString());
    }

    @Test
    void responseBuilderUsesDefaultContentTypeWhenBodyHasNoType() {
        ResponseHandlerBuilder builder = new ResponseHandlerBuilder();
        Map<String, Object> config = new HashMap<>();
        config.put("code", 200);
        config.put("body", "payload");

        HttpHandler handler = builder.build(config).wrap(noop());

        assertEquals("response( code='200', type='text/html', body='payload' )", handler.toString());
    }

    @Test
    void rewriteBuilderNormalizesEmptyConstantToRootPath() throws Exception {
        RewriteHandlerBuilder builder = new RewriteHandlerBuilder();

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        builder.build(Collections.<String, Object>singletonMap("value", new ConstantExchangeAttribute("")))
                .wrap(noop())
                .handleRequest(exchange);

        assertEquals("/", exchange.getRelativePath());
    }


