/**
 * Tests for the plain value holder that pairs a predicate with a handler.
 */
@Tag("io.undertow.testutils.category.UnitTest")
class PredicatedHandlerTest {

    private static final HandlerWrapper WRAPPER = new HandlerWrapper() {
        @Override
        public HttpHandler wrap(HttpHandler handler) {
            return handler;
        }
    };

    private static final HandlerWrapper ELSE_WRAPPER = new HandlerWrapper() {
        @Override
        public HttpHandler wrap(HttpHandler handler) {
            return handler;
        }
    };

    @Test
    void twoArgumentConstructorLeavesElseHandlerNull() {
        Predicate predicate = Predicates.truePredicate();

        PredicatedHandler predicatedHandler = new PredicatedHandler(predicate, WRAPPER);

        assertSame(predicate, predicatedHandler.getPredicate());
        assertSame(WRAPPER, predicatedHandler.getHandler());
        assertNull(predicatedHandler.getElseHandler());
    }

    @Test
    void threeArgumentConstructorExposesAllValues() {
        Predicate predicate = Predicates.falsePredicate();

        PredicatedHandler predicatedHandler = new PredicatedHandler(predicate, WRAPPER, ELSE_WRAPPER);

        assertSame(predicate, predicatedHandler.getPredicate());
        assertSame(WRAPPER, predicatedHandler.getHandler());
        assertSame(ELSE_WRAPPER, predicatedHandler.getElseHandler());
    }

    @Test
    void explicitNullElseHandlerIsReportedAsNull() {
        PredicatedHandler predicatedHandler = new PredicatedHandler(Predicates.truePredicate(), WRAPPER, null);

        assertNull(predicatedHandler.getElseHandler());
    }

    @Test
    void gettersDoNotWrapTheHandlerChain() {
        int[] wrapCalls = {0};
        HandlerWrapper countingWrapper = new HandlerWrapper() {
            @Override
            public HttpHandler wrap(HttpHandler handler) {
                wrapCalls[0]++;
                return handler;
            }
        };

        PredicatedHandler predicatedHandler = new PredicatedHandler(Predicates.truePredicate(), countingWrapper);

        assertSame(countingWrapper, predicatedHandler.getHandler());
        assertEquals(0, wrapCalls[0], "the PredicatedHandler is a passive holder and must not wrap handlers");
    }

    @Test
    void predicateOfHolderCanBeResolvedAgainstAnExchange() {
        HttpServerExchange exchange = HandlerTestSupport.exchange().setRelativePath("/holder");
        PredicatedHandler predicatedHandler = new PredicatedHandler(
                PredicatedHandlersParser.parsePredicate("path('/holder')", getClass().getClassLoader()), WRAPPER);

        assertTrue(predicatedHandler.getPredicate().resolve(exchange));
    }
}
