/**
 * Tests for the textual handler/predicate parser.
 */
@Tag("io.undertow.testutils.category.UnitTest")
class PredicatedHandlersParserTest {

    @TempDir
    Path tempDir;

    private static ClassLoader classLoader() {
        return PredicatedHandlersParserTest.class.getClassLoader();
    }

    // ------------------------------------------------------------------
    // tokenizer
    // ------------------------------------------------------------------

    @Test
    void tokenizeSplitsASimpleHandlerCall() {
        assertEquals(List.of("response-code", "(", "404", ")"), tokens("response-code(404)"));
    }

    @Test
    void tokenizeHandlesNamedParametersAndArrow() {
        assertEquals(List.of("path", "(", "/foo", ")", "->", "response-code", "(", "200", ")"),
                tokens("path('/foo') -> response-code(200)"));
    }

    @Test
    void tokenizeHandlesQuotedAndBracketSyntax() {
        assertEquals(List.of("rewrite", "[", "value", "=", "/path", "]"),
                tokens("rewrite[value=\"/path\"]"));
    }

    @Test
    void tokenizeHandlesCurlyBraceArrays() {
        assertEquals(List.of("path", "(", "{", "/a", ",", "/b", "}", ")"),
                tokens("path({'/a','/b'})"));
    }

    @Test
    void tokenizeUnescapesQuotesInsideQuotedValues() {
        assertEquals(List.of("reason-phrase", "(", "it's", ")"), tokens("reason-phrase('it\\'s')"));
    }

    @Test
    void tokenizeKeepsExchangeAttributeTokensIntact() {
        assertEquals(List.of("rewrite", "[", "value", "=", "%{RELATIVE_PATH}", "]"),
                tokens("rewrite[value=%{RELATIVE_PATH}]"));
    }

    @Test
    void tokenizeEmitsStatementSeparators() {
        assertEquals(List.of("response-code", "(", "200", ")", ";", "response-code", "(", "404", ")"),
                tokens("response-code(200);response-code(404)"));
    }

    @Test
    void tokenizeSkipsWholeLineComments() {
        List<String> tokens = tokens("# this line is ignored\nresponse-code(200)");

        assertTrue(tokens.contains("response-code"));
        assertFalse(tokens.contains("#"));
        assertFalse(tokens.contains("ignored"));
    }

    @Test
    void tokenizeOfEmptyStringProducesNoTokens() {
        assertTrue(tokens("").isEmpty());
    }

    // ------------------------------------------------------------------
    // handler parsing
    // ------------------------------------------------------------------

    @Test
    void parseHandlerWithDefaultParameter() throws Exception {
        HandlerWrapper wrapper = HandlerParser.parse("response-code(418)", classLoader());

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        wrapper.wrap(noop()).handleRequest(exchange);
        assertEquals(418, exchange.getStatusCode());
    }

    @Test
    void parseHandlerWithNamedParameterAndOldStyleBrackets() throws Exception {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("response-code[value=403]", classLoader());

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        wrapper.wrap(noop()).handleRequest(exchange);
        assertEquals(403, exchange.getStatusCode());
    }

    @Test
    void parseHandlerWithQuotedStringParameter() throws Exception {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("reason-phrase('Out to lunch')", classLoader());

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        wrapper.wrap(noop()).handleRequest(exchange);
        assertEquals("Out to lunch", exchange.getReasonPhrase());
    }

    @Test
    void parseHandlerCoercesExchangeAttributeParameters() throws Exception {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("rewrite('/static')", classLoader());

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        wrapper.wrap(noop()).handleRequest(exchange);
        assertEquals("/static", exchange.getRelativePath());
        assertEquals("/static", exchange.getRequestURI());
    }

    @Test
    void parseHandlerParsesUndertowStyleAttributeExpressions() throws Exception {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("rewrite(%{METHOD})", classLoader());

        HttpServerExchange exchange = HandlerTestSupport.exchange().setRequestMethod(Methods.GET);
        wrapper.wrap(noop()).handleRequest(exchange);
        assertEquals("/GET", exchange.getRelativePath());
        assertEquals("/GET", exchange.getRequestURI());
    }

    @Test
    void parseHandlerPassesAllResponseParameters() {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler(
                "response(code=200, reason='OK', type='text/plain', body='hello')", classLoader());

        HttpHandler handler = wrapper.wrap(noop());
        assertEquals("response( code='200', reason='OK', type='text/plain', body='hello' )",
                handler.toString());
    }

    @Test
    void parseHandlerUnescapesQuotedParameterValues() throws Exception {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("reason-phrase('it\\'s fine')", classLoader());

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        wrapper.wrap(noop()).handleRequest(exchange);
        assertEquals("it's fine", exchange.getReasonPhrase());
    }

    @Test
    void parseHandlerCoercesArrayParameters() throws Exception {
        HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("allowed-methods(GET, POST)", classLoader());

        HandlerTestSupport.RecordingHandler next = new HandlerTestSupport.RecordingHandler();
        HttpHandler handler = wrapper.wrap(next);

        handler.handleRequest(HandlerTestSupport.exchange().setRequestMethod(Methods.POST));
        handler.handleRequest(HandlerTestSupport.exchange().setRequestMethod(Methods.GET));
        assertEquals(2, next.invocations);
    }

    @Test
    void parseHandlerRejectsUnknownHandler() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("no-such-handler(1)", classLoader()));

        assertTrue(e.getMessage().contains("no handler named no-such-handler"), e.getMessage());
    }

    @Test
    void parseHandlerRejectsMissingRequiredParameters() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("response-code()", classLoader()));

        assertTrue(e.getMessage().contains("required parameters [value] not provided for handler response-code"),
                e.getMessage());
    }

    @Test
    void parseHandlerRejectsUnknownParameters() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("response-code(other=200)", classLoader()));

        assertTrue(e.getMessage().contains("unknown parameter other"), e.getMessage());
    }

    @Test
    void parseHandlerRejectsArrayValueForScalarParameter() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("response-code(value={200,201})", classLoader()));

        assertTrue(e.getMessage().contains("parameter is not an array type value"), e.getMessage());
    }

    @Test
