        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.POST)));
    }

    @Test
    void parsePredicateMatchesRelativePath() {
        Predicate predicate = PredicatedHandlersParser.parsePredicate("path('/admin')", classLoader());

        assertTrue(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/admin")));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/admin/other")));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/public")));
    }

    @Test
    void parsePredicateSupportsMultiplePathValues() {
        Predicate predicate = PredicatedHandlersParser.parsePredicate("path({'/a','/b'})", classLoader());

        assertTrue(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/a")));
        assertTrue(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/b")));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRelativePath("/c")));
    }

    @Test
    void parsePredicateSupportsConstants() {
        assertTrue(PredicatedHandlersParser.parsePredicate("true", classLoader())
                .resolve(HandlerTestSupport.exchange()));
        assertFalse(PredicatedHandlersParser.parsePredicate("false", classLoader())
                .resolve(HandlerTestSupport.exchange()));
    }

    @Test
    void parsePredicateSupportsAndOrNot() {
        ClassLoader cl = classLoader();

        Predicate and = PredicatedHandlersParser.parsePredicate("method(GET) and path('/a')", cl);
        assertTrue(and.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/a")));
        assertFalse(and.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.POST).setRelativePath("/a")));
        assertFalse(and.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/b")));

        Predicate or = PredicatedHandlersParser.parsePredicate("method(PUT) or path('/a')", cl);
        assertTrue(or.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.PUT).setRelativePath("/z")));
        assertTrue(or.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/a")));
        assertFalse(or.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/z")));

        Predicate not = PredicatedHandlersParser.parsePredicate("not method(GET)", cl);
        assertFalse(not.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET)));
        assertTrue(not.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.POST)));
