                "path('/a') -> response-code(200); else response-code(404);", classLoader());

        assertEquals(1, handlers.size());
        assertNotNull(handlers.get(0).getElseHandler());

        HttpServerExchange unmatched = HandlerTestSupport.exchange();
        handlers.get(0).getElseHandler().wrap(noop()).handleRequest(unmatched);
        assertEquals(404, unmatched.getStatusCode());
    }


    @Test
    void parseSingleRule() throws Exception {
