@SuppressWarnings("deprecation")
@Tag("io.undertow.testutils.category.UnitTest")
class HandlerBuilderImplementationsTest {

    private static ClassLoader classLoader() {
        return HandlerBuilderImplementationsTest.class.getClassLoader();
