    @Test
    void handlerBuilderDefaultPriorityIsOne() {
        HandlerBuilder builder = new HandlerBuilder() {
            @Override
            public String name() {
                return "custom";
            }

            @Override
            public Map<String, Class<?>> parameters() {
                return Collections.emptyMap();
            }

            @Override
            public Set<String> requiredParameters() {
                return Collections.emptySet();
            }

            @Override
            public String defaultParameter() {
                return null;
            }

            @Override
            public HandlerWrapper build(Map<String, Object> config) {
                return handler -> handler;
            }
        };

        assertEquals(1, builder.priority());
    }

    // ------------------------------------------------------------------
    // ResponseCodeHandlerBuilder
    // ------------------------------------------------------------------

    @Test
    void responseCodeBuilderDescribesItself() {
        ResponseCodeHandlerBuilder builder = new ResponseCodeHandlerBuilder();

        assertEquals("response-code", builder.name());
        assertEquals(Collections.singletonMap("value", Integer.class), builder.parameters());
        assertEquals(Collections.singleton("value"), builder.requiredParameters());
        assertEquals("value", builder.defaultParameter());
        assertEquals(0, builder.priority());
    }

    @Test
    void responseCodeBuilderBuildsHandlerThatSetsStatusAndContinues() throws Exception {
        ResponseCodeHandlerBuilder builder = new ResponseCodeHandlerBuilder();
        HandlerWrapper wrapper = builder.build(Collections.<String, Object>singletonMap("value", 404));

        HandlerTestSupport.RecordingHandler next = new HandlerTestSupport.RecordingHandler();
        HttpHandler handler = wrapper.wrap(next);
        assertInstanceOf(ResponseCodeHandler.class, handler);

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        handler.handleRequest(exchange);

        assertEquals(404, exchange.getStatusCode());
        assertEquals(1, next.invocations);
    }

    @Test
    void responseCodeBuilderUsesConfiguredValue() throws Exception {
        ResponseCodeHandlerBuilder builder = new ResponseCodeHandlerBuilder();

        for (int code : new int[] {200, 301, 500}) {
            HttpServerExchange exchange = HandlerTestSupport.exchange();
            builder.build(Collections.<String, Object>singletonMap("value", code))
                    .wrap(noop())
                    .handleRequest(exchange);
            assertEquals(code, exchange.getStatusCode());
        }
    }

    // ------------------------------------------------------------------
    // ReasonPhraseHandlerBuilder
    // ------------------------------------------------------------------

    @Test
    void reasonPhraseBuilderDescribesItself() {
        ReasonPhraseHandlerBuilder builder = new ReasonPhraseHandlerBuilder();

        assertEquals("reason-phrase", builder.name());
        assertEquals(Collections.singletonMap("value", String.class), builder.parameters());
        assertEquals(Collections.singleton("value"), builder.requiredParameters());
        assertEquals("value", builder.defaultParameter());
        assertEquals(1, builder.priority());
    }

    @Test
    void reasonPhraseBuilderSetsReasonPhraseBeforeContinuing() throws Exception {
        ReasonPhraseHandlerBuilder builder = new ReasonPhraseHandlerBuilder();
        HandlerWrapper wrapper = builder.build(Collections.<String, Object>singletonMap("value", "I am a teapot"));

        HandlerTestSupport.RecordingHandler next = new HandlerTestSupport.RecordingHandler();
        HttpHandler handler = wrapper.wrap(next);

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        handler.handleRequest(exchange);

        assertEquals("I am a teapot", exchange.getReasonPhrase());
        assertEquals("I am a teapot", next.reasonPhraseSeen);
        assertEquals(1, next.invocations);
    }

    @Test
    void reasonPhraseBuilderDoesNotChangeTheStatusCode() throws Exception {
        ReasonPhraseHandlerBuilder builder = new ReasonPhraseHandlerBuilder();

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        builder.build(Collections.<String, Object>singletonMap("value", "Custom"))
                .wrap(noop())
                .handleRequest(exchange);

        assertEquals(200, exchange.getStatusCode());
    }

