        expected.put("code", Integer.class);
        expected.put("reason", String.class);
        expected.put("type", String.class);
        expected.put("body", String.class);
        assertEquals(expected, builder.parameters());
        assertEquals(Collections.singleton("code"), builder.requiredParameters());
        assertNull(builder.defaultParameter());
        assertEquals(1, builder.priority());
    }

    @Test
    void responseBuilderSetsCodeOnly() throws Exception {
        ResponseHandlerBuilder builder = new ResponseHandlerBuilder();
        Map<String, Object> config = new HashMap<>();
        config.put("code", 204);

        HandlerTestSupport.RecordingHandler next = new HandlerTestSupport.RecordingHandler();
        HttpHandler handler = builder.build(config).wrap(next);
        assertInstanceOf(ResponseHandler.class, handler);

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        handler.handleRequest(exchange);

        assertEquals(204, exchange.getStatusCode());
        assertNull(exchange.getReasonPhrase());
        assertFalse(exchange.getResponseHeaders().contains(Headers.CONTENT_TYPE));
        assertEquals(0, next.invocations,
                "the response handler terminates the exchange itself and does not invoke the wrapped handler");
    }

    @Test
    void responseBuilderSetsCodeAndReason() throws Exception {
        ResponseHandlerBuilder builder = new ResponseHandlerBuilder();
        Map<String, Object> config = new HashMap<>();
        config.put("code", 404);
