        HttpServerExchange first = HandlerTestSupport.exchange().setQueryString("one");
        handler.handleRequest(first);
        assertEquals("/queryone", first.getRelativePath());

        HttpServerExchange second = HandlerTestSupport.exchange().setQueryString("two");
        handler.handleRequest(second);
        assertEquals("/querytwo", second.getRelativePath());
    }

    @Test
