    @Test
    void rewriteBuilderHandlerDescriptionContainsTheTargetPath() {
        RewriteHandlerBuilder builder = new RewriteHandlerBuilder();
        HttpHandler handler = builder.build(
                Collections.<String, Object>singletonMap("value", new ConstantExchangeAttribute("/target"))).wrap(noop());

        assertEquals("rewrite( '/target' )", handler.toString());
