    void responseBuilderUsesDefaultContentTypeWhenBodyHasNoType() {
        ResponseHandlerBuilder builder = new ResponseHandlerBuilder();
        Map<String, Object> config = new HashMap<>();
        config.put("code", 200);
        config.put("body", "payload");

