        assertEquals("response( code='200', type='text/html', body='payload' )", handler.toString());
    }

    @Test
    void rewriteBuilderNormalizesEmptyConstantToRootPath() throws Exception {
        RewriteHandlerBuilder builder = new RewriteHandlerBuilder();

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        builder.build(Collections.<String, Object>singletonMap("value", new ConstantExchangeAttribute("")))
                .wrap(noop())
                .handleRequest(exchange);

        assertEquals("/", exchange.getRelativePath());
    }


