package io.undertow.server.handlers.builder;

import io.undertow.server.HttpHandler;
import io.undertow.server.HttpServerExchange;

/**
 * Small, dependency free helpers shared by the tests for the handler builder module.
 * <p>
 * The exchange is created without a backing connection; the handlers under test only touch
 * request/response state that lives on the exchange itself, so no real I/O is required.
 */
final class HandlerTestSupport {

    private HandlerTestSupport() {
    }

    static HttpServerExchange exchange() {
        return new HttpServerExchange(null);
    }

    /**
     * Next handler that records the exchanges it sees.
     */
    static final class RecordingHandler implements HttpHandler {

        int invocations;
        HttpServerExchange lastExchange;
        String reasonPhraseSeen;

        @Override
        public void handleRequest(HttpServerExchange exchange) throws Exception {
            invocations++;
            lastExchange = exchange;
            reasonPhraseSeen = exchange.getReasonPhrase();
        }
    }
}

