package io.undertow.server.handlers.builder;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.net.URLClassLoader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

import io.undertow.predicate.Predicate;
import io.undertow.predicate.PredicateBuilder;
import io.undertow.server.HandlerWrapper;
import io.undertow.server.HttpHandler;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Tests for the {@link java.util.ServiceLoader} based builder lookup and for the parameter
 * coercion performed by the parser, using builders that are only visible to a dedicated
 * class loader.
 */
@Tag("io.undertow.testutils.category.UnitTest")
class PredicatedHandlersParserDiscoveryTest {

    @TempDir
    Path tempDir;

    // ------------------------------------------------------------------
    // builder discovery
    // ------------------------------------------------------------------
    @Test
    void discoversHandlerBuildersFromTheSuppliedClassLoader() throws Exception {
        try (URLClassLoader loader = loaderWithServices(HandlerBuilder.class,
                CoercionHandlerBuilder.class.getName())) {
            HandlerWrapper wrapper = PredicatedHandlersParser.parseHandler("test-coercion(hello)", loader);

            // the build method is only reached when the custom builder was discovered
            assertEquals("hello", CoercionHandlerBuilder.lastConfig().get("string"));
            HttpHandler next = exchange -> {
            };
            assertSame(next, wrapper.wrap(next));
        }
    }


    @Test
    void usesDefaultParameterNameWhenNoNameIsGiven() throws Exception {
        try (URLClassLoader loader = loaderWithServices(HandlerBuilder.class,
                CoercionHandlerBuilder.class.getName())) {

            PredicatedHandlersParser.parseHandler("test-coercion(1234)", loader);

            Map<String, Object> config = CoercionHandlerBuilder.lastConfig();
            assertEquals(1, config.size());
            assertEquals("1234", config.get("string"));
        }
    }

    @Test
    void rejectsDuplicateHandlerNames() throws Exception {
        try (URLClassLoader loader = loaderWithServices(HandlerBuilder.class,
                CoercionHandlerBuilder.class.getName(),
                DuplicateCoercionHandlerBuilder.class.getName())) {

            IllegalStateException e = assertThrows(IllegalStateException.class,
                    () -> PredicatedHandlersParser.parseHandler("test-coercion(hello)", loader));

            assertTrue(e.getMessage().contains("More than one handler with name test-coercion"), e.getMessage());
        }
    }

    @Test
    void rejectsDuplicatePredicateNames() throws Exception {
        try (URLClassLoader loader = loaderWithServices(PredicateBuilder.class,
                MarkerPredicateBuilder.class.getName(),
                DuplicateMarkerPredicateBuilder.class.getName())) {

            IllegalStateException e = assertThrows(IllegalStateException.class,
                    () -> PredicatedHandlersParser.parsePredicate("test-marker", loader));

            assertTrue(e.getMessage().contains("More than one predicate with name test-marker"), e.getMessage());
        }
    }

    // ------------------------------------------------------------------
    // parameter coercion
    // ------------------------------------------------------------------

    @Test
    void coercesAllSupportedScalarParameterTypes() throws Exception {
        try (URLClassLoader loader = loaderWithServices(HandlerBuilder.class,
                CoercionHandlerBuilder.class.getName())) {

            PredicatedHandlersParser.parseHandler("test-coercion(string=hello, integer=42, primitive-int=7, "
                    + "long=99, float=1.5, double=2.25, byte=3, short=4, boolean=true, character=x)", loader);

            Map<String, Object> config = CoercionHandlerBuilder.lastConfig();
            assertEquals("hello", config.get("string"));
            assertEquals(Integer.valueOf(42), config.get("integer"));
            assertEquals(Integer.valueOf(7), config.get("primitive-int"));
            assertEquals(Long.valueOf(99), config.get("long"));
            assertEquals(Float.valueOf(1.5f), config.get("float"));
            assertEquals(Double.valueOf(2.25), config.get("double"));
            assertEquals(Byte.valueOf((byte) 3), config.get("byte"));
            assertEquals(Short.valueOf((short) 4), config.get("short"));
            assertEquals(Boolean.TRUE, config.get("boolean"));
            assertEquals(Character.valueOf('x'), config.get("character"));
        }
    }

    @Test
    void coercesArrayParametersToListOfComponents() throws Exception {
        try (URLClassLoader loader = loaderWithServices(HandlerBuilder.class,
                CoercionHandlerBuilder.class.getName())) {

            PredicatedHandlersParser.parseHandler("test-coercion(string=hello, array={a,b,c})", loader);

            assertArrayEquals(new String[] {"a", "b", "c"},
                    (String[]) CoercionHandlerBuilder.lastConfig().get("array"));
        }
    }

    @Test
    void rejectsCharacterParametersLongerThanOneCharacter() throws Exception {
        try (URLClassLoader loader = loaderWithServices(HandlerBuilder.class,
                CoercionHandlerBuilder.class.getName())) {

            IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                    () -> PredicatedHandlersParser.parseHandler("test-coercion(string=hello, character=too-long)", loader));

            assertTrue(e.getMessage().contains("Cannot coerce too-long to a Character"), e.getMessage());
        }
    }

    // ------------------------------------------------------------------
    // custom builders
    // ------------------------------------------------------------------

    /**
     * Handler builder exposing one parameter for every type that the parser knows how to coerce.
     */
    public static class CoercionHandlerBuilder implements HandlerBuilder {

        private static volatile Map<String, Object> lastConfig = new HashMap<>();

        static Map<String, Object> lastConfig() {
            return lastConfig;
        }

        @Override
        public String name() {
            return "test-coercion";
        }

        @Override
        public Map<String, Class<?>> parameters() {
            Map<String, Class<?>> parameters = new HashMap<>();
            parameters.put("string", String.class);
            parameters.put("integer", Integer.class);
            parameters.put("primitive-int", int.class);
            parameters.put("long", Long.class);
            parameters.put("float", Float.class);
            parameters.put("double", Double.class);
            parameters.put("byte", Byte.class);
            parameters.put("short", Short.class);
            parameters.put("boolean", Boolean.class);
            parameters.put("character", Character.class);
            parameters.put("array", String[].class);
            return parameters;
        }

        @Override
        public Set<String> requiredParameters() {
            return Set.of("string");
        }

        @Override
        public String defaultParameter() {
            return "string";
        }

        @Override
        public HandlerWrapper build(Map<String, Object> config) {
            lastConfig = new HashMap<>(config);
            return handler -> handler;
        }
    }

    /**
     * Same name as {@link CoercionHandlerBuilder} so that duplicate detection can be verified.
     */
    public static final class DuplicateCoercionHandlerBuilder extends CoercionHandlerBuilder {
    }

    /**
     * Predicate builder used to verify duplicate predicate detection.
     */
    public static final class MarkerPredicateBuilder implements PredicateBuilder {

        @Override
        public String name() {
            return "test-marker";
        }

        @Override
        public Map<String, Class<?>> parameters() {
            return Map.of();
        }

        @Override
        public Set<String> requiredParameters() {
            return Set.of();
        }

        @Override
        public String defaultParameter() {
            return null;
        }

        @Override
        public Predicate build(Map<String, Object> config) {
            return exchange -> true;
        }
    }

    /**
     * Same name as {@link MarkerPredicateBuilder} so that duplicate detection can be verified.
     */
    public static final class DuplicateMarkerPredicateBuilder implements PredicateBuilder {

        @Override
        public String name() {
            return "test-marker";
        }

        @Override
        public Map<String, Class<?>> parameters() {
            return Map.of();
        }

        @Override
        public Set<String> requiredParameters() {
            return Set.of();
        }

        @Override
        public String defaultParameter() {
            return null;
        }

        @Override
        public Predicate build(Map<String, Object> config) {
            return exchange -> false;
        }
    }

    // ------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------

    private URLClassLoader loaderWithServices(Class<?> serviceType, String... implementationClasses)
            throws IOException {
        Path serviceFile = tempDir.resolve("META-INF/services").resolve(serviceType.getName());
        Files.createDirectories(serviceFile.getParent());
        Files.write(serviceFile, String.join("\n", implementationClasses).getBytes(StandardCharsets.UTF_8));

        return new URLClassLoader(new java.net.URL[] {tempDir.toUri().toURL()}, getClass().getClassLoader());
    }
}

