    @Test
    void parseRuleWithSemicolonSeparatedElseBranch() throws Exception {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "path('/a') -> response-code(200); else response-code(404);", classLoader());

        assertEquals(1, handlers.size());
        assertNotNull(handlers.get(0).getElseHandler());

        HttpServerExchange unmatched = HandlerTestSupport.exchange();
        handlers.get(0).getElseHandler().wrap(noop()).handleRequest(unmatched);
        assertEquals(404, unmatched.getStatusCode());
    }


    @Test
    void parseSingleRule() throws Exception {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "path('/admin') -> response-code(403)", classLoader());

        assertEquals(1, handlers.size());
        PredicatedHandler handler = handlers.get(0);
        assertTrue(handler.getPredicate().resolve(HandlerTestSupport.exchange().setRelativePath("/admin")));
        assertFalse(handler.getPredicate().resolve(HandlerTestSupport.exchange().setRelativePath("/public")));
        assertNull(handler.getElseHandler());

        HttpServerExchange exchange = HandlerTestSupport.exchange();
        handler.getHandler().wrap(noop()).handleRequest(exchange);
        assertEquals(403, exchange.getStatusCode());
    }

    @Test
    void parseMultipleRules() throws Exception {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "path('/a') -> response-code(200)\npath('/b') -> response-code(404)\n", classLoader());

        assertEquals(2, handlers.size());

        HttpServerExchange first = HandlerTestSupport.exchange();
        handlers.get(0).getHandler().wrap(noop()).handleRequest(first);
        assertEquals(200, first.getStatusCode());

        HttpServerExchange second = HandlerTestSupport.exchange();
        handlers.get(1).getHandler().wrap(noop()).handleRequest(second);
        assertEquals(404, second.getStatusCode());
    }

    @Test
    void parseRuleWithElseBranch() throws Exception {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "method(GET) -> response-code(200) else response-code(405)", classLoader());

        assertEquals(1, handlers.size());
        PredicatedHandler handler = handlers.get(0);
        assertNotNull(handler.getElseHandler());

        Predicate predicate = handler.getPredicate();
        assertTrue(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET)));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.POST)));

        HttpServerExchange matched = HandlerTestSupport.exchange();
        handler.getHandler().wrap(noop()).handleRequest(matched);
        assertEquals(200, matched.getStatusCode());

        HttpServerExchange unmatched = HandlerTestSupport.exchange();
        handler.getElseHandler().wrap(noop()).handleRequest(unmatched);
        assertEquals(405, unmatched.getStatusCode());
    }

    @Test
    void parseRuleWithNestedBlockHandler() {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "path('/a') -> { response-code(200); response-code(201); }", classLoader());

        assertEquals(1, handlers.size());
        HandlerWrapper block = handlers.get(0).getHandler();

        assertInstanceOf(PredicatesHandler.Wrapper.class, block);
        assertInstanceOf(PredicatesHandler.class, block.wrap(noop()));
    }

    @Test
    void parseTopLevelBlockWithSeveralRules() {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "{ path('/a') -> response-code(200); path('/b') -> response-code(404); }", classLoader());

        assertEquals(2, handlers.size());
    }

    @Test
    void parseRuleWithCompoundPredicate() throws Exception {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "method(GET) and not path('/blocked') -> response-code(200)", classLoader());

        assertEquals(1, handlers.size());
        Predicate predicate = handlers.get(0).getPredicate();
        assertTrue(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/ok")));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.GET).setRelativePath("/blocked")));
        assertFalse(predicate.resolve(HandlerTestSupport.exchange().setRequestMethod(Methods.POST).setRelativePath("/ok")));
    }

    @Test
    void parseIgnoresCommentLines() {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "# rules below\npath('/a') -> response-code(200)\n", classLoader());

        assertEquals(1, handlers.size());
    }

    @Test
    void parseEmptyDocumentProducesNoHandlers() {
        assertTrue(PredicatedHandlersParser.parse("", classLoader()).isEmpty());
        assertTrue(PredicatedHandlersParser.parse("# only a comment", classLoader()).isEmpty());
    }

    @Test
    void parseRejectsUnknownHandlerInRule() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parse("path('/a') -> no-such-handler(1)", classLoader()));

        assertTrue(e.getMessage().contains("no handler named no-such-handler"), e.getMessage());
    }

    @Test
    void parseRejectsBarePredicateWithoutHandler() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parse("path('/a')", classLoader()));

        assertTrue(e.getMessage().contains("no handler named path"), e.getMessage());
    }

    @Test
    void parseRejectsUnexpectedClosingBraceAtTopLevel() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parse("}", classLoader()));

        assertTrue(e.getMessage().contains("Unexpected token"), e.getMessage());
    }

    // ------------------------------------------------------------------
    // file based parsing
    // ------------------------------------------------------------------

    @Test
    void parseFromPathAndFileAgree() throws IOException {
        String contents = "path('/a') -> response-code(200)\npath('/b') -> response-code(404)\n";
        Path file = tempDir.resolve("undertow-handlers.conf");
        Files.write(file, contents.getBytes(StandardCharsets.UTF_8));

        List<PredicatedHandler> fromPath = PredicatedHandlersParser.parse(file, classLoader());
        List<PredicatedHandler> fromFile = PredicatedHandlersParser.parse(file.toFile(), classLoader());

        assertEquals(2, fromPath.size());
        assertEquals(2, fromFile.size());
    }

    @Test
    void parseFromInputStream() throws Exception {
        String contents = "path('/a') -> response-code(201)";
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                new ByteArrayInputStream(contents.getBytes(StandardCharsets.UTF_8)), classLoader());

        assertEquals(1, handlers.size());
        HttpServerExchange exchange = HandlerTestSupport.exchange();
        handlers.get(0).getHandler().wrap(noop()).handleRequest(exchange);
        assertEquals(201, exchange.getStatusCode());
    }

    @Test
    void parseAcceptsWindowsLineEndings() {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(
                "path('/a') -> response-code(200)\r\npath('/b') -> response-code(404)\r\n", classLoader());

        assertEquals(2, handlers.size());
    }

    @Test
    void parseMissingFileFailsWithRuntimeException() {
        Path missing = tempDir.resolve("does-not-exist.conf");

        RuntimeException e = assertThrows(RuntimeException.class,
                () -> PredicatedHandlersParser.parse(missing, classLoader()));

        assertInstanceOf(IOException.class, e.getCause());
    }

    @Test
    void parseEmptyInputStreamProducesNoHandlers() {
        assertTrue(PredicatedHandlersParser.parse(
                new ByteArrayInputStream(new byte[0]), classLoader()).isEmpty());
    }


    // ------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------

    private static List<String> tokens(String input) {
        List<String> result = new ArrayList<>();
        for (PredicatedHandlersParser.Token token : PredicatedHandlersParser.tokenize(input)) {
            result.add(token.getToken());
        }
        return result;
    }

    private static HttpHandler noop() {
        return exchange -> {
        };
    }
}

