    @Test
    void extractsAuthenticationQueryAndConnectionAttributes() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();
        ByteBuffer packet = new AjpTestSupport.RequestBuilder()
                .requestUri("/secure")
                .attribute(5, "a=1&b=hello+world")
                .attribute(3, "alice")
                .attribute(4, "BASIC")
                .attribute(13, "PATCH")
                .namedAttribute(AjpRequestParser.AJP_REMOTE_PORT, "4321")
                .attribute(9, "31323334")
                .attribute(8, "TLS_AES_256_GCM_SHA384")
                .attribute(11, 256)
                .namedAttribute(AjpRequestParser.AJP_SSL_PROTOCOL, "TLSv1.3")
                .build();

        parser().parse(packet, state, exchange);

        assertEquals(Methods.PATCH, exchange.getRequestMethod());
        assertEquals("alice", exchange.getAttachment(ExternalAuthenticationMechanism.EXTERNAL_PRINCIPAL));
        assertEquals("alice", exchange.getAttachment(HttpServerExchange.REMOTE_USER));
        assertEquals("BASIC", exchange.getAttachment(ExternalAuthenticationMechanism.EXTERNAL_AUTHENTICATION_TYPE));
        assertEquals("a=1&b=hello+world", exchange.getQueryString());
        assertEquals("1", exchange.getQueryParameters().get("a").peekFirst());
        assertEquals("hello world", exchange.getQueryParameters().get("b").peekFirst());
        assertEquals(4321, state.remotePort);
        assertEquals(4321, state.createPeerAddress().getPort());
        assertNotNull(state.createSslSessionInfo());
        assertArrayEquals(new byte[] {'1', '2', '3', '4'}, state.createSslSessionInfo().getSessionId());
        assertEquals("TLS_AES_256_GCM_SHA384", state.createSslSessionInfo().getCipherSuite());
        assertEquals(256, state.createSslSessionInfo().getKeySize());
        assertEquals("TLSv1.3", state.createSslSessionInfo().getSecureProtocol());
    }

