            ByteBuffer second = ByteBuffer.allocate(8);

            long read = conduit.read(new ByteBuffer[] {first, second}, 0, 2);

            assertEquals(5, read);
            first.flip();
            second.flip();
            assertEquals("wo", new String(bytes(first), StandardCharsets.US_ASCII));
            assertEquals("rld", new String(bytes(second), StandardCharsets.US_ASCII));
        } finally {
            fixture.close();
        }
