    private static byte[] bodyPacket(String value) {
        byte[] body = value.getBytes(StandardCharsets.US_ASCII);
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write(0x12);
        out.write(0x34);
        out.write(((body.length + 2) >> 8) & 0xFF);
        out.write((body.length + 2) & 0xFF);
        out.write((body.length >> 8) & 0xFF);
        out.write(body.length & 0xFF);
        out.write(body, 0, body.length);
        return out.toByteArray();
    }

    private static byte[] bytes(ByteBuffer buffer) {
        byte[] bytes = new byte[buffer.remaining()];
        buffer.get(bytes);
        return bytes;
    }

    private static final class Fixture {
        private final ServerConnection connection = createNiceMock(ServerConnection.class);
        private final HttpServerExchange exchange;
        private final DefaultByteBufferPool pool = new DefaultByteBufferPool(false, 128);
        private final TestSourceConduit source;
        private final TestSinkConduit responseSink = new TestSinkConduit();
        private final AjpServerResponseConduit response;
        private final AtomicBoolean finished = new AtomicBoolean();

        private Fixture(byte[] sourceBytes) {
            expect(connection.getUndertowOptions()).andReturn(OptionMap.EMPTY).anyTimes();
            replay(connection);
            exchange = new HttpServerExchange(connection);
            source = new TestSourceConduit(sourceBytes);
            response = new AjpServerResponseConduit(responseSink, pool, exchange, null, false);
        }

        private AjpServerRequestConduit conduit(Long length) {
            return new AjpServerRequestConduit(source, exchange, response, length, channel -> {
                finished.set(true);
            });
        }

        private void close() {
            pool.close();
        }
    }
}
