import org.junit.jupiter.api.Test;
import org.xnio.OptionMap;

class AjpServerResponseConduitTest {

    @Test
    void writesSendHeadersAndBodyButFlushesHeadersOnlyOnce() throws Exception {
        DefaultByteBufferPool pool = new DefaultByteBufferPool(false, 256);
        try {
            HttpServerExchange exchange = exchange(OptionMap.EMPTY);
            exchange.setStatusCode(201);
            exchange.setReasonPhrase("Stored");
            exchange.getResponseHeaders().put(Headers.CONTENT_TYPE, "text/plain");
            exchange.getResponseHeaders().put(Headers.CONTENT_LANGUAGE, "en");
            exchange.getResponseHeaders().put(HttpString.tryFromString("X-Custom"), "line1\r\nline2");
            TestSinkConduit sink = new TestSinkConduit();
            AjpServerResponseConduit conduit = new AjpServerResponseConduit(
                    sink, pool, exchange, null, false);

            assertEquals(5, conduit.write(ByteBuffer.wrap("hello".getBytes(StandardCharsets.US_ASCII))));
            assertEquals(6, conduit.write(ByteBuffer.wrap(" world".getBytes(StandardCharsets.US_ASCII))));
            assertTrue(conduit.flush());

            List<byte[]> frames = frames(sink.bytes());
            assertEquals(4, frames.size());

            SendHeaders headers = sendHeaders(frames.get(0));
            assertEquals(201, headers.status);
            assertEquals("Stored", headers.reason);
            assertEquals(3, headers.headerCount);
            assertEquals("text/plain", headers.valueFor(0xA001));
            assertEquals("en", headers.valueFor(0xA002));
            assertEquals("line1  line2", headers.valueFor("X-Custom"));

            assertEquals("hello", stringBody(frames.get(1)));
            assertEquals(" world", stringBody(frames.get(2)));
            assertArrayEqualsBytes(new byte[] {3, 0, 0, 0}, frames.get(3));
        } finally {
            pool.close();
        }
    }

    @Test
    void headRequestConsumesTheBodyButDoesNotWriteABodyPacket() throws Exception {
        DefaultByteBufferPool pool = new DefaultByteBufferPool(false, 256);
        try {
            HttpServerExchange exchange = exchange(OptionMap.EMPTY);
            TestSinkConduit sink = new TestSinkConduit();
            AjpServerResponseConduit conduit = new AjpServerResponseConduit(
                    sink, pool, exchange, null, true);
            ByteBuffer body = ByteBuffer.wrap("not-sent".getBytes(StandardCharsets.US_ASCII));

            assertEquals(body.remaining(), conduit.write(body));
            assertFalse(body.hasRemaining());
            assertTrue(conduit.flush());

            List<byte[]> frames = frames(sink.bytes());
            assertEquals(2, frames.size());
            assertEquals(4, frames.get(0)[0]);
            assertArrayEqualsBytes(new byte[] {3, 0, 0, 0}, frames.get(1));
        } finally {
            pool.close();
        }
    }


    @Test
    void splitsLargeBodiesAtTheConfiguredMaximumAjpPacketSize() throws Exception {
        DefaultByteBufferPool pool = new DefaultByteBufferPool(false, 256);
        try {
            HttpServerExchange exchange = exchange(OptionMap.create(UndertowOptions.MAX_AJP_PACKET_SIZE, 16));
            TestSinkConduit sink = new TestSinkConduit();
            AjpServerResponseConduit conduit = new AjpServerResponseConduit(
                    sink, pool, exchange, null, false);
            ByteBuffer body = ByteBuffer.wrap("abcdefghijklmnopqrst".getBytes(StandardCharsets.US_ASCII));

            int written = 0;
            while (body.hasRemaining()) {
                written += conduit.write(body);
            }
            assertTrue(conduit.flush());

            assertEquals(20, written);
            List<byte[]> frames = frames(sink.bytes());
            assertEquals(5, frames.size());
            assertEquals("abcdefgh", stringBody(frames.get(1)));
            assertEquals("ijklmnop", stringBody(frames.get(2)));
            assertEquals("qrst", stringBody(frames.get(3)));
            assertArrayEqualsBytes(new byte[] {3, 0, 0, 0}, frames.get(4));
        } finally {
            pool.close();
        }
    }

    @Test
    void flattensResponseCookiesIntoSetCookieHeaders() throws Exception {
        DefaultByteBufferPool pool = new DefaultByteBufferPool(false, 128);
        try {
            HttpServerExchange exchange = exchange(OptionMap.EMPTY);
            exchange.setResponseCookie(new CookieImpl("session", "abc"));
            TestSinkConduit sink = new TestSinkConduit();
            AjpServerResponseConduit conduit = new AjpServerResponseConduit(
                    sink, pool, exchange, null, false);

            assertTrue(conduit.flush());

            SendHeaders headers = sendHeaders(frames(sink.bytes()).get(0));
            assertEquals(1, headers.headerCount);
            assertEquals("session=abc", headers.valueFor(0xA007));
        } finally {
            pool.close();
        }
    }

    @Test
    void terminateWritesAddsThePersistentClosePacketAndInvokesTheFinishListener() throws Exception {
        DefaultByteBufferPool pool = new DefaultByteBufferPool(false, 128);
        try {
            HttpServerExchange exchange = exchange(OptionMap.EMPTY);
            exchange.setPersistent(true);
            AtomicBoolean finished = new AtomicBoolean();
            TestSinkConduit sink = new TestSinkConduit();
            AjpServerResponseConduit conduit = new AjpServerResponseConduit(
                    sink, pool, exchange, c -> finished.set(true), false);

            conduit.terminateWrites();
            assertTrue(conduit.flush());
            assertTrue(finished.get());

            List<byte[]> frames = frames(sink.bytes());
            assertArrayEqualsBytes(new byte[] {5, 1}, frames.get(frames.size() - 1));
            assertTrue(conduit.isWriteShutdown());
        } finally {
            pool.close();
        }
    }

    @Test
    void terminateWritesAddsTheNonPersistentClosePacket() throws Exception {
        DefaultByteBufferPool pool = new DefaultByteBufferPool(false, 128);
        try {
            HttpServerExchange exchange = exchange(OptionMap.EMPTY);
            exchange.setPersistent(false);
            TestSinkConduit sink = new TestSinkConduit();
            AjpServerResponseConduit conduit = new AjpServerResponseConduit(
                    sink, pool, exchange, null, false);

            conduit.terminateWrites();
            assertTrue(conduit.flush());

            List<byte[]> frames = frames(sink.bytes());
            assertArrayEqualsBytes(new byte[] {5, 0}, frames.get(frames.size() - 1));
        } finally {
            pool.close();
        }
    }

    @Test
    void defaultReasonPhraseIsDerivedFromTheStatusCode() throws Exception {
        DefaultByteBufferPool pool = new DefaultByteBufferPool(false, 128);
        try {
            HttpServerExchange exchange = exchange(OptionMap.EMPTY);
            exchange.setStatusCode(404);
            TestSinkConduit sink = new TestSinkConduit();
            AjpServerResponseConduit conduit = new AjpServerResponseConduit(
                    sink, pool, exchange, null, false);

            assertTrue(conduit.flush());

            SendHeaders headers = sendHeaders(frames(sink.bytes()).get(0));
            assertEquals(404, headers.status);
            assertNotEquals("", headers.reason);
        } finally {
            pool.close();
        }
    }

    @Test
    void resumeAndSuspendAreReflectedByIsWriteResumed() throws Exception {
        DefaultByteBufferPool pool = new DefaultByteBufferPool(false, 128);
        try {
            HttpServerExchange exchange = exchange(OptionMap.EMPTY);
            TestSinkConduit sink = new TestSinkConduit();
            AjpServerResponseConduit conduit = new AjpServerResponseConduit(
                    sink, pool, exchange, null, false);

            assertFalse(conduit.isWriteResumed());
            conduit.resumeWrites();
            assertTrue(conduit.isWriteResumed());
            assertTrue(sink.isWriteResumed());
            conduit.suspendWrites();
            assertFalse(conduit.isWriteResumed());
            assertFalse(sink.isWriteResumed());
        } finally {
            pool.close();
        }
    }

    private static HttpServerExchange exchange(OptionMap options) {
        ServerConnection connection = createNiceMock(ServerConnection.class);
        expect(connection.getUndertowOptions()).andReturn(options).anyTimes();
        replay(connection);
        return new HttpServerExchange(connection);
    }

    private static List<byte[]> frames(byte[] bytes) {
        List<byte[]> frames = new ArrayList<>();
        int position = 0;
        while (position < bytes.length) {
            assertTrue(position + 4 <= bytes.length, "truncated AJP frame at " + position);
            assertEquals('A', bytes[position] & 0xFF, "frame position " + position + " in " + java.util.HexFormat.of().formatHex(bytes));
            assertEquals('B', bytes[position + 1] & 0xFF);
            int length = ((bytes[position + 2] & 0xFF) << 8) | (bytes[position + 3] & 0xFF);
            assertTrue(position + 4 + length <= bytes.length, "truncated AJP frame payload");
            frames.add(Arrays.copyOfRange(bytes, position + 4, position + 4 + length));
            position += 4 + length;
        }
        assertEquals(bytes.length, position);
        return frames;
    }

    private static SendHeaders sendHeaders(byte[] frame) {
        ByteBuffer buffer = ByteBuffer.wrap(frame);
        assertEquals(4, buffer.get() & 0xFF);
        int status = buffer.getShort() & 0xFFFF;
        String reason = readString(buffer);
        int headerCount = buffer.getShort() & 0xFFFF;
        SendHeaders result = new SendHeaders(status, reason, headerCount);
        for (int i = 0; i < headerCount; i++) {
            int mark = buffer.getShort(buffer.position()) & 0xFFFF;
            String name;
            if ((mark & 0xFF00) != 0) {
                buffer.position(buffer.position() + 2);
                name = Integer.toString(mark);
            } else {
                name = readString(buffer);
            }
            String value = readString(buffer);
            result.names.add(name);
            result.values.add(value);
        }
        assertFalse(buffer.hasRemaining(), "send-headers frame had trailing bytes");
        return result;
    }

    private static String stringBody(byte[] frame) {
        ByteBuffer buffer = ByteBuffer.wrap(frame);
        assertEquals(3, buffer.get() & 0xFF);
        int length = buffer.getShort() & 0xFFFF;
        byte[] data = new byte[length];
        buffer.get(data);
        assertEquals(0, buffer.get() & 0xFF);
        assertFalse(buffer.hasRemaining());
        return new String(data, StandardCharsets.US_ASCII);
    }

    private static String readString(ByteBuffer buffer) {
        int length = buffer.getShort() & 0xFFFF;
        byte[] data = new byte[length];
        buffer.get(data);
        assertEquals(0, buffer.get() & 0xFF);
        return new String(data, StandardCharsets.US_ASCII);
    }

    private static void assertArrayEqualsBytes(byte[] expected, byte[] actual) {
        org.junit.jupiter.api.Assertions.assertArrayEquals(expected, actual);
    }

    private static final class SendHeaders {
        private final int status;
        private final String reason;
        private final int headerCount;
        private final List<String> names = new ArrayList<>();
        private final List<String> values = new ArrayList<>();

        private SendHeaders(int status, String reason, int headerCount) {
            this.status = status;
            this.reason = reason;
            this.headerCount = headerCount;
        }

        private String valueFor(int encodedName) {
            return valueFor(Integer.toString(encodedName));
        }

        private String valueFor(String name) {
            int index = names.indexOf(name);
            return index == -1 ? null : values.get(index);
        }
    }
}
