package io.undertow.server.protocol.ajp;

import java.io.ByteArrayOutputStream;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

import io.undertow.server.HttpServerExchange;
import io.undertow.util.BadRequestException;

/**
 * Small builders and utilities shared by the AJP protocol tests. No network or
 * external service is used; every packet is held in memory.
 */
final class AjpTestSupport {

    private AjpTestSupport() {
    }

    static void parseFully(AjpRequestParser parser, ByteBuffer buffer, AjpRequestParseState state,
            HttpServerExchange exchange) throws Exception {
        while (buffer.hasRemaining() && !state.isComplete()) {
            parser.parse(buffer, state, exchange);
        }
    }

    static ByteBuffer packet(byte[] payload) {
        ByteBuffer buffer = ByteBuffer.allocate(payload.length + 4);
        buffer.put((byte) 0x12);
        buffer.put((byte) 0x34);
        buffer.put((byte) ((payload.length >> 8) & 0xFF));
        buffer.put((byte) (payload.length & 0xFF));
        buffer.put(payload);
        buffer.flip();
        return buffer;
    }

    static ByteBuffer simplePacket(int prefix) {
        return packet(new byte[] {(byte) prefix});
    }

    static final class RequestBuilder {
        private int method = 2;
        private String protocol = "HTTP/1.1";
        private String requestUri = "/";
        private String remoteAddress = "127.0.0.1";
        private String remoteHost = "localhost";
        private String serverName = "localhost";
        private int serverPort = 8080;
        private int ssl = 0;
        private final List<Header> headers = new ArrayList<>();
        private final List<Attribute> attributes = new ArrayList<>();

        RequestBuilder method(int method) {
            this.method = method;
            return this;
        }

        RequestBuilder protocol(String protocol) {
            this.protocol = protocol;
            return this;
        }

        RequestBuilder requestUri(String requestUri) {
            this.requestUri = requestUri;
            return this;
        }

        RequestBuilder remoteAddress(String remoteAddress) {
            this.remoteAddress = remoteAddress;
            return this;
        }

        RequestBuilder remoteHost(String remoteHost) {
            this.remoteHost = remoteHost;
            return this;
        }

        RequestBuilder serverName(String serverName) {
            this.serverName = serverName;
            return this;
        }

        RequestBuilder serverPort(int serverPort) {
            this.serverPort = serverPort;
            return this;
        }

        RequestBuilder ssl(boolean ssl) {
            this.ssl = ssl ? 1 : 0;
            return this;
        }

        RequestBuilder header(String name, String value) {
            headers.add(new Header(name, value, false));
            return this;
        }

        RequestBuilder commonHeader(int code, String value) {
            headers.add(new Header(null, value, true, code));
            return this;
        }

        RequestBuilder attribute(int code, String value) {
            attributes.add(new Attribute(value, false, null, code));
            return this;
        }

        RequestBuilder namedAttribute(String name, String value) {
            attributes.add(new Attribute(value, true, name, 0));
            return this;
        }

        RequestBuilder attribute(int code, int value) {
            attributes.add(new Attribute(null, false, null, code, value));
            return this;
        }

        ByteBuffer build() {
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            out.write(2); // FORWARD_REQUEST
            out.write(method);
            writeString(out, protocol);
            writeString(out, requestUri);
            writeString(out, remoteAddress);
            writeString(out, remoteHost);
            writeString(out, serverName);
            writeInt(out, serverPort);
            out.write(ssl);
            writeInt(out, headers.size());
            for (Header header : headers) {
                if (header.common) {
                    writeInt(out, 0xA000 | header.code);
                } else {
                    writeString(out, header.name);
                }
                writeString(out, header.value);
            }
            for (Attribute attribute : attributes) {
                if (attribute.named) {
                    out.write(0x0A);
                    writeString(out, attribute.name);
                } else {
                    out.write(attribute.code);
                }
                if (attribute.integerValue != null) {
                    writeInt(out, attribute.integerValue);
                } else {
                    writeString(out, attribute.value);
                }
            }
            out.write(0xFF);
            return packet(out.toByteArray());
        }
    }

    private static final class Header {
        private final String name;
        private final String value;
        private final boolean common;
        private final int code;

        private Header(String name, String value, boolean common) {
            this(name, value, common, 0);
        }

        private Header(String name, String value, boolean common, int code) {
            this.name = name;
            this.value = value;
            this.common = common;
            this.code = code;
        }
    }

    private static final class Attribute {
        private final String value;
        private final boolean named;
        private final String name;
        private final int code;
        private final Integer integerValue;

        private Attribute(String value, boolean named, String name, int code) {
            this(value, named, name, code, null);
        }

        private Attribute(String value, boolean named, String name, int code, Integer integerValue) {
            this.value = value;
            this.named = named;
            this.name = name;
            this.code = code;
            this.integerValue = integerValue;
        }
    }

    static void writeString(ByteArrayOutputStream out, String value) {
        if (value == null) {
            writeInt(out, 0xFFFF);
            return;
        }
        byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
        writeInt(out, bytes.length);
        out.write(bytes, 0, bytes.length);
        out.write(0);
    }

    static void writeInt(ByteArrayOutputStream out, int value) {
        out.write((value >> 8) & 0xFF);
        out.write(value & 0xFF);
    }

    static BadRequestException assertBadRequest(org.junit.jupiter.api.function.Executable executable) {
        return org.junit.jupiter.api.Assertions.assertThrows(BadRequestException.class, executable);
    }
}

/**
 * In-memory sink conduit used by response and request channel tests.
 */
final class TestSinkConduit implements org.xnio.conduits.StreamSinkConduit {

    final ByteArrayOutputStream output = new ByteArrayOutputStream();
    private boolean writeShutdown;
    private boolean resumed;
    private org.xnio.conduits.WriteReadyHandler writeReadyHandler;

    @Override
    public void terminateWrites() {
        writeShutdown = true;
    }

    @Override
    public boolean isWriteShutdown() {
        return writeShutdown;
    }

    @Override
    public void resumeWrites() {
        resumed = true;
    }

    @Override
    public void suspendWrites() {
        resumed = false;
    }

    @Override
    public void wakeupWrites() {
        resumed = true;
    }

    @Override
    public boolean isWriteResumed() {
        return resumed;
    }

    @Override
    public void awaitWritable() {
    }

    @Override
    public void awaitWritable(long time, java.util.concurrent.TimeUnit timeUnit) {
    }

    @Override
    public org.xnio.XnioIoThread getWriteThread() {
        return null;
    }

    @Override
    public void setWriteReadyHandler(org.xnio.conduits.WriteReadyHandler handler) {
        this.writeReadyHandler = handler;
    }

    org.xnio.conduits.WriteReadyHandler getWriteReadyHandler() {
        return writeReadyHandler;
    }

    @Override
    public void truncateWrites() {
    }

    @Override
    public boolean flush() {
        return true;
    }

    @Override
    public long transferFrom(java.nio.channels.FileChannel src, long position, long count) {
        throw new UnsupportedOperationException();
    }

    @Override
    public long transferFrom(org.xnio.channels.StreamSourceChannel source, long count, ByteBuffer throughBuffer) {
        throw new UnsupportedOperationException();
    }

    @Override
    public int write(ByteBuffer src) {
        int remaining = src.remaining();
        byte[] bytes = new byte[remaining];
        src.get(bytes);
        output.write(bytes, 0, bytes.length);
        return remaining;
    }

    @Override
    public long write(ByteBuffer[] srcs, int offset, int length) {
        long total = 0;
        for (int i = offset; i < offset + length; i++) {
            total += write(srcs[i]);
        }
        return total;
    }

    @Override
    public int writeFinal(ByteBuffer src) {
        int written = write(src);
        terminateWrites();
        return written;
    }

    @Override
    public long writeFinal(ByteBuffer[] srcs, int offset, int length) {
        long written = write(srcs, offset, length);
        terminateWrites();
        return written;
    }

    @Override
    public org.xnio.XnioWorker getWorker() {
        return null;
    }

    byte[] bytes() {
        return output.toByteArray();
    }
}

/**
 * In-memory source conduit used by request channel tests.
 */
final class TestSourceConduit implements org.xnio.conduits.StreamSourceConduit {

    private ByteBuffer input;
    private boolean readShutdown;
    private boolean resumed;
    private org.xnio.conduits.ReadReadyHandler readReadyHandler;

    TestSourceConduit(byte[] bytes) {
        this.input = ByteBuffer.wrap(bytes);
    }

    void append(byte[] bytes) {
        ByteBuffer old = input;
        input = ByteBuffer.allocate(old.remaining() + bytes.length);
        input.put(old);
        input.put(bytes);
        input.flip();
    }

    @Override
    public void terminateReads() {
        readShutdown = true;
    }

    @Override
    public boolean isReadShutdown() {
        return readShutdown;
    }

    @Override
    public void resumeReads() {
        resumed = true;
    }

    @Override
    public void suspendReads() {
        resumed = false;
    }

    @Override
    public void wakeupReads() {
        resumed = true;
    }

    @Override
    public boolean isReadResumed() {
        return resumed;
    }

    @Override
    public void awaitReadable() {
    }

    @Override
    public void awaitReadable(long time, java.util.concurrent.TimeUnit timeUnit) {
    }

    @Override
    public org.xnio.XnioIoThread getReadThread() {
        return null;
    }

    @Override
    public void setReadReadyHandler(org.xnio.conduits.ReadReadyHandler handler) {
        this.readReadyHandler = handler;
    }

    org.xnio.conduits.ReadReadyHandler getReadReadyHandler() {
        return readReadyHandler;
    }

    @Override
    public long transferTo(long position, long count, java.nio.channels.FileChannel target) {
        throw new UnsupportedOperationException();
    }

    @Override
    public long transferTo(long count, ByteBuffer throughBuffer, org.xnio.channels.StreamSinkChannel target) {
        throw new UnsupportedOperationException();
    }

    @Override
    public int read(ByteBuffer dst) {
        if (!input.hasRemaining()) {
            return -1;
        }
        int count = Math.min(dst.remaining(), input.remaining());
        int oldLimit = input.limit();
        input.limit(input.position() + count);
        dst.put(input);
        input.limit(oldLimit);
        return count;
    }

    @Override
    public long read(ByteBuffer[] dsts, int offset, int length) {
        long total = 0;
        for (int i = offset; i < offset + length; i++) {
            int read = read(dsts[i]);
            if (read == -1) {
                return total == 0 ? -1 : total;
            }
            total += read;
        }
        return total;
    }

    @Override
    public org.xnio.XnioWorker getWorker() {
        return null;
    }
}
