import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

class SecurityActionsTest {

    private static final String KEY = "io.undertow.test.ajp.securityActions";

    @AfterEach
    void clearProperty() {
        System.clearProperty(KEY);
    }

    @Test
    void returnsAConfiguredSystemProperty() {
        System.setProperty(KEY, "configured");

        assertEquals("configured", SecurityActions.getSystemProperty(KEY));
        assertEquals("configured", SecurityActions.getSystemProperty(KEY, "fallback"));
    }

    @Test
    void returnsNullForAMissingPropertyWithoutDefault() {
        assertNull(SecurityActions.getSystemProperty(KEY));
    }

    @Test
    void returnsTheDefaultForAMissingProperty() {
