class AjpRequestParseStateTest {

    @Test
    void hasProtocolDefaults() {
        AjpRequestParseState state = new AjpRequestParseState();

        assertEquals(AjpRequestParseState.BEGIN, state.state);
        assertEquals(-1, state.stringLength);
        assertEquals(-1, state.currentIntegerPart);
        assertEquals(0, state.numHeaders);
        assertEquals(-1, state.remotePort);
        assertEquals(80, state.serverPort);
        assertFalse(state.isComplete());
        assertNull(state.attributes);
    }

    @Test
    void isCompleteOnlyInDoneState() {
        AjpRequestParseState state = new AjpRequestParseState();
        state.state = AjpRequestParseState.DONE;
        assertTrue(state.isComplete());

        state.state = AjpRequestParseState.READING_HEADERS;
        assertFalse(state.isComplete());
    }

    @Test
    void accumulatesAndClearsTheCurrentString() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        state.addStringByte((byte) 'A');
        state.addStringByte((byte) 0xE9);

        assertEquals(2, state.getCurrentStringLength());
        String value = state.getStringAndClear();
        assertEquals(2, value.length());
        assertEquals('A', value.charAt(0));
        assertEquals((char) 0xE9, value.charAt(1));
        assertEquals(0, state.getCurrentStringLength());
        assertEquals("", state.getStringAndClear());
    }

    @Test
    void resetClearsPartialParseInformation() {
        AjpRequestParseState state = new AjpRequestParseState();
        state.stringLength = 20;
        state.currentIntegerPart = 7;
        state.readHeaders = 3;
        state.badRequest = true;
        state.containsUnencodedUrlCharacters = true;
        state.secretProvided = true;
        state.addStringByte((byte) 'x');
        state.numHeaders = 9;
        state.remoteAddress = "203.0.113.5";

        state.reset();

        assertEquals(-1, state.stringLength);
        assertEquals(-1, state.currentIntegerPart);
        assertEquals(0, state.readHeaders);
        assertFalse(state.badRequest);
        assertFalse(state.containsUnencodedUrlCharacters);
        assertFalse(state.secretProvided);
        assertEquals(0, state.getCurrentStringLength());
        // reset is intentionally a lightweight per-request parser reset.
        assertEquals(9, state.numHeaders);
        assertEquals("203.0.113.5", state.remoteAddress);
    }

    @Test
    void createsAConfiguredSslSession() {
        AjpRequestParseState state = new AjpRequestParseState();
        state.sslSessionId = "31323334";
        state.sslCipher = "TLS_AES_256_GCM_SHA384";
        state.sslKeySize = "256";
        state.secureProtocol = "TLSv1.3";

        BasicSSLSessionInfo session = state.createSslSessionInfo();

        assertArrayEquals(new byte[] {'1', '2', '3', '4'}, session.getSessionId());
        assertEquals("TLS_AES_256_GCM_SHA384", session.getCipherSuite());
        assertEquals(256, session.getKeySize());
        assertEquals("TLSv1.3", session.getSecureProtocol());
