    @Test
    void parsesAForwardRequestWithHeadersAddressesAndScheme() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();
        ByteBuffer packet = new AjpTestSupport.RequestBuilder()
                .method(2)
                .requestUri("/app/hello%20world")
                .remoteAddress("192.0.2.10")
                .remoteHost("client.example")
                .serverName("server.example")
                .serverPort(8443)
                .ssl(true)
                .commonHeader(0xB, "example.test:8443")
                .header("X-Trace", "one")
                .header("X-Trace", "two")
                .build();

        parser().parse(packet, state, exchange);

        assertAllState(state, exchange);
        assertEquals(2, state.prefix);
        assertTrue(state.dataSize > 0);
        assertEquals(Methods.GET, exchange.getRequestMethod());
        assertEquals("HTTP/1.1", exchange.getProtocol().toString());
        assertEquals("https", exchange.getRequestScheme());
        assertEquals("/app/hello%20world", exchange.getRequestURI());
        assertEquals("/app/hello world", exchange.getRequestPath());
        assertEquals("/app/hello world", exchange.getRelativePath());
        assertEquals("192.0.2.10", state.remoteAddress);
        assertEquals("server.example", state.serverAddress);
        assertEquals(8443, state.serverPort);
        assertEquals("example.test:8443", exchange.getRequestHeaders().getFirst(Headers.HOST));
        assertEquals(Arrays.asList("one", "two"), exchange.getRequestHeaders().get("X-Trace"));
    }

