        HttpServerExchange exchange = exchange();
        ByteBuffer full = new AjpTestSupport.RequestBuilder()
                .method(4)
                .requestUri("/fragmented")
                .header("X-Fragment", "works")
                .attribute(5, "a=1")
                .build();
        AjpRequestParser parser = parser();

        while (full.hasRemaining()) {
            ByteBuffer oneByte = ByteBuffer.wrap(new byte[] {full.get()});
            parser.parse(oneByte, state, exchange);
            assertFalse(oneByte.hasRemaining(), "the parser must consume a complete one-byte slice");
        }

        assertTrue(state.isComplete());
        assertEquals(Methods.POST, exchange.getRequestMethod());
        assertEquals("/fragmented", exchange.getRequestPath());
        assertEquals("works", exchange.getRequestHeaders().getFirst("X-Fragment"));
        assertEquals("1", exchange.getQueryParameters().get("a").peekFirst());
    }

