        parser().parse(simplePacket(AjpRequestParser.CPING), state, exchange);

        assertTrue(state.isComplete());
        assertEquals(AjpRequestParser.CPING, state.prefix);
        assertEquals(HttpString.EMPTY, exchange.getRequestMethod());
        assertNull(exchange.getRequestPath());
    }

    @Test
    void marksTooManyHeadersAsBadRequestAndDoesNotPopulateTheHeaderMap() throws Exception {
        AjpRequestParser parser = new AjpRequestParser("UTF-8", true, 10, 1, false, false);
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();
        ByteBuffer packet = new AjpTestSupport.RequestBuilder()
                .header("X-One", "1")
                .header("X-Two", "2")
                .build();

        parser.parse(packet, state, exchange);

        assertTrue(state.isComplete());
