        ByteBuffer packet = new AjpTestSupport.RequestBuilder()
                .commonHeader(0x7, "text/plain")
                .commonHeader(0x8, "12")
                .commonHeader(0x9, "a=1")
                .commonHeader(0x9, "b=2")
