                .build();

        parser().parse(packet, state, exchange);

        assertEquals("/context", state.attributes.get(AjpRequestParser.CONTEXT));
        assertEquals("/servlet", state.attributes.get(AjpRequestParser.SERVLET_PATH));
        assertEquals("node-a", state.attributes.get(AjpRequestParser.ROUTE));
        assertFalse(state.attributes.containsKey("not.allowed"));
    }

    @Test
    void secretIsOnlyAcceptedWhenItMatchesTheConfiguredValue() throws Exception {
        AjpRequestParser parser = new AjpRequestParser("UTF-8", true, 10, 10, false, false, null, "s3cr3t");
        AjpRequestParseState wrong = new AjpRequestParseState();
        parser.parse(new AjpTestSupport.RequestBuilder().attribute(12, "wrong").build(), wrong, exchange());
        assertFalse(wrong.secretProvided);

        AjpRequestParseState right = new AjpRequestParseState();
        parser.parse(new AjpTestSupport.RequestBuilder().attribute(12, "s3cr3t").build(), right, exchange());
        assertTrue(right.secretProvided);
    }

    @Test
    void marksRequestBadWhenQueryParameterLimitIsExceeded() throws Exception {
        AjpRequestParser parser = new AjpRequestParser("UTF-8", true, 1, 10, false, false);
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();
        ByteBuffer packet = new AjpTestSupport.RequestBuilder()
                .attribute(5, "a=1&b=2")
                .build();

        parser.parse(packet, state, exchange);

        assertTrue(state.isComplete());
        assertTrue(state.badRequest);
    }

    @Test
    void decodesUriOnlyWhereRequiredAndKeepsTheRawRequestUriOtherwise() throws Exception {
        HttpServerExchange strictExchange = exchange();
        parser().parse(new AjpTestSupport.RequestBuilder().requestUri("/a%20b").build(),
                new AjpRequestParseState(), strictExchange);

        assertEquals("/a%20b", strictExchange.getRequestURI());
        assertEquals("/a b", strictExchange.getRequestPath());

        AjpRequestParser lenient = new AjpRequestParser("UTF-8", true, 10, 10, false, true);
        HttpServerExchange lenientExchange = exchange();
        lenient.parse(new AjpTestSupport.RequestBuilder().requestUri("/a%20b").build(),
                new AjpRequestParseState(), lenientExchange);

        assertEquals("/a b", lenientExchange.getRequestURI());
        assertEquals("/a b", lenientExchange.getRequestPath());
    }

    @Test
    void rejectsMalformedPercentEncodingInTheUri() {
        ByteBuffer packet = new AjpTestSupport.RequestBuilder().requestUri("/bad%zz").build();
        assertThrows(UrlDecodeException.class,
                () -> parser().parse(packet, new AjpRequestParseState(), exchange()));
    }

    @Test
    void rejectsAnInvalidHeaderToken() {
        ByteBuffer packet = new AjpTestSupport.RequestBuilder().header("bad header", "value").build();
        assertThrows(IllegalArgumentException.class,
                () -> parser().parse(packet, new AjpRequestParseState(), exchange()));
    }

    @Test
    void nullStringsAreAcceptedForUnusedRequestFields() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();
        ByteBuffer packet = new AjpTestSupport.RequestBuilder()
                .remoteAddress(null)
                .remoteHost(null)
                .serverName(null)
                .build();

        parser().parse(packet, state, exchange);

        assertTrue(state.isComplete());
        assertNull(state.remoteAddress);
        assertNull(state.createPeerAddress());
        assertNull(state.createDestinationAddress());
    }


    @Test
    void exposesMethodAndHeaderConstantsUsedByCallers() {
        assertEquals(2, AjpRequestParser.FORWARD_REQUEST);
        assertEquals(7, AjpRequestParser.SHUTDOWN);
        assertEquals(9, AjpRequestParser.CPONG);
        assertEquals(10, AjpRequestParser.CPING);
        assertEquals("query_string", AjpRequestParser.QUERY_STRING);
        assertEquals("AJP_REMOTE_PORT", AjpRequestParser.AJP_REMOTE_PORT);
        assertEquals("AJP_SSL_PROTOCOL", AjpRequestParser.AJP_SSL_PROTOCOL);
    }

    @Test
    void emptyBufferDoesNotAdvanceTheParserState() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();

        parser().parse(ByteBuffer.allocate(0), state, exchange);

        assertEquals(AjpRequestParseState.BEGIN, state.state);
        assertFalse(state.isComplete());
        assertEquals(HttpString.EMPTY, exchange.getRequestMethod());
    }

    @Test
    void parsesCustomStringTypeWithUtf8BytesAsProtocolString() throws Exception {
        AjpRequestParseState state = new AjpRequestParseState();
        HttpServerExchange exchange = exchange();
        ByteBuffer packet = new AjpTestSupport.RequestBuilder()
                .protocol("HTTP/2.0")
                .requestUri("/typed")
                .build();

        parser().parse(packet, state, exchange);

        assertEquals(HttpString.tryFromString("HTTP/2.0"), exchange.getProtocol());
        assertEquals("/typed", exchange.getRequestPath());
    }

    @Test
    void doesNotDecodeUriWhenDecodeUrlIsDisabled() throws Exception {
        AjpRequestParser parser = new AjpRequestParser("UTF-8", false, 10, 10, false, false);
        HttpServerExchange exchange = exchange();

        parser.parse(new AjpTestSupport.RequestBuilder().requestUri("/a%20b").build(),
                new AjpRequestParseState(), exchange);

        assertEquals("/a%20b", exchange.getRequestURI());
        assertEquals("/a%20b", exchange.getRequestPath());
    }

    @Test
    void slashDecodingFollowsTheConfiguredFlag() throws Exception {
        HttpServerExchange strictExchange = exchange();
        parser().parse(new AjpTestSupport.RequestBuilder().requestUri("/a%2Fb").build(),
                new AjpRequestParseState(), strictExchange);
        assertEquals("/a%2Fb", strictExchange.getRequestPath());

        AjpRequestParser slashDecoder = new AjpRequestParser("UTF-8", true, 10, 10, true, false);
        HttpServerExchange decodedExchange = exchange();
        slashDecoder.parse(new AjpTestSupport.RequestBuilder().requestUri("/a%2Fb").build(),
                new AjpRequestParseState(), decodedExchange);
        assertEquals("/a/b", decodedExchange.getRequestPath());
    }
}

