import org.xnio.channels.Configurable;
import org.xnio.conduits.ConduitStreamSinkChannel;
import org.xnio.conduits.ConduitStreamSourceChannel;

class AjpServerConnectionTest {

    @Test
    void reportsAjpTransportCapabilities() {
        TestConnection fixture = new TestConnection();
        try {
            AjpServerConnection connection = fixture.connection();

            assertFalse(connection.isContinueResponseSupported());
            assertFalse(connection.isRequestTrailerFieldsSupported());
            assertTrue(connection.getTransportProtocol().equals("ajp"));
            assertThrows(IllegalStateException.class,
                    () -> connection.sendOutOfBandResponse(new HttpServerExchange(connection)));
        } finally {
            fixture.close();
        }
    }

    @Test
    void storesAndReturnsTheSslSessionInfo() {
        TestConnection fixture = new TestConnection();
        try {
            AjpServerConnection connection = fixture.connection();
            SSLSessionInfo session = new SSLSessionInfo() {
                @Override
                public byte[] getSessionId() {
                    return new byte[] {1};
                }

                @Override
                public String getCipherSuite() {
                    return "TLS_AES_128_GCM_SHA256";
                }

                @Override
                public java.security.cert.Certificate[] getPeerCertificates() {
                    return new java.security.cert.Certificate[0];
                }

                @Override
                public javax.security.cert.X509Certificate[] getPeerCertificateChain() {
                    return new javax.security.cert.X509Certificate[0];
                }

                @Override
                public void renegotiate(HttpServerExchange exchange, org.xnio.SslClientAuthMode sslClientAuthMode) {
                }

                @Override
                public javax.net.ssl.SSLSession getSSLSession() {
                    return null;
                }
            };

            connection.setSslSessionInfo(session);
            assertSame(session, connection.getSslSessionInfo());
        } finally {
            fixture.close();
        }
    }

    @Test
    void resetChannelRestoresTheOriginalConduitAndStateCanRestoreTheWrapper() {
        TestConnection fixture = new TestConnection();
        try {
            AjpServerConnection connection = fixture.connection();
            TestSinkConduit wrapper = new TestSinkConduit();
            fixture.sinkChannel.setConduit(wrapper);

            AjpServerConnection.ConduitState state = connection.resetChannel();

            assertSame(fixture.originalSink, fixture.sinkChannel.getConduit());
            connection.restoreChannel(state);
            assertSame(wrapper, fixture.sinkChannel.getConduit());
        } finally {
            fixture.close();
        }
    }

    @Test
    void clearChannelRestoresTheOriginalConduit() {
        TestConnection fixture = new TestConnection();
        try {
            AjpServerConnection connection = fixture.connection();
            fixture.sinkChannel.setConduit(new TestSinkConduit());

            connection.clearChannel();

            assertSame(fixture.originalSink, fixture.sinkChannel.getConduit());
            assertSame(fixture.originalSource, fixture.sourceChannel.getConduit());
        } finally {
            fixture.close();
        }
    }

    @Test
    void terminateRequestChannelClosesTheSourceOnlyForNonPersistentExchanges() {
        TestConnection fixture = new TestConnection();
        try {
            AjpServerConnection connection = fixture.connection();
            HttpServerExchange persistent = new HttpServerExchange(connection);
            persistent.setPersistent(true);

            connection.terminateRequestChannel(persistent);
            assertFalse(fixture.sourceConduit.isReadShutdown());

            HttpServerExchange nonPersistent = new HttpServerExchange(connection);
            nonPersistent.setPersistent(false);
            connection.terminateRequestChannel(nonPersistent);
            assertTrue(fixture.sourceConduit.isReadShutdown());
        } finally {
            fixture.close();
        }
    }

    private static final class TestConnection {
        private final TestSinkConduit originalSink = new TestSinkConduit();
        private final TestSourceConduit originalSource = new TestSourceConduit(new byte[0]);
        private final ConduitStreamSinkChannel sinkChannel = new ConduitStreamSinkChannel(
                Configurable.EMPTY, originalSink);
        private final ConduitStreamSourceChannel sourceChannel = new ConduitStreamSourceChannel(
                Configurable.EMPTY, originalSource);
        private final TestSourceConduit sourceConduit = originalSource;
        private final DefaultByteBufferPool pool = new DefaultByteBufferPool(false, 128);
        private final StreamConnection channel;

        private TestConnection() {
            channel = createNiceMock(StreamConnection.class);
            expect(channel.getSinkChannel()).andReturn(sinkChannel).anyTimes();
            expect(channel.getSourceChannel()).andReturn(sourceChannel).anyTimes();
            replay(channel);
        }

        private AjpServerConnection connection() {
            return new AjpServerConnection(channel, pool, null, OptionMap.EMPTY, 128);
        }

        private void close() {
            pool.close();
        }
    }
}

