import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.ClosedChannelException;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicBoolean;

import io.undertow.server.DefaultByteBufferPool;
import io.undertow.server.HttpServerExchange;
import io.undertow.server.RequestTooBigException;
import io.undertow.server.ServerConnection;
import org.junit.jupiter.api.Test;
import org.xnio.OptionMap;

class AjpServerRequestConduitTest {

    @Test
    void readsAKnownLengthBodyFromAnAjpBodyPacket() throws Exception {
        Fixture fixture = new Fixture(bodyPacket("hello"));
        try {
            AjpServerRequestConduit conduit = fixture.conduit(5L);
            ByteBuffer destination = ByteBuffer.allocate(16);

            assertEquals(5, conduit.read(destination));
            destination.flip();
            assertArrayEquals("hello".getBytes(StandardCharsets.US_ASCII), bytes(destination));
            assertFalse(fixture.finished.get());
            assertEquals(-1, conduit.read(ByteBuffer.allocate(1)));
            assertTrue(fixture.finished.get());
            assertEquals(0, fixture.responseSink.bytes().length);
        } finally {
            fixture.close();
        }
    }

    @Test
    void unknownLengthSendsAReadBodyChunkRequestBeforeReading() throws Exception {
        Fixture fixture = new Fixture(bodyPacket("abc"));
        try {
            AjpServerRequestConduit conduit = fixture.conduit(null);
            ByteBuffer destination = ByteBuffer.allocate(8);

            assertEquals(3, conduit.read(destination));
            destination.flip();
            assertEquals("abc", new String(bytes(destination), StandardCharsets.US_ASCII));
            assertArrayEquals(new byte[] {0x41, 0x42, 0x00, 0x03, 0x06, 0x1F, (byte) 0xFA},
                    fixture.responseSink.bytes());
        } finally {
            fixture.close();
        }
    }

    @Test
    void readsAcrossMultipleDestinationBuffers() throws Exception {
        Fixture fixture = new Fixture(bodyPacket("world"));
        try {
            AjpServerRequestConduit conduit = fixture.conduit(5L);
            ByteBuffer first = ByteBuffer.allocate(2);
            ByteBuffer second = ByteBuffer.allocate(8);

            long read = conduit.read(new ByteBuffer[] {first, second}, 0, 2);

            assertEquals(5, read);
            first.flip();
            second.flip();
            assertEquals("wo", new String(bytes(first), StandardCharsets.US_ASCII));
            assertEquals("rld", new String(bytes(second), StandardCharsets.US_ASCII));
        } finally {
            fixture.close();
        }
    }

    @Test
    void zeroLengthRequestFinishesWithoutReadingTheDelegate() throws Exception {
        Fixture fixture = new Fixture(new byte[0]);
        try {
            AjpServerRequestConduit conduit = fixture.conduit(0L);

            assertEquals(-1, conduit.read(ByteBuffer.allocate(1)));
            assertFalse(fixture.source.isReadShutdown());
            assertEquals(0, fixture.responseSink.bytes().length);
        } finally {
            fixture.close();
        }
    }

    @Test
    void zeroLengthRequestIsTerminatedWithoutClosingAPersistentSource() throws Exception {
        Fixture fixture = new Fixture(new byte[0]);
        try {
            AjpServerRequestConduit conduit = fixture.conduit(0L);
            fixture.exchange.setPersistent(true);

            conduit.terminateReads();

            assertFalse(fixture.source.isReadShutdown());
        } finally {
            fixture.close();
        }
    }

    @Test
    void terminateReadsClosesTheDelegateForAnActiveRequest() throws Exception {
        Fixture fixture = new Fixture(bodyPacket("data"));
        try {
            AjpServerRequestConduit conduit = fixture.conduit(4L);
            fixture.exchange.setPersistent(true);

            conduit.terminateReads();

            assertTrue(fixture.source.isReadShutdown());
        } finally {
            fixture.close();
        }
    }

    @Test
    void truncatedBodyPacketHeaderRaisesClosedChannelAndFinishes() throws Exception {
        Fixture fixture = new Fixture(new byte[] {0x12, 0x34, 0x00});
        try {
            AjpServerRequestConduit conduit = fixture.conduit(5L);
            assertEquals(0, conduit.read(ByteBuffer.allocate(8)));
            assertThrows(ClosedChannelException.class, () -> conduit.read(ByteBuffer.allocate(8)));
            assertTrue(fixture.finished.get());
        } finally {
            fixture.close();
        }
    }

    @Test
    void malformedBodyPacketMagicRaisesIoException() throws Exception {
        byte[] invalid = bodyPacket("hello");
        invalid[1] = 0x33;
        Fixture fixture = new Fixture(invalid);
        try {
            AjpServerRequestConduit conduit = fixture.conduit(5L);
            assertThrows(IOException.class, () -> conduit.read(ByteBuffer.allocate(8)));
        } finally {
            fixture.close();
        }
    }

    @Test
    void maxEntitySizeIsEnforcedAcrossReads() throws Exception {
        Fixture fixture = new Fixture(bodyPacket("too-large"));
        try {
            fixture.exchange.setMaxEntitySize(3);
            AjpServerRequestConduit conduit = fixture.conduit(9L);

            assertThrows(RequestTooBigException.class, () -> conduit.read(ByteBuffer.allocate(32)));
            assertFalse(fixture.exchange.isPersistent());
            assertTrue(fixture.source.isReadShutdown());
        } finally {
            fixture.close();
        }
    }

    @Test
    void aZeroLengthBodyPacketFinishesTheRequestAndPreservesTheTerminatorBytes() throws Exception {
        Fixture fixture = new Fixture(new byte[] {0x12, 0x34, 0x00, 0x00, 0x00, 0x00});
        try {
            AjpServerRequestConduit conduit = fixture.conduit(1L);

            assertEquals(-1, conduit.read(ByteBuffer.allocate(8)));
            assertTrue(fixture.finished.get());
        } finally {
            fixture.close();
        }
    }

    private static byte[] bodyPacket(String value) {
        byte[] body = value.getBytes(StandardCharsets.US_ASCII);
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write(0x12);
        out.write(0x34);
        out.write(((body.length + 2) >> 8) & 0xFF);
        out.write((body.length + 2) & 0xFF);
        out.write((body.length >> 8) & 0xFF);
        out.write(body.length & 0xFF);
        out.write(body, 0, body.length);
        return out.toByteArray();
    }

    private static byte[] bytes(ByteBuffer buffer) {
        byte[] bytes = new byte[buffer.remaining()];
        buffer.get(bytes);
        return bytes;
    }

    private static final class Fixture {
        private final ServerConnection connection = createNiceMock(ServerConnection.class);
        private final HttpServerExchange exchange;
        private final DefaultByteBufferPool pool = new DefaultByteBufferPool(false, 128);
        private final TestSourceConduit source;
        private final TestSinkConduit responseSink = new TestSinkConduit();
        private final AjpServerResponseConduit response;
        private final AtomicBoolean finished = new AtomicBoolean();

        private Fixture(byte[] sourceBytes) {
            expect(connection.getUndertowOptions()).andReturn(OptionMap.EMPTY).anyTimes();
            replay(connection);
            exchange = new HttpServerExchange(connection);
            source = new TestSourceConduit(sourceBytes);
            response = new AjpServerResponseConduit(responseSink, pool, exchange, null, false);
        }

        private AjpServerRequestConduit conduit(Long length) {
            return new AjpServerRequestConduit(source, exchange, response, length, channel -> {
                finished.set(true);
            });
        }

        private void close() {
            pool.close();
        }
    }
}

