        long written = write(srcs, offset, length);
        terminateWrites();
        return written;
    }

    @Override
    public org.xnio.XnioWorker getWorker() {
        return null;
    }

    byte[] bytes() {
        return output.toByteArray();
    }
}

/**
 * In-memory source conduit used by request channel tests.
 */
final class TestSourceConduit implements org.xnio.conduits.StreamSourceConduit {

    private ByteBuffer input;
    private boolean readShutdown;
    private boolean resumed;
    private org.xnio.conduits.ReadReadyHandler readReadyHandler;

    TestSourceConduit(byte[] bytes) {
        this.input = ByteBuffer.wrap(bytes);
    }

    void append(byte[] bytes) {
        ByteBuffer old = input;
        input = ByteBuffer.allocate(old.remaining() + bytes.length);
        input.put(old);
        input.put(bytes);
        input.flip();
    }

    @Override
    public void terminateReads() {
        readShutdown = true;
    }

    @Override
    public boolean isReadShutdown() {
        return readShutdown;
    }

    @Override
    public void resumeReads() {
        resumed = true;
    }

    @Override
    public void suspendReads() {
        resumed = false;
    }

    @Override
    public void wakeupReads() {
        resumed = true;
    }

    @Override
    public boolean isReadResumed() {
        return resumed;
    }

    @Override
    public void awaitReadable() {
    }

    @Override
    public void awaitReadable(long time, java.util.concurrent.TimeUnit timeUnit) {
    }

    @Override
    public org.xnio.XnioIoThread getReadThread() {
        return null;
    }

    @Override
    public void setReadReadyHandler(org.xnio.conduits.ReadReadyHandler handler) {
        this.readReadyHandler = handler;
    }

    org.xnio.conduits.ReadReadyHandler getReadReadyHandler() {
        return readReadyHandler;
    }

    @Override
    public long transferTo(long position, long count, java.nio.channels.FileChannel target) {
        throw new UnsupportedOperationException();
    }

    @Override
    public long transferTo(long count, ByteBuffer throughBuffer, org.xnio.channels.StreamSinkChannel target) {
        throw new UnsupportedOperationException();
    }

    @Override
    public int read(ByteBuffer dst) {
        if (!input.hasRemaining()) {
            return -1;
        }
        int count = Math.min(dst.remaining(), input.remaining());
        int oldLimit = input.limit();
        input.limit(input.position() + count);
        dst.put(input);
        input.limit(oldLimit);
        return count;
    }

    @Override
    public long read(ByteBuffer[] dsts, int offset, int length) {
        long total = 0;
        for (int i = offset; i < offset + length; i++) {
            int read = read(dsts[i]);
            if (read == -1) {
                return total == 0 ? -1 : total;
            }
            total += read;
        }
        return total;
    }

    @Override
    public org.xnio.XnioWorker getWorker() {
        return null;
    }
}

