        RewriteCond condition = condition("first", "^first$");

        assertTrue(condition.evaluate(null, null, NO_RESOLVER));
        assertEquals("first", condition.getMatcher().group(0));
        assertTrue(condition.evaluate(null, null, NO_RESOLVER));
    }

    @Test
    void accessorsRoundTripConfiguration() {
        RewriteCond condition = new RewriteCond();
        condition.setTestString("%{REQUEST_URI}");
        condition.setCondPattern("^/app/");
        condition.setNocase(true);
        condition.setOrnext(true);
        condition.setPositive(false);

        assertEquals("%{REQUEST_URI}", condition.getTestString());
        assertEquals("^/app/", condition.getCondPattern());
        assertTrue(condition.isNocase());
