class SubstitutionTest {

    private static final Resolver RESOLVER = new StubResolver();

    @Test
    void parsesAndEvaluatesStaticTextAndBackReferences() {
        Substitution substitution = substitution("/new/$1/condition-%1/%{REQUEST_URI}");
        substitution.parse(Collections.emptyMap());
        Matcher rule = Pattern.compile("^/old/(.*)$").matcher("/old/item");
        rule.matches();
        Matcher condition = Pattern.compile("^(.*)$").matcher("captured");
        condition.matches();

        assertEquals("/new/item/condition-captured//app/request", substitution.evaluate(rule, condition, RESOLVER));
    }

    @Test
    void expandsEveryServerVariableKind() {
        assertEquals("/app/request", parsed("%{REQUEST_URI}").evaluate(null, null, RESOLVER));
        assertEquals("environment", parsed("%{ENV:name}").evaluate(null, null, RESOLVER));
        assertEquals("secure", parsed("%{SSL:name}").evaluate(null, null, RESOLVER));
        assertEquals("header", parsed("%{HTTP:name}").evaluate(null, null, RESOLVER));
    }

    @Test
    void emptySubstitutionEvaluatesToEmptyString() {
        Substitution substitution = substitution("");
        substitution.parse(Collections.emptyMap());

        assertEquals("", substitution.evaluate(null, null, RESOLVER));
    }

    @Test
    void mapLookupUsesMappedValueWhenPresent() {
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("numbers", new FixedRewriteMap("one", "1"));
        Substitution substitution = substitution("${numbers:one}");
        substitution.parse(maps);

        assertEquals("1", substitution.evaluate(null, null, RESOLVER));
    }

    @Test
    void mapLookupUsesDefaultWhenMapReturnsNull() {
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("numbers", new FixedRewriteMap("one", "1"));
        Substitution substitution = substitution("before-${numbers:missing|fallback}-after");
        substitution.parse(maps);

        assertEquals("before-fallback-after", substitution.evaluate(null, null, RESOLVER));
    }

    @Test
    void mapWithoutDefaultReturnsNullWhenLookupFails() {
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("numbers", new FixedRewriteMap("one", "1"));
        Substitution substitution = substitution("${numbers:missing}");
        substitution.parse(maps);

        assertEquals("null", substitution.evaluate(null, null, RESOLVER));
    }

    @Test
    void setSubIsVisibleThroughAccessor() {
        Substitution substitution = new Substitution();
        substitution.setSub("/target?value=$1");

        assertEquals("/target?value=$1", substitution.getSub());
    }

    @Test
    void trailingRuleBackReferenceMarkerIsRejected() {
        assertThrows(IllegalArgumentException.class, () -> substitution("/target/$").parse(Collections.emptyMap()));
    }

    @Test
    void trailingConditionBackReferenceMarkerIsRejected() {
        assertThrows(IllegalArgumentException.class, () -> substitution("/target/%").parse(Collections.emptyMap()));
    }

    @Test
    void unknownMapNameIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> substitution("${unknown:key}").parse(Collections.emptyMap()));
    }

    @Test
    void malformedMapExpressionIsRejected() {
        Map<String, RewriteMap> maps = Collections.singletonMap("m", new FixedRewriteMap("k", "v"));

        assertThrows(IllegalArgumentException.class, () -> substitution("${m:key").parse(maps));
        assertThrows(IllegalArgumentException.class, () -> substitution("${m-key}").parse(maps));
    }

    @Test
    void malformedServerVariableIsRejected() {
        assertThrows(IllegalArgumentException.class, () -> substitution("%{REQUEST_URI").parse(Collections.emptyMap()));
        assertThrows(IllegalArgumentException.class, () -> substitution("%{ENV:name").parse(Collections.emptyMap()));
    }

    @Test
    void unknownServerVariableTypeIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> substitution("%{UNKNOWN:name}").parse(Collections.emptyMap()));
    }

    private static Substitution parsed(String value) {
        Substitution substitution = substitution(value);
        substitution.parse(Collections.emptyMap());
        return substitution;
    }

    private static Substitution substitution(String value) {
        Substitution substitution = new Substitution();
        substitution.setSub(value);
        return substitution;
    }

    private static final class FixedRewriteMap implements RewriteMap {
        private final String key;
        private final String value;

        private FixedRewriteMap(String key, String value) {
            this.key = key;
            this.value = value;
        }

        @Override
        public String setParameters(String params) {
            return null;
        }

        @Override
        public String lookup(String lookupKey) {
            return key.equals(lookupKey) ? value : null;
        }
    }

    private static final class StubResolver extends Resolver {
        @Override
        public String resolve(String key) {
            return key.equals("REQUEST_URI") ? "/app/request" : null;
        }

        @Override
        public String resolveEnv(String key) {
            return "environment";
        }

        @Override
        public String resolveSsl(String key) {
            return "secure";
        }

        @Override
        public String resolveHttp(String key) {
            return "header";
        }

        @Override
        public boolean resolveResource(int type, String name) {
            return false;
        }
    }
