        }
    }
}

package io.undertow.servlet.compat.rewrite;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class RewriteConfigFactoryTest {

    @Test
    void parsesCommentsBlankLinesConditionsAndRules() {
        RewriteConfig config = build(""
                + "# a comment\n"
                + "\n"
                + "RewriteCond %{HTTP_HOST} ^www\\.example\\.com$ [NC,OR]\n"
                + "RewriteRule ^/old$ /new [L]\n");

        assertEquals(1, config.getRules().length);
        RewriteRule rule = config.getRules()[0];
        assertEquals("^/old$", rule.getPatternString());
        assertEquals("/new", rule.getSubstitutionString());
        assertTrue(rule.isLast());
        assertEquals(1, rule.getConditions().length);
        assertTrue(rule.getConditions()[0].isNocase());
        assertTrue(rule.getConditions()[0].isOrnext());
        assertTrue(config.getMaps().isEmpty());
    }

    @Test
    void parsesShortRuleFlagsAndTheirValues() {
        RewriteConfig config = build("RewriteRule ^/old$ /new "
                + "[C,F,G,H,L,N,QSA,R=308,S=1,T=text/x-test]\n");

        RewriteRule rule = config.getRules()[0];
        assertTrue(rule.isChain());
        assertTrue(rule.isForbidden());
        assertTrue(rule.isGone());
        assertTrue(rule.isHost());
        assertTrue(rule.isLast());
        assertTrue(rule.isNext());
        assertTrue(rule.isQsappend());
        assertTrue(rule.isRedirect());
        assertEquals(308, rule.getRedirectCode());
        assertEquals(1, rule.getSkip());
        assertTrue(rule.isType());
        assertEquals("text/x-test", rule.getTypeValue());
    }

    @Test
    void parsesLongRuleFlags() {
        RewriteConfig config = build("RewriteRule ^/old$ /new "
                + "[chain,nocase,noescape,qsappend,redirect,type=text/plain]\n");

        RewriteRule rule = config.getRules()[0];
        assertTrue(rule.isChain());
        assertTrue(rule.isNocase());
        assertTrue(rule.isNoescape());
        assertTrue(rule.isQsappend());
        assertTrue(rule.isRedirect());
        assertEquals(302, rule.getRedirectCode());
        assertTrue(rule.isType());
        assertEquals("text/plain", rule.getTypeValue());
    }

    @Test
    void parsesCookieFlagFields() {
        RewriteConfig config = build("RewriteRule ^/old$ - "
                + "[CO=session:abc:example.test:30:/app:true:true]\n");

        RewriteRule rule = config.getRules()[0];
        assertTrue(rule.isCookie());
        assertEquals("session", rule.getCookieName());
        assertEquals("abc", rule.getCookieValue());
        assertEquals("example.test", rule.getCookieDomain());
        assertEquals(30, rule.getCookieLifetime());
        assertEquals("/app", rule.getCookiePath());
        assertTrue(rule.isCookieSecure());
        assertTrue(rule.isCookieHttpOnly());
    }

    @Test
    void parsesMultipleEnvironmentFlags() {
        RewriteConfig config = build("RewriteRule ^/old$ - [E=one:1,E=two:value]\n");

        RewriteRule rule = config.getRules()[0];
        assertTrue(rule.isEnv());
        assertEquals(2, rule.getEnvSize());
        assertEquals("one", rule.getEnvName(0));
        assertEquals("1", rule.getEnvValue(0));
        assertEquals("two", rule.getEnvName(1));
        assertEquals("value", rule.getEnvValue(1));
    }

    @Test
    void shortNocaseFlagMakesRuleCaseInsensitive() {
        RewriteConfig config = build("RewriteRule ^/ITEM$ /new [NC]\n");

        assertTrue(config.getRules()[0].isNocase());
    }

    @Test
    void shortNoescapeFlagSetsNoescape() {
        RewriteConfig config = build("RewriteRule ^/old$ /new [NE]\n");

        assertTrue(config.getRules()[0].isNoescape());
    }

    @Test
    void parsesRewriteMapAndUsesItInSubstitution() throws Exception {
        FixedRewriteMap.reset();
        RewriteConfig config = build("RewriteMap numbers " + FixedRewriteMap.class.getName() + " seed\n"
                + "RewriteRule ^/number$ /value/${numbers:one|fallback} [L]\n");

        RewriteMap map = config.getMaps().get("numbers");
        assertNotNull(map);
        assertEquals("seed", FixedRewriteMap.parameters);
        IdentifierResolver resolver = new IdentifierResolver();
        assertEquals("/value/1", config.getRules()[0].evaluate("/number", resolver).toString());
    }

    @Test
    void unknownDirectiveIsRejected() {
        assertThrows(IllegalArgumentException.class, () -> build("NotADirective value\n"));
    }

    @Test
    void incompleteCondAndRuleDirectivesAreRejected() {
        assertThrows(IllegalArgumentException.class, () -> build("RewriteCond %{HTTP_HOST}\n"));
        assertThrows(IllegalArgumentException.class, () -> build("RewriteRule ^/old$\n"));
    }

    @Test
    void unknownConditionFlagIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> build("RewriteCond %{HTTP_HOST} ^www [BOGUS]\nRewriteRule ^/old$ /new\n"));
    }

    @Test
    void unknownRuleFlagIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> build("RewriteRule ^/old$ /new [BOGUS]\n"));
    }

    @Test
    void incompleteCookieAndEnvFlagsAreRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> build("RewriteRule ^/old$ /new [CO=onlyName]\n"));
        assertThrows(IllegalArgumentException.class,
                () -> build("RewriteRule ^/old$ /new [E=onlyName]\n"));
        assertThrows(IllegalArgumentException.class,
                () -> build("RewriteRule ^/old$ /new [E=name:]\n"));
    }

    @Test
    void unknownMapClassIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> build("RewriteMap bad no.such.RewriteMapClass\n"));
    }

    @Test
    void incompleteMapDirectiveIsRejected() {
        assertThrows(IllegalArgumentException.class, () -> build("RewriteMap name\n"));
    }

    @Test
    void configStringRoundTripsConditionsAndRules() {
        RewriteConfig config = build(""
                + "RewriteCond %{HTTP_HOST} ^example [NC]\n"
                + "RewriteRule ^/old$ /new [L]\n");

        assertEquals("RewriteCond %{HTTP_HOST} ^example\r\n"
                + "RewriteRule ^/old$ /new\r\n\r\n", config.toString());
    }

    private static RewriteConfig build(String contents) {
        return RewriteConfigFactory.build(new ByteArrayInputStream(contents.getBytes(StandardCharsets.UTF_8)));
    }

    public static final class FixedRewriteMap implements RewriteMap {
        static String parameters;
        static final List<String> LOOKUPS = new ArrayList<>();

        static void reset() {
            parameters = null;
            LOOKUPS.clear();
        }

        @Override
        public String setParameters(String params) {
            parameters = params;
            return null;
        }

        @Override
        public String lookup(String key) {
            LOOKUPS.add(key);
            return "one".equals(key) ? "1" : null;
        }
    }

    private static final class IdentifierResolver extends Resolver {
        @Override
        public String resolve(String key) {
            return key;
        }

        @Override
        public String resolveSsl(String key) {
            return null;
        }

        @Override
        public String resolveHttp(String key) {
            return null;
        }

        @Override
        public boolean resolveResource(int type, String name) {
            return false;
        }
    }
}

package io.undertow.servlet.compat.rewrite;

import org.junit.jupiter.api.Test;

import java.util.Collections;
