package io.undertow.servlet.compat.rewrite;

import io.undertow.Handlers;
import io.undertow.Undertow;
import io.undertow.server.HttpServerExchange;
import io.undertow.server.handlers.PathHandler;
import io.undertow.server.handlers.resource.FileResourceManager;
import io.undertow.servlet.Servlets;
import io.undertow.servlet.api.DeploymentInfo;
import io.undertow.servlet.api.DeploymentManager;
import io.undertow.servlet.api.ServletContainer;
import io.undertow.servlet.api.ServletInfo;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.net.HttpURLConnection;
import java.net.InetSocketAddress;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class RewriteHandlerTest {

    private static final String CONTEXT_PATH = "/app";

    private static final String RULES = ""
            + "RewriteRule ^/last-old$ /last-new [L]\n"
            + "RewriteRule ^/last-new$ /last-bad [L]\n"
            + "RewriteRule ^/next-a$ /next-b [N]\n"
            + "RewriteRule ^/next-b$ /next-done [L]\n"
            + "RewriteRule ^/skip$ /skip-target [S=1]\n"
            + "RewriteRule ^/skip-target$ /skip-bad [L]\n"
            + "RewriteRule ^/skip-target$ /skip-done [L]\n"
            + "RewriteRule ^/chain-open$ /chain-open-target [C]\n"
            + "RewriteRule ^/never$ /chain-bad [L]\n"
            + "RewriteRule ^/chain-closed$ /chain-closed-target [L]\n"
            + "RewriteRule ^/qsa$ /qsa-target?from=rule [QSA,L]\n"
            + "RewriteRule ^/rewrite$ /rewritten [L]\n"
            + "RewriteRule ^/redir$ /redir-target [R=301,L]\n"
            + "RewriteRule ^/temp$ /temporary [R,L]\n"
            + "RewriteRule ^/forbidden$ - [F]\n"
            + "RewriteRule ^/gone$ - [G]\n"
            + "RewriteRule ^/attrs$ - [E=rewritten:yes,E=path:%{REQUEST_PATH},CO=seen:cookie-value,T=text/plain,L]\n";

    @TempDir
    Path tempDir;

    private Undertow server;
    private DeploymentManager deploymentManager;
    private String baseUrl;

    @BeforeEach
    void startServer() throws Exception {
        RewriteConfig config = RewriteConfigFactory.build(
                new java.io.ByteArrayInputStream(RULES.getBytes(StandardCharsets.UTF_8)));
        DeploymentInfo deploymentInfo = Servlets.deployment()
                .setClassLoader(RewriteHandlerTest.class.getClassLoader())
                .setContextPath(CONTEXT_PATH)
                .setDeploymentName("rewrite-handler-test.war")
                .setResourceManager(new FileResourceManager(tempDir.toFile(), 0))
                .addServlet(new ServletInfo("probe", ProbeServlet.class).addMapping("/"))
                .addOuterHandlerChainWrapper(next -> new RewriteHandler(config, next));

        ServletContainer container = Servlets.newContainer();
        deploymentManager = container.addDeployment(deploymentInfo);
        deploymentManager.deploy();
        PathHandler pathHandler = Handlers.path().addPrefixPath(CONTEXT_PATH, deploymentManager.start());

        server = Undertow.builder()
                .addHttpListener(0, "127.0.0.1")
                .setHandler(pathHandler)
                .build();
        server.start();

        InetSocketAddress address = (InetSocketAddress) server.getListenerInfo().get(0).getAddress();
        baseUrl = "http://127.0.0.1:" + address.getPort();
    }

    @AfterEach
    void stopServer() throws Exception {
        if (server != null) {
            server.stop();
        }
        if (deploymentManager != null) {
            if (deploymentManager.getState() == DeploymentManager.State.STARTED) {
                deploymentManager.stop();
            }
            if (deploymentManager.getState() != DeploymentManager.State.UNDEPLOYED) {
                deploymentManager.undeploy();
            }
        }
    }

    @Test
    void emptyOrNullRuleSetDelegatesWithoutServletContext() throws Exception {
        AtomicInteger invocations = new AtomicInteger();
        io.undertow.server.HttpHandler next = exchange -> invocations.incrementAndGet();
        HttpServerExchange exchange = new HttpServerExchange(null);

        new RewriteHandler(new RewriteConfig(new RewriteRule[0], Collections.emptyMap()), next).handleRequest(exchange);
        new RewriteHandler(new RewriteConfig(null, Collections.emptyMap()), next).handleRequest(exchange);

        assertEquals(2, invocations.get());
    }

    @Test
    void unmatchedRequestReachesServletWithOriginalRequestState() throws Exception {
        Response response = get("/plain");

        assertEquals(200, response.status, response.body);
        assertBodyLine(response.body, "uri=", "/app/plain");
        assertBodyLine(response.body, "servletPath=", "/plain");
        assertBodyLine(response.body, "query=", "null");
        assertNull(response.location);
    }

    @Test
    void internalRewriteChangesRequestPathAndLastStopsLaterRules() throws Exception {
        Response rewritten = get("/rewrite");
        assertEquals(200, rewritten.status, rewritten.body);
        assertBodyLine(rewritten.body, "uri=", "/app/rewritten");
        assertBodyLine(rewritten.body, "servletPath=", "/rewritten");

        Response last = get("/last-old");
        assertEquals(200, last.status, last.body);
        assertBodyLine(last.body, "uri=", "/app/last-new");
        assertBodyLine(last.body, "servletPath=", "/last-new");
    }

    @Test
    void nextFlagRestartsRuleProcessingAndSkipSkipsFollowingRule() throws Exception {
        Response next = get("/next-a");
        assertEquals(200, next.status, next.body);
        assertBodyLine(next.body, "uri=", "/app/next-done");

        Response skip = get("/skip");
        assertEquals(200, skip.status, skip.body);
        assertBodyLine(skip.body, "uri=", "/app/skip-done");
    }

    @Test
    void chainFlagSkipsChainedRulesAfterMissButContinuesAtNextUnchainedRule() throws Exception {
        Response open = get("/chain-open");
        assertEquals(200, open.status, open.body);
        assertBodyLine(open.body, "uri=", "/app/chain-open-target");

        Response closed = get("/chain-closed");
        assertEquals(200, closed.status, closed.body);
        assertBodyLine(closed.body, "uri=", "/app/chain-closed-target");
    }

    @Test
    void qsappendCombinesRewrittenAndOriginalQueryStrings() throws Exception {
        Response response = get("/qsa?x=1");

        assertEquals(200, response.status, response.body);
        assertBodyLine(response.body, "uri=", "/app/qsa-target");
        assertBodyLine(response.body, "query=", "from=rule&x=1");
    }

    @Test
    void defaultRedirectUsesFoundStatusAppendsQueryAndContextPath() throws Exception {
        Response response = get("/temp?x=1");

        assertEquals(302, response.status, response.body);
        assertTrue(response.location.endsWith("/app/temporary?x=1"), response.location);
    }

    @Test
    void configuredRedirectStatusIsSentToClient() throws Exception {
        Response response = get("/redir?x=1");

        assertTrue(response.location.endsWith("/app/redir-target?x=1"), response.location);
        assertEquals(301, response.status, response.body);
    }

    @Test
    void forbiddenAndGoneRulesTerminateWithExpectedStatusCodes() throws Exception {
        assertEquals(403, get("/forbidden").status);
        assertEquals(410, get("/gone").status);
    }

    @Test
    void envCookieAndTypeFlagsProduceObservableRequestAndResponseEffects() throws Exception {
        Response response = get("/attrs");

        assertEquals(200, response.status, response.body);
        assertBodyLine(response.body, "rewritten=", "yes");
        assertBodyLine(response.body, "path=", "/attrs");
        assertBodyLine(response.body, "contentType=", "text/plain");
        assertTrue(response.setCookie.contains("seen=cookie-value"), response.setCookie);
    }

    private Response get(String path) throws IOException {
        HttpURLConnection connection = (HttpURLConnection) new URL(baseUrl + CONTEXT_PATH + path).openConnection();
        connection.setInstanceFollowRedirects(false);
        connection.setRequestMethod("GET");
        connection.setRequestProperty("X-Test", "present");
        try {
            int status = connection.getResponseCode();
            InputStream stream = status >= 400 ? connection.getErrorStream() : connection.getInputStream();
            String body = stream == null ? "" : new String(stream.readAllBytes(), StandardCharsets.UTF_8);
            return new Response(status, body,
                    connection.getHeaderField("Location"), connection.getHeaderField("Set-Cookie"));
        } finally {
            connection.disconnect();
        }
    }

    private static void assertBodyLine(String body, String prefix, String expected) {
        assertTrue(body.lines().anyMatch(line -> line.equals(prefix + expected)),
                () -> "Expected line " + prefix + expected + " in response body:\n" + body);
    }

    private static final class Response {
        private final int status;
        private final String body;
        private final String location;
        private final String setCookie;

        private Response(int status, String body, String location, String setCookie) {
            this.status = status;
            this.body = body;
            this.location = location;
            this.setCookie = setCookie;
        }
    }

    public static class ProbeServlet extends HttpServlet {
        @Override
        protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
            response.setContentType("text/plain");
            PrintWriter writer = response.getWriter();
            writer.println("uri=" + request.getRequestURI());
            writer.println("servletPath=" + request.getServletPath());
            writer.println("pathInfo=" + request.getPathInfo());
            writer.println("query=" + request.getQueryString());
            writer.println("contentType=" + request.getContentType());
            writer.println("rewritten=" + request.getAttribute("rewritten"));
            writer.println("path=" + request.getAttribute("path"));
        }
    }
}

package io.undertow.servlet.compat.rewrite;

import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.regex.PatternSyntaxException;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class RewriteRuleTest {

    private static final Resolver RESOLVER = new StubResolver();

    @Test
    void matchingRuleExpandsCapturedBackReference() {
        RewriteRule rule = rule("^/old/(.*)$", "/new/$1");
        rule.parse(Collections.emptyMap());

        assertEquals("/new/item", rule.evaluate("/old/item", RESOLVER).toString());
    }

    @Test
    void nonMatchingRuleReturnsNull() {
        RewriteRule rule = rule("^/old$", "/new");
        rule.parse(Collections.emptyMap());

        assertNull(rule.evaluate("/different", RESOLVER));
    }

    @Test
    void dashSubstitutionLeavesUrlUnchanged() {
        RewriteRule rule = rule("^/same$", "-");
        rule.parse(Collections.emptyMap());
        CharSequence input = new StringBuilder("/same");

        CharSequence result = rule.evaluate(input, RESOLVER);

        assertSame(input, result);
    }

    @Test
    void allConditionsMustMatchByDefault() {
        RewriteRule rule = rule("^/item$", "/rewritten");
        rule.addCondition(condition("yes", "^yes$", false));
        rule.addCondition(condition("no", "^yes$", false));
        rule.parse(Collections.emptyMap());

        assertNull(rule.evaluate("/item", RESOLVER));
    }

    @Test
    void ornextAllowsALaterConditionToSatisfyTheRule() {
        RewriteRule rule = rule("^/item$", "/rewritten");
        rule.addCondition(condition("no", "^yes$", true));
        rule.addCondition(condition("yes", "^yes$", false));
        rule.parse(Collections.emptyMap());

        assertEquals("/rewritten", rule.evaluate("/item", RESOLVER).toString());
    }

    @Test
    void conditionCaptureCanBeInterpolatedIntoSubstitution() {
        RewriteRule rule = rule("^/item/(.*)$", "/target/%1");
        rule.addCondition(condition("$1", "^(\\w+)$", false));
        rule.parse(Collections.emptyMap());

        assertEquals("/target/detail", rule.evaluate("/item/detail", RESOLVER).toString());
    }

    @Test
    void nocaseMakesRulePatternCaseInsensitive() {
        RewriteRule rule = rule("^/ITEM$", "/rewritten");
        rule.setNocase(true);
        rule.parse(Collections.emptyMap());

        assertEquals("/rewritten", rule.evaluate("/item", RESOLVER).toString());
    }

    @Test
    void envValuesAreEvaluatedOnlyWhenRuleMatches() {
        RewriteRule rule = rule("^/item/(.*)$", "-");
        rule.setEnv(true);
        rule.addEnvName("rewritten");
        rule.addEnvValue("$1");
        rule.addEnvName("constant");
        rule.addEnvValue("value");
        rule.parse(Collections.emptyMap());

        assertNull(rule.evaluate("/not-an-item", RESOLVER));
        assertNull(rule.getEnvResult(0));
        assertNull(rule.getEnvResult(1));

        rule.evaluate("/item/value", RESOLVER);

        assertEquals("value", rule.getEnvResult(0));
        assertEquals("value", rule.getEnvResult(1));
        assertEquals(2, rule.getEnvSize());
    }

    @Test
    void cookieValueIsEvaluatedWhenRuleMatches() {
        RewriteRule rule = rule("^/item/(.*)$", "-");
        rule.setCookie(true);
        rule.setCookieName("seen");
        rule.setCookieValue("$1");
        rule.parse(Collections.emptyMap());

        rule.evaluate("/item/page", RESOLVER);

        assertEquals("page", rule.getCookieResult());
    }

    @Test
    void addConditionAppendsInOrderAndSetConditionsReplacesArray() {
        RewriteRule rule = new RewriteRule();
        RewriteCond first = condition("a", "a", false);
        RewriteCond second = condition("b", "b", false);

        rule.addCondition(first);
        rule.addCondition(second);
        assertArrayEquals(new RewriteCond[]{first, second}, rule.getConditions());

        rule.setConditions(new RewriteCond[]{second});
        assertArrayEquals(new RewriteCond[]{second}, rule.getConditions());
    }

    @Test
    void invalidPatternIsRejectedDuringParse() {
        RewriteRule rule = rule("(", "/replacement");

        assertThrows(PatternSyntaxException.class, () -> rule.parse(Collections.emptyMap()));
    }

    @Test
    void accessorsRoundTripRuleConfiguration() {
        RewriteRule rule = new RewriteRule();
        rule.setPatternString("^/old$");
        rule.setSubstitutionString("/new");
        rule.setChain(true);
        rule.setCookie(true);
        rule.setEnv(true);
        rule.setForbidden(true);
        rule.setGone(true);
        rule.setHost(true);
        rule.setLast(true);
        rule.setNext(true);
        rule.setNocase(true);
        rule.setNoescape(true);
        rule.setNosubreq(true);
        rule.setQsappend(true);
        rule.setRedirect(true);
        rule.setRedirectCode(308);
        rule.setSkip(2);
        rule.setType(true);
        rule.setTypeValue("text/plain");
        rule.setCookieName("name");
        rule.setCookieValue("value");
        rule.setCookieDomain("example.test");
        rule.setCookieLifetime(10);
        rule.setCookiePath("/app");
        rule.setCookieSecure(true);
        rule.setCookieHttpOnly(true);

        assertEquals("^/old$", rule.getPatternString());
        assertEquals("/new", rule.getSubstitutionString());
        assertTrue(rule.isChain());
        assertTrue(rule.isCookie());
        assertTrue(rule.isEnv());
        assertTrue(rule.isForbidden());
        assertTrue(rule.isGone());
        assertTrue(rule.isHost());
        assertTrue(rule.isLast());
        assertTrue(rule.isNext());
        assertTrue(rule.isNocase());
        assertTrue(rule.isNoescape());
        assertTrue(rule.isNosubreq());
        assertTrue(rule.isQsappend());
        assertTrue(rule.isRedirect());
        assertEquals(308, rule.getRedirectCode());
        assertEquals(2, rule.getSkip());
        assertTrue(rule.isType());
        assertEquals("text/plain", rule.getTypeValue());
        assertEquals("name", rule.getCookieName());
        assertEquals("value", rule.getCookieValue());
        assertEquals("example.test", rule.getCookieDomain());
        assertEquals(10, rule.getCookieLifetime());
        assertEquals("/app", rule.getCookiePath());
        assertTrue(rule.isCookieSecure());
        assertTrue(rule.isCookieHttpOnly());
    }

    @Test
    void stringRepresentationIncludesPatternAndSubstitution() {
        assertEquals("RewriteRule ^/old$ /new", rule("^/old$", "/new").toString());
    }

    private static RewriteRule rule(String pattern, String substitution) {
        RewriteRule rule = new RewriteRule();
        rule.setPatternString(pattern);
