package io.undertow.servlet.compat.rewrite;

import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class SubstitutionTest {

    private static final Resolver RESOLVER = new StubResolver();

    @Test
    void parsesAndEvaluatesStaticTextAndBackReferences() {
        Substitution substitution = substitution("/new/$1/condition-%1/%{REQUEST_URI}");
        substitution.parse(Collections.emptyMap());
        Matcher rule = Pattern.compile("^/old/(.*)$").matcher("/old/item");
        rule.matches();
        Matcher condition = Pattern.compile("^(.*)$").matcher("captured");
        condition.matches();

        assertEquals("/new/item/condition-captured//app/request", substitution.evaluate(rule, condition, RESOLVER));
    }

    @Test
    void expandsEveryServerVariableKind() {
        assertEquals("/app/request", parsed("%{REQUEST_URI}").evaluate(null, null, RESOLVER));
        assertEquals("environment", parsed("%{ENV:name}").evaluate(null, null, RESOLVER));
        assertEquals("secure", parsed("%{SSL:name}").evaluate(null, null, RESOLVER));
        assertEquals("header", parsed("%{HTTP:name}").evaluate(null, null, RESOLVER));
    }

    @Test
    void emptySubstitutionEvaluatesToEmptyString() {
        Substitution substitution = substitution("");
        substitution.parse(Collections.emptyMap());

        assertEquals("", substitution.evaluate(null, null, RESOLVER));
    }

    @Test
    void mapLookupUsesMappedValueWhenPresent() {
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("numbers", new FixedRewriteMap("one", "1"));
        Substitution substitution = substitution("${numbers:one}");
        substitution.parse(maps);

        assertEquals("1", substitution.evaluate(null, null, RESOLVER));
    }

    @Test
    void mapLookupUsesDefaultWhenMapReturnsNull() {
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("numbers", new FixedRewriteMap("one", "1"));
        Substitution substitution = substitution("before-${numbers:missing|fallback}-after");
        substitution.parse(maps);

        assertEquals("before-fallback-after", substitution.evaluate(null, null, RESOLVER));
    }

    @Test
    void mapWithoutDefaultReturnsNullWhenLookupFails() {
        Map<String, RewriteMap> maps = new HashMap<>();
        maps.put("numbers", new FixedRewriteMap("one", "1"));
        Substitution substitution = substitution("${numbers:missing}");
        substitution.parse(maps);

        assertEquals("null", substitution.evaluate(null, null, RESOLVER));
    }

    @Test
    void setSubIsVisibleThroughAccessor() {
        Substitution substitution = new Substitution();
        substitution.setSub("/target?value=$1");

        assertEquals("/target?value=$1", substitution.getSub());
    }

    @Test
    void trailingRuleBackReferenceMarkerIsRejected() {
        assertThrows(IllegalArgumentException.class, () -> substitution("/target/$").parse(Collections.emptyMap()));
    }

    @Test
    void trailingConditionBackReferenceMarkerIsRejected() {
        assertThrows(IllegalArgumentException.class, () -> substitution("/target/%").parse(Collections.emptyMap()));
    }

    @Test
    void unknownMapNameIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> substitution("${unknown:key}").parse(Collections.emptyMap()));
    }

    @Test
    void malformedMapExpressionIsRejected() {
        Map<String, RewriteMap> maps = Collections.singletonMap("m", new FixedRewriteMap("k", "v"));

        assertThrows(IllegalArgumentException.class, () -> substitution("${m:key").parse(maps));
        assertThrows(IllegalArgumentException.class, () -> substitution("${m-key}").parse(maps));
    }

    @Test
    void malformedServerVariableIsRejected() {
        assertThrows(IllegalArgumentException.class, () -> substitution("%{REQUEST_URI").parse(Collections.emptyMap()));
        assertThrows(IllegalArgumentException.class, () -> substitution("%{ENV:name").parse(Collections.emptyMap()));
    }

    @Test
    void unknownServerVariableTypeIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> substitution("%{UNKNOWN:name}").parse(Collections.emptyMap()));
    }

    private static Substitution parsed(String value) {
        Substitution substitution = substitution(value);
        substitution.parse(Collections.emptyMap());
        return substitution;
    }

    private static Substitution substitution(String value) {
        Substitution substitution = new Substitution();
        substitution.setSub(value);
        return substitution;
    }

    private static final class FixedRewriteMap implements RewriteMap {
        private final String key;
        private final String value;

        private FixedRewriteMap(String key, String value) {
            this.key = key;
            this.value = value;
        }

        @Override
        public String setParameters(String params) {
            return null;
        }

        @Override
        public String lookup(String lookupKey) {
            return key.equals(lookupKey) ? value : null;
        }
    }

    private static final class StubResolver extends Resolver {
        @Override
        public String resolve(String key) {
            return key.equals("REQUEST_URI") ? "/app/request" : null;
        }

        @Override
        public String resolveEnv(String key) {
            return "environment";
        }

        @Override
        public String resolveSsl(String key) {
            return "secure";
        }

        @Override
        public String resolveHttp(String key) {
            return "header";
        }

        @Override
        public boolean resolveResource(int type, String name) {
            return false;
        }
    }
}

package io.undertow.servlet.compat.rewrite;

import io.undertow.server.handlers.resource.Resource;
import io.undertow.server.handlers.resource.ResourceManager;
import io.undertow.servlet.api.Deployment;
import io.undertow.servlet.api.DeploymentInfo;
import io.undertow.servlet.handlers.ServletRequestContext;
import jakarta.servlet.ServletContext;
import jakarta.servlet.http.HttpServletRequest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class UndertowResolverTest {

    private static final String PROPERTY = "undertow.rewrite.resolver.env";

    @AfterEach
    void clearProperty() {
        System.clearProperty(PROPERTY);
    }

    @Test
    void resolvesHeadersAndRequestMetadata() {
        Map<String, String> headers = new HashMap<>();
        headers.put("user-agent", "JUnit");
        headers.put("referer", "https://ref.example/");
        headers.put("cookie", "a=b");
        headers.put("forwarded", "for=192.0.2.1");
        headers.put("host", "www.example.test:8443");
        headers.put("proxy-connection", "keep-alive");
        headers.put("accept", "text/plain");
        UndertowResolver resolver = resolver(request(headers, new HashMap<>()), emptyDeployment());

        assertEquals("JUnit", resolver.resolve("HTTP_USER_AGENT"));
        assertEquals("https://ref.example/", resolver.resolve("HTTP_REFERER"));
        assertEquals("a=b", resolver.resolve("HTTP_COOKIE"));
        assertEquals("for=192.0.2.1", resolver.resolve("HTTP_FORWARDED"));
        assertEquals("www.example.test", resolver.resolve("HTTP_HOST"));
        assertEquals("keep-alive", resolver.resolve("HTTP_PROXY_CONNECTION"));
        assertEquals("text/plain", resolver.resolve("HTTP_ACCEPT"));
        assertEquals("10.1.2.3", resolver.resolve("REMOTE_ADDR"));
        assertEquals("client.example.test", resolver.resolve("REMOTE_HOST"));
        assertEquals("4567", resolver.resolve("REMOTE_PORT"));
        assertEquals("alice", resolver.resolve("REMOTE_USER"));
        assertEquals("alice", resolver.resolve("REMOTE_IDENT"));
        assertEquals("GET", resolver.resolve("REQUEST_METHOD"));
        assertEquals("/docroot/index.jsp", resolver.resolve("SCRIPT_FILENAME"));
        assertEquals("/app", resolver.resolve("CONTEXT_PATH"));
        assertEquals("/index.jsp", resolver.resolve("SERVLET_PATH"));
        assertEquals("", resolver.resolve("PATH_INFO"));
        assertEquals("x=1", resolver.resolve("QUERY_STRING"));
        assertEquals("BASIC", resolver.resolve("AUTH_TYPE"));
        assertEquals("/docroot", resolver.resolve("DOCUMENT_ROOT"));
        assertEquals("server.example.test", resolver.resolve("SERVER_NAME"));
        assertEquals("127.0.0.1", resolver.resolve("SERVER_ADDR"));
        assertEquals("8080", resolver.resolve("SERVER_PORT"));
        assertEquals("HTTP/1.1", resolver.resolve("SERVER_PROTOCOL"));
        assertEquals("tomcat", resolver.resolve("SERVER_SOFTWARE"));
        assertEquals("GET /app/index.jsp HTTP/1.1", resolver.resolve("THE_REQUEST"));
        assertEquals("/app/index.jsp", resolver.resolve("REQUEST_URI"));
        assertEquals("/docroot/translated", resolver.resolve("REQUEST_FILENAME"));
        assertEquals("on", resolver.resolve("HTTPS"));
        assertNull(resolver.resolve("UNKNOWN_VARIABLE"));
    }

    @Test
    void nullHostHeaderResolvesToNull() {
        Map<String, String> headers = new HashMap<>();
        UndertowResolver resolver = resolver(request(headers, new HashMap<>()), emptyDeployment());

        assertNull(resolver.resolve("HTTP_HOST"));
    }

    @Test
    void resolveEnvPrefersRequestAttributeAndFallsBackToSystemProperty() {
        Map<String, Object> attributes = new HashMap<>();
        attributes.put("from.attribute", 123);
        UndertowResolver resolver = resolver(request(new HashMap<>(), attributes), emptyDeployment());
        System.setProperty(PROPERTY, "from.property");

        assertEquals("123", resolver.resolveEnv("from.attribute"));
        assertEquals("from.property", resolver.resolveEnv(PROPERTY));
        assertNull(resolver.resolveEnv("missing.env.value"));
    }

    @Test
    void resolveHttpReadsRequestHeaderAndSslIsNotImplemented() {
        Map<String, String> headers = new HashMap<>();
        headers.put("x-token", "abc");
        UndertowResolver resolver = resolver(request(headers, new HashMap<>()), emptyDeployment());

        assertEquals("abc", resolver.resolveHttp("x-token"));
        assertNull(resolver.resolveSsl("SSL_PROTOCOL"));
    }

    @Test
    void resourceLookupDistinguishesMissingPresentAndNonEmptyResources() {
        Map<String, Resource> resources = new HashMap<>();
        resources.put("/present.txt", resource(5));
        resources.put("/empty.txt", resource(0));
        UndertowResolver resolver = resolver(request(new HashMap<>(), new HashMap<>()),
                deploymentWithResources(resources));

        assertTrue(resolver.resolveResource(0, "/missing.txt"));
        assertFalse(resolver.resolveResource(0, "/present.txt"));
        assertTrue(resolver.resolveResource(1, "/present.txt"));
        assertFalse(resolver.resolveResource(1, "/missing.txt"));
        assertTrue(resolver.resolveResource(2, "/present.txt"));
        assertFalse(resolver.resolveResource(2, "/empty.txt"));
        assertFalse(resolver.resolveResource(99, "/present.txt"));
    }

    @Test
    void resourceManagerIoFailureIsWrappedInRuntimeException() {
        UndertowResolver resolver = resolver(request(new HashMap<>(), new HashMap<>()),
                deploymentWithFailingResources());

        RuntimeException exception = assertThrows(RuntimeException.class,
                () -> resolver.resolveResource(1, "/broken"));

        assertTrue(exception.getCause() instanceof IOException);
    }

    private static UndertowResolver resolver(HttpServletRequest request, Deployment deployment) {
        ServletRequestContext context = new ServletRequestContext(deployment, null, null, null);
        return new UndertowResolver(context, request);
    }

    private static Deployment emptyDeployment() {
        return deploymentWithResources(new HashMap<>());
    }

    private static Deployment deploymentWithResources(Map<String, Resource> resources) {
        return deploymentWithResourceManager(new ResourceManager() {
            @Override
            public Resource getResource(String path) {
                return resources.get(path);
            }

            @Override
            public boolean isResourceChangeListenerSupported() {
                return false;
            }

            @Override
            public void registerResourceChangeListener(io.undertow.server.handlers.resource.ResourceChangeListener listener) {
            }

            @Override
            public void removeResourceChangeListener(io.undertow.server.handlers.resource.ResourceChangeListener listener) {
            }

            @Override
            public void close() {
            }
        });
    }

    private static Deployment deploymentWithFailingResources() {
        return deploymentWithResourceManager(new ResourceManager() {
            @Override
            public Resource getResource(String path) throws IOException {
                throw new IOException("broken");
            }

            @Override
            public boolean isResourceChangeListenerSupported() {
                return false;
            }

            @Override
            public void registerResourceChangeListener(io.undertow.server.handlers.resource.ResourceChangeListener listener) {
            }

            @Override
            public void removeResourceChangeListener(io.undertow.server.handlers.resource.ResourceChangeListener listener) {
            }

            @Override
            public void close() {
            }
        });
    }

    private static Deployment deploymentWithResourceManager(ResourceManager resourceManager) {
        DeploymentInfo info = new DeploymentInfo();
        info.setResourceManager(resourceManager);
        return proxy(Deployment.class, (proxy, method, args) ->
                method.getName().equals("getDeploymentInfo") ? info : defaultValue(method.getReturnType()));
    }

    private static Resource resource(long length) {
        return proxy(Resource.class, (proxy, method, args) -> {
            if (method.getName().equals("getContentLength")) {
                return length;
            }
            return defaultValue(method.getReturnType());
        });
    }

    private static HttpServletRequest request(Map<String, String> headers, Map<String, Object> attributes) {
        ServletContext servletContext = proxy(ServletContext.class, (proxy, method, args) -> {
            if (method.getName().equals("getRealPath")) {
                String path = (String) args[0];
                return "/".equals(path) ? "/docroot" : "/docroot" + path;
            }
            return defaultValue(method.getReturnType());
        });
        return proxy(HttpServletRequest.class, (proxy, method, args) -> {
            switch (method.getName()) {
                case "getHeader":
                    return headers.get(((String) args[0]).toLowerCase(Locale.ROOT));
                case "getAttribute":
                    return attributes.get(args[0]);
                case "getServletContext":
                    return servletContext;
                case "getRemoteAddr":
                    return "10.1.2.3";
                case "getRemoteHost":
                    return "client.example.test";
                case "getRemotePort":
                    return 4567;
                case "getRemoteUser":
                    return "alice";
                case "getMethod":
                    return "GET";
                case "getServletPath":
                    return "/index.jsp";
                case "getPathInfo":
                    return null;
                case "getQueryString":
                    return "x=1";
                case "getContextPath":
                    return "/app";
                case "getAuthType":
                    return "BASIC";
                case "getLocalName":
                    return "server.example.test";
                case "getLocalAddr":
                    return "127.0.0.1";
                case "getLocalPort":
                    return 8080;
                case "getProtocol":
                    return "HTTP/1.1";
                case "getRequestURI":
                    return "/app/index.jsp";
                case "getPathTranslated":
                    return "/docroot/translated";
                case "isSecure":
                    return true;
                default:
                    return defaultValue(method.getReturnType());
            }
        });
    }

    @SuppressWarnings("unchecked")
    private static <T> T proxy(Class<T> type, InvocationHandler handler) {
        return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, handler);
    }

    private static Object defaultValue(Class<?> type) {
        if (!type.isPrimitive()) {
            return null;
        }
        if (type == boolean.class) {
            return false;
        }
        if (type == char.class) {
            return '\0';
        }
        if (type == byte.class) {
            return (byte) 0;
        }
        if (type == short.class) {
            return (short) 0;
        }
        if (type == int.class) {
            return 0;
        }
        if (type == long.class) {
            return 0L;
        }
        if (type == float.class) {
            return 0F;
        }
        if (type == double.class) {
            return 0D;
        }
        return null;
    }
}

