                BooleanEndpoint.class, target);
        AnnotatedEndpointTestSupport.SessionFixture fixture = AnnotatedEndpointTestSupport.newSession(
                endpoint.endpoint, Map.of());

        endpoint.endpoint.onOpen(fixture.session, EmptyEndpointConfig.INSTANCE);
        whole(fixture.session, boolean.class).onMessage(Boolean.TRUE);

        assertTrue(target.value);
    }

    @Test
    void customTextDecodedPayloadIsRegisteredUnderItsDecodedType() throws Exception {
        EncodingFactory encodingFactory = decodedFactory(CustomPayload.class, false);
        Encoding encoding = encodingFactory.createEncoding(EmptyEndpointConfig.INSTANCE);
        CustomTextEndpoint target = new CustomTextEndpoint();
        AnnotatedEndpointTestSupport.EndpointFixture endpoint = AnnotatedEndpointTestSupport.endpointWithHandle(
                CustomTextEndpoint.class, target, encodingFactory, Collections.emptySet());
        AnnotatedEndpointTestSupport.SessionFixture fixture = AnnotatedEndpointTestSupport.newSession(
                endpoint.endpoint, Map.of(), encoding);

        endpoint.endpoint.onOpen(fixture.session, EmptyEndpointConfig.INSTANCE);
        CustomPayload payload = new CustomPayload("decoded");
        whole(fixture.session, CustomPayload.class).onMessage(payload);

        assertEquals(payload, target.message);
    }

    @Test
    void customBinaryDecodedPayloadIsRegisteredUnderItsDecodedType() throws Exception {
        EncodingFactory encodingFactory = decodedFactory(CustomPayload.class, true);
        Encoding encoding = encodingFactory.createEncoding(EmptyEndpointConfig.INSTANCE);
        CustomBinaryEndpoint target = new CustomBinaryEndpoint();
        AnnotatedEndpointTestSupport.EndpointFixture endpoint = AnnotatedEndpointTestSupport.endpointWithHandle(
                CustomBinaryEndpoint.class, target, encodingFactory, Collections.emptySet());
        AnnotatedEndpointTestSupport.SessionFixture fixture = AnnotatedEndpointTestSupport.newSession(
                endpoint.endpoint, Map.of(), encoding);

        endpoint.endpoint.onOpen(fixture.session, EmptyEndpointConfig.INSTANCE);
        CustomPayload payload = new CustomPayload("decoded binary");
        whole(fixture.session, CustomPayload.class).onMessage(payload);

        assertEquals(payload, target.message);
    }

    @Test
    void exceptionsFromMessageHandlersAreForwardedToOnError() throws Exception {
        ThrowingMessageEndpoint target = new ThrowingMessageEndpoint();
        AnnotatedEndpointTestSupport.EndpointFixture endpoint = AnnotatedEndpointTestSupport.endpointWithHandle(
                ThrowingMessageEndpoint.class, target);
        AnnotatedEndpointTestSupport.SessionFixture fixture = AnnotatedEndpointTestSupport.newSession(
                endpoint.endpoint, Map.of());

        endpoint.endpoint.onOpen(fixture.session, EmptyEndpointConfig.INSTANCE);
        whole(fixture.session, String.class).onMessage("bad");

        assertEquals(1, target.errorCalls);
        assertEquals("bad message", target.failure.getMessage());
    }

    @SuppressWarnings("unchecked")
    private static <T> MessageHandler.Whole<T> whole(UndertowSession session, Class<T> type) {
        MessageHandler handler = onlyHandler(session);
        assertTrue(handler instanceof MessageHandler.Whole, "Expected a whole message handler for " + type);
        return (MessageHandler.Whole<T>) handler;
    }

    @SuppressWarnings("unchecked")
    private static <T> MessageHandler.Partial<T> partial(UndertowSession session, Class<T> type) {
        MessageHandler handler = onlyHandler(session);
        assertTrue(handler instanceof MessageHandler.Partial, "Expected a partial message handler for " + type);
        return (MessageHandler.Partial<T>) handler;
    }

    private static MessageHandler onlyHandler(UndertowSession session) {
        Set<MessageHandler> handlers = session.getMessageHandlers();
        assertEquals(1, handlers.size());
        return handlers.iterator().next();
    }

    private static EncodingFactory decodedFactory(Class<?> type, boolean binary) {
        Map<Class<?>, List<InstanceFactory<? extends Encoder>>> binaryEncoders = Collections.emptyMap();
        Map<Class<?>, List<InstanceFactory<? extends Encoder>>> textEncoders = Collections.emptyMap();
        Map<Class<?>, List<InstanceFactory<? extends Decoder>>> binaryDecoders = Collections.emptyMap();
        Map<Class<?>, List<InstanceFactory<? extends Decoder>>> textDecoders = Collections.emptyMap();
        Map<Class<?>, List<InstanceFactory<? extends Decoder>>> decoders = new HashMap<>();
        decoders.put(type, Collections.emptyList());
        if (binary) {
            binaryDecoders = decoders;
        } else {
            textDecoders = decoders;
        }
        return new EncodingFactory(binaryEncoders, binaryDecoders, textEncoders, textDecoders);
    }

    public static class WholeTextEndpoint {
        String message;

        @OnMessage(maxMessageSize = 1024)
        public void message(String message) {
            this.message = message;
        }
    }

    public static class WholeByteArrayEndpoint {
        byte[] message;

        @OnMessage(maxMessageSize = 2048)
        public void message(byte[] message) {
            this.message = message;
        }
    }

    public static class WholeByteBufferEndpoint {
        ByteBuffer message;

        @OnMessage
        public void message(ByteBuffer message) {
            this.message = message;
        }
    }

    public static class PartialTextEndpoint {
        final StringBuilder message = new StringBuilder();
        boolean firstLast;
        boolean secondLast;
        int calls;

        @OnMessage
        public void message(String fragment, boolean last) {
            message.append(fragment);
            if (calls++ == 0) {
                firstLast = last;
            } else {
                secondLast = last;
            }
        }
    }

    public static class PartialBinaryEndpoint {
        int size;
        boolean firstLast;
        boolean secondLast;
        int calls;

        @OnMessage
        public void message(byte[] fragment, boolean last) {
            size += fragment.length;
            if (calls++ == 0) {
                firstLast = last;
            } else {
                secondLast = last;
            }
        }
    }

    public static class ReaderEndpoint {
        String message;

        @OnMessage
        public void message(Reader reader) throws IOException {
            StringBuilder builder = new StringBuilder();
            char[] buffer = new char[32];
            int read;
            while ((read = reader.read(buffer)) != -1) {
                builder.append(buffer, 0, read);
            }
            message = builder.toString();
        }
    }

    public static class InputStreamEndpoint {
        byte[] message;

        @OnMessage
        public void message(InputStream stream) throws IOException {
            message = stream.readAllBytes();
        }
    }

    public static class PongEndpoint {
        PongMessage message;

        @OnMessage
        public void message(PongMessage message) {
            this.message = message;
        }
    }

    public static class BoundMessageEndpoint {
        String message;
        String id;
        Session session;

        @OnMessage
        public void message(String message, Session session, @PathParam("id") String id) {
            this.message = message;
            this.session = session;
            this.id = id;
        }
    }

    public static class BooleanEndpoint {
        boolean value;

        @OnMessage
        public void message(boolean value) {
            this.value = value;
        }
    }

    public static class CustomPayload {
        final String value;

        CustomPayload(String value) {
            this.value = value;
        }
    }

    public static class CustomTextEndpoint {
        CustomPayload message;

        @OnMessage
        public void message(CustomPayload message) {
            this.message = message;
        }
    }

    public static class CustomBinaryEndpoint {
        CustomPayload message;

        @OnMessage
        public void message(CustomPayload message) {
            this.message = message;
        }
    }

    public static class ThrowingMessageEndpoint {
        Throwable failure;
        int errorCalls;

        @OnMessage
        public void message(String message) {
            throw new IllegalStateException("bad message");
        }

        @OnError
        public void error(Throwable failure) {
            this.failure = failure;
            errorCalls++;
        }
    }
}

package io.undertow.websockets.jsr.annotated;

import static org.easymock.EasyMock.anyObject;
import static org.easymock.EasyMock.createMock;
import static org.easymock.EasyMock.expect;
import static org.easymock.EasyMock.expectLastCall;
import static org.easymock.EasyMock.replay;

import java.net.URI;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.Executor;

import io.undertow.servlet.api.InstanceHandle;
import io.undertow.websockets.core.WebSocketChannel;
import io.undertow.websockets.jsr.Encoding;
import io.undertow.websockets.jsr.EncodingFactory;
import io.undertow.websockets.jsr.EndpointSessionHandler;
import io.undertow.websockets.jsr.ServerWebSocketContainer;
import io.undertow.websockets.jsr.SessionContainer;
import io.undertow.websockets.jsr.UndertowSession;
import jakarta.websocket.Endpoint;
import jakarta.websocket.EndpointConfig;
import org.easymock.EasyMock;
import org.xnio.ChannelListener;
import org.xnio.XnioIoThread;

/**
 * Builds a real {@link UndertowSession} around mocked I/O collaborators.  The endpoint code only
 * needs the session's in-memory handler registry, path parameters and container dispatch hook,
 * so the network-facing channel can remain a controlled boundary.
 */
final class AnnotatedEndpointTestSupport {

    private AnnotatedEndpointTestSupport() {
    }

    static final class RecordingInstanceHandle<T> implements InstanceHandle<T> {
        private final T instance;
        int releaseCount;

        RecordingInstanceHandle(T instance) {
            this.instance = instance;
        }

        @Override
        public T getInstance() {
            return instance;
        }

        @Override
        public void release() {
            releaseCount++;
        }
    }

    static final class EndpointFixture {
        final AnnotatedEndpoint endpoint;
        final RecordingInstanceHandle<Object> handle;

        private EndpointFixture(AnnotatedEndpoint endpoint, RecordingInstanceHandle<Object> handle) {
            this.endpoint = endpoint;
            this.handle = handle;
        }
    }

    static final class SessionFixture {
        final ServerWebSocketContainer container;
        final XnioIoThread ioThread;
        final UndertowSession session;

        private SessionFixture(ServerWebSocketContainer container, XnioIoThread ioThread, UndertowSession session) {
            this.container = container;
            this.ioThread = ioThread;
            this.session = session;
        }
    }

    static SessionFixture newSession(AnnotatedEndpoint endpoint, Map<String, String> pathParameters) {
        return newSession(endpoint, pathParameters, EncodingFactory.DEFAULT.createEncoding(EmptyEndpointConfig.INSTANCE));
    }

    static SessionFixture newSession(AnnotatedEndpoint endpoint, Map<String, String> pathParameters, Encoding encoding) {
        try {
        WebSocketChannel channel = createMock(WebSocketChannel.class);
        @SuppressWarnings("unchecked")
        ChannelListener.Setter<WebSocketChannel> receiveSetter = createMock(ChannelListener.Setter.class);
        XnioIoThread ioThread = createMock(XnioIoThread.class);
        ServerWebSocketContainer container = createMock(ServerWebSocketContainer.class);

        expect(channel.getReceiveSetter()).andReturn(receiveSetter);
        receiveSetter.set(anyObject(ChannelListener.class));
        expectLastCall().once();
        channel.addCloseTask(anyObject(ChannelListener.class));
        expectLastCall().once();
        expect(channel.getIoThread()).andReturn(ioThread).anyTimes();
        expect(container.isDispatchToWorker()).andReturn(false).anyTimes();
        container.invokeEndpointMethod(anyObject(Executor.class), anyObject(Runnable.class));
        expectLastCall().andAnswer(() -> {
            ((Runnable) EasyMock.getCurrentArguments()[1]).run();
            return null;
        }).anyTimes();
        replay(channel, receiveSetter, ioThread, container);

        @SuppressWarnings("unchecked")
        InstanceHandle<Endpoint> endpointHandle = (InstanceHandle<Endpoint>) (InstanceHandle<?>) new RecordingInstanceHandle<>(endpoint);
        Map<String, String> paths = pathParameters == null ? Collections.emptyMap() : new HashMap<>(pathParameters);
        java.lang.reflect.Constructor<UndertowSession> constructor = UndertowSession.class.getDeclaredConstructor(
                WebSocketChannel.class, URI.class, Map.class, Map.class, EndpointSessionHandler.class,
                java.security.Principal.class, InstanceHandle.class, EndpointConfig.class, String.class,
                Encoding.class, SessionContainer.class, String.class, java.util.List.class,
                io.undertow.websockets.client.WebSocketClient.ConnectionBuilder.class);
        constructor.setAccessible(true);
        UndertowSession session = constructor.newInstance(
                channel,
                URI.create("ws://localhost/test"),
                paths,
                Collections.emptyMap(),
                new EndpointSessionHandler(container),
                null,
                endpointHandle,
                EmptyEndpointConfig.INSTANCE,
                null,
                encoding,
                new SessionContainer(),
                null,
                Collections.emptyList(),
                null);
        return new SessionFixture(container, ioThread, session);
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("Could not construct test session", e);
        }
    }

    static AnnotatedEndpoint endpoint(Class<?> endpointClass, Object target) throws Exception {
        return endpointWithHandle(endpointClass, target, EncodingFactory.DEFAULT, Collections.emptySet()).endpoint;
    }

    static EndpointFixture endpointWithHandle(Class<?> endpointClass, Object target) throws Exception {
        return endpointWithHandle(endpointClass, target, EncodingFactory.DEFAULT, Collections.emptySet());
    }

    static EndpointFixture endpointWithHandle(Class<?> endpointClass, Object target,
            EncodingFactory encodingFactory, Set<String> paths) throws Exception {
        AnnotatedEndpointFactory factory = AnnotatedEndpointFactory.create(endpointClass, encodingFactory, paths);
        RecordingInstanceHandle<Object> handle = new RecordingInstanceHandle<>(target);
        return new EndpointFixture(factory.createInstance(handle), handle);
    }
}

package io.undertow.websockets.jsr.annotated;

import static org.easymock.EasyMock.createMock;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.lang.reflect.Method;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

import jakarta.websocket.DeploymentException;
import jakarta.websocket.Session;
import org.junit.jupiter.api.Test;

class BoundMethodTest {

    @Test
    void exposesMetadataAndBindsValuesByParameterType() throws Exception {
        Method method = Target.class.getDeclaredMethod("capture", Session.class, String.class, int.class);
        Session session = createMock(Session.class);
        BoundMethod boundMethod = new BoundMethod(method, String.class, true, 4096L,
                new ValueParameter(0, Session.class),
                new ValueParameter(1, String.class),
                new ValueParameter(2, int.class));
        Target target = new Target();

        Map<Class<?>, Object> values = new HashMap<>();
        values.put(Session.class, session);
        values.put(String.class, "hello");
        values.put(int.class, 17);
        Object result = boundMethod.invoke(target, values);

        assertEquals("hello:17", result);
        assertSame(session, target.session);
        assertEquals("hello", target.text);
        assertEquals(17, target.number);
        assertEquals(String.class, boundMethod.getMessageType());
        assertTrue(boundMethod.isDecoderRequired());
        assertEquals(4096L, boundMethod.getMaxMessageSize());
        assertTrue(boundMethod.hasParameterType(Session.class));
        assertTrue(boundMethod.hasParameterType(String.class));
        assertTrue(boundMethod.hasParameterType(int.class));
        assertFalse(boundMethod.hasParameterType(long.class));
    }

    @Test
    void refusesToLeaveMethodParametersUnbound() throws Exception {
        Method method = Target.class.getDeclaredMethod("capture", Session.class, String.class, int.class);

        assertThrows(DeploymentException.class,
                () -> new BoundMethod(method, null, false, 0L, new ValueParameter(0, Session.class)));
    }

    @Test
    void unwrapsCheckedAndRuntimeExceptionsFromTheInvokedMethod() throws Exception {
        BoundMethod checked = new BoundMethod(
                Target.class.getDeclaredMethod("throwChecked"), null, false, 0L);
        BoundMethod runtime = new BoundMethod(
                Target.class.getDeclaredMethod("throwRuntime"), null, false, 0L);

        IOException checkedFailure = assertThrows(IOException.class,
                () -> checked.invoke(new Target(), Collections.emptyMap()));
        assertEquals("checked", checkedFailure.getMessage());
        IllegalStateException runtimeFailure = assertThrows(IllegalStateException.class,
                () -> runtime.invoke(new Target(), Collections.emptyMap()));
        assertEquals("runtime", runtimeFailure.getMessage());
    }

    @Test
    void wrapsErrorsRaisedByTheInvokedMethod() throws Exception {
        BoundMethod method = new BoundMethod(Target.class.getDeclaredMethod("throwError"), null, false, 0L);

        RuntimeException failure = assertThrows(RuntimeException.class,
                () -> method.invoke(new Target(), Collections.emptyMap()));

        assertInstanceOf(AssertionError.class, failure.getCause());
        assertEquals("error", failure.getCause().getMessage());
    }

    @Test
    void recognisesCompatibleOverridesOnly() throws Exception {
        Method childTransform = Child.class.getDeclaredMethod("transform", String.class);
        BoundMethod child = new BoundMethod(childTransform, null, false, 0L,
                new ValueParameter(0, String.class));

        assertTrue(child.overrides(Parent.class.getDeclaredMethod("transform", String.class)));
        assertFalse(child.overrides(Parent.class.getDeclaredMethod("other", String.class)));
        assertFalse(child.overrides(Other.class.getDeclaredMethod("transform", Integer.class)));

        BoundMethod zeroArgument = new BoundMethod(
                Child.class.getDeclaredMethod("zero"), null, false, 0L);
        assertTrue(zeroArgument.overrides(Parent.class.getDeclaredMethod("zero")));
        assertFalse(zeroArgument.overrides(Parent.class.getDeclaredMethod("transform", String.class)));
    }

    private static final class ValueParameter implements BoundParameter {
        private final int position;
        private final Class<?> type;

        private ValueParameter(int position, Class<?> type) {
            this.position = position;
            this.type = type;
        }

        @Override
        public Set<Integer> positions() {
            return Set.of(position);
        }

        @Override
        public void populate(Object[] params, Map<Class<?>, Object> values) {
            params[position] = values.get(type);
        }

        @Override
        public Class<?> getType() {
            return type;
        }
    }

    public static class Target {
        Session session;
        String text;
        int number;

        public String capture(Session session, String text, int number) {
            this.session = session;
            this.text = text;
            this.number = number;
            return text + ":" + number;
        }

        public void throwChecked() throws IOException {
            throw new IOException("checked");
        }

        public void throwRuntime() {
            throw new IllegalStateException("runtime");
        }

        public void throwError() {
            throw new AssertionError("error");
        }
    }

    public static class Parent {
        public Number transform(String value) {
            return 1;
        }

        public void other(String value) {
        }

        public void zero() {
        }
    }

    public static class Child extends Parent {
        @Override
        public Integer transform(String value) {
            return 2;
        }

        @Override
        public void zero() {
        }
    }

    public static class Other {
        public Number transform(Integer value) {
            return 3;
        }
    }
}

package io.undertow.websockets.jsr.annotated;

import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Map;

import jakarta.websocket.EndpointConfig;
import org.junit.jupiter.api.Test;

class DecoderUtilsTest {

    @Test
    void returnsNoDecodersForAnyType() {
        assertNull(DecoderUtils.getDecodersForType(String.class, EmptyEndpointConfig.INSTANCE));
        assertNull(DecoderUtils.getDecodersForType(Integer.class, EmptyEndpointConfig.INSTANCE));
        assertNull(DecoderUtils.getDecodersForType(DecoderUtilsTest.class, new EmptyConfig()));
    }

    @Test
    void emptyEndpointConfigAlwaysProvidesEmptyImmutableCollections() {
        EndpointConfig config = EmptyEndpointConfig.INSTANCE;

        assertTrue(config.getEncoders().isEmpty());
        assertTrue(config.getDecoders().isEmpty());
        assertTrue(config.getUserProperties().isEmpty());
        assertThrows(UnsupportedOperationException.class,
                () -> config.getEncoders().add(null));
        assertThrows(UnsupportedOperationException.class,
                () -> config.getDecoders().add(null));
        assertThrows(UnsupportedOperationException.class,
                () -> config.getUserProperties().put("key", "value"));
    }

    private static final class EmptyConfig implements EndpointConfig {
        @Override
        public java.util.List<Class<? extends jakarta.websocket.Encoder>> getEncoders() {
            return java.util.Collections.emptyList();
        }

        @Override
        public java.util.List<Class<? extends jakarta.websocket.Decoder>> getDecoders() {
            return java.util.Collections.emptyList();
        }

        @Override
        public Map<String, Object> getUserProperties() {
            return java.util.Collections.emptyMap();
        }
    }
}
